/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180306-3","meetingId":"h30-c-budget","date":"2018年3月6日","dateIso":"2018-03-06","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を179件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年度品川区一般会計予算","agenda":"平成３０年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"私からは、６５ページ、八潮北公園スケートボート場についてお伺いしたいと思います。昨年１１月１９日にオープニングセレモニーがございました。やはりこのスケートボード場については、前々からいろいろ要望があったということで、スケートボード場が開園して、スケートボード愛好者が今現在も利用し、盛り上がっているというところであります。そこでお聞きいたします。よろしくお願いします。","respondent":"池田スポーツ推進課長","answer":"１１月２０日にオープンいたしました八潮北公園のスケートボード場の登録者の人数です。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問","question":"区内の小学生が５９人、中学生が９３人に対して区外の中学生以上の人数が１６５名いるということで、今現在、区外の方が倍近いのですけれども、区外からスケートボードの愛好者が来ているということについてのお考えといいますか、その辺のところをお聞きしたいと思います。","respondent":"池田スポーツ推進課長","answer":"区外の方については、中学生以上の方で１６５人が登録されているところですけれども、主に大田区の方、それと、ちょっと遠いところでは川崎の方ということで、八潮北公園に近い区外、都外の方が登録されていまして、皆さん。","voiceIndex":6,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そこで、日本スケートボード協会のほうにも要望というか、お願いで、貸出をぜひしていただければと考えています。これは要望で終わらせたいと思います。今月、３月２４日の土曜日、１３時から１５時まで、定員が先着２０名ということで、同じくスケートボード教室をやると思うのですけれども、今現在の、申し込み状況をお知らせいただければと思います。","respondent":"溝口公園課長","answer":"３月２４日の応募状況です。これにつきましては、まだ開始したばかりで、これから多分、応募人数が増えていくような形で予想しております。若干名、問い合わせと応募があるというふうには聞いておりますが、まだ人数等は確定をしていないというのが現状です。","voiceIndex":8,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そこで、江東区の有明で行われる競技の中にはＢＭＸがあるのです。ほかの委員からも第１回定例会の一般質問のときにＢＭＸの使用について要望がありましたが、品川区として、今後どういうふうに問題点を改善していくのか、そこをお知らせいただきたいと思います。","respondent":"溝口公園課長","answer":"ただ、やはり当初、スケートボード場としてオープンしておりますので、スケートボードの利用者をしっかり守りながら、さらなるスケートボード場の活用、そういったものも行っていきたいというふうに考えているところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"区広報では３月１１日の日曜日、９時から１１時まで、この八潮北公園は休場するということですけれども、これはＢＭＸの利用に関する要望を踏まえて、約２時間休場して、施設の調査をするということで、具体的な調査内容を教えていただければと思います。","respondent":"溝口公園課長","answer":"そういったところで、実際に試走していただいて、危険な箇所がないか、また、当施設が今のまま安全に使えるのか、そういった視点で確認をしていただきたいというふうに考えているところです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からも、ただいま質疑がありました６５ページの八潮北公園スケートボード場について、それと１１５ページの生活支援付住まい確保事業補助金についてお伺いいたします。八潮北公園は、今、状況を伺いましたが、利用状況についてお伺いしたいと思います。土日、また平日、それぞれ利用されていると思うのですが、特に平日の利用状況がどうなのかということをお伺いしたいと思います。","respondent":"池田スポーツ推進課長、溝口公園課長","answer":"１１月からこれまでの利用状況ですけれども、平日で８４５人、休日については４３４人ということで、１週間は５日間が平日で、２日間が土日ということを考えますと、この２日間の休日で４３４人ということで、平日の８４５人に比べると。今回の試走にあたりご協力いただく団体になりますが、公益財団法人日本自転車競技連盟の方からご紹介いただきまして、一般社団法人全日本フリースタイルＢＭＸ連盟にご協力をいただいて試走をするものです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"新妻委員","kind":"提案","question":"あわせて、高齢者の住宅支援補助金では、厚生労働省の「低所得高齢者等住まい・生活支援モデル事業」の補助金や、また、これまで我が会派が求めてきた居住支援協議会を立ち上げることで、受け取ることができる国土交通省の「重層的住宅セーフティネット構築支援事業」の補助金があると思いますが、それらを使わない事業とした理由をお伺いしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"国土交通省の新しいセーフティネットの補助金につきましては、住宅の確保と生活支援がリンクしていないなどの課題がございまして、活用は難しいと考えております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"これから開始される新規事業の内容について少し教えていただきたいと思います。","respondent":"松山高齢者地域支援課長","answer":"新規事業の内容ですが、低所得者の高齢者が品川区でいつまでも暮らし続けるために、対象としましては、住宅あっ旋の対象のうち、特に支援が必要な方を社会福祉協議会の生活支援サービスで、長く居宅生活を送っていただけるということが目的の事業です。","voiceIndex":20,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"今既に品川区の事業で行われております高齢者地域支援課の住宅あっ旋事業があります。条件としては、低所得者支援のため、年間収入が約２５７万円以下の方が利用できるというものですが、この事業は、この新規事業の中に吸収されると考えていいのでしょうか。そうなると、新規事業の対象も年間収入が２５７万円以下の方となるのかを確認させていただきたいと思います。","respondent":"松山高齢者地域支援課長","answer":"１つは、高齢者住宅のあっ旋制度で解決される方は、そちらをお使いいただきます。一方で、入居後の生活にご不安がある方については、新規事業でということになります。ですから、所得に関しましても、委員ご指摘のとおり２５７万２,０００円以内の方が対象になってあります。","voiceIndex":22,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後新しく始まる事業は、生活支援の見守り等も含まれております。高齢者の中には、所得が２５７万円以上でもお困りの方もいらっしゃるので、この所得については、今後、ご検討をいただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"７５ページの情報公開手数料に関してお伺いしたいと思います。この理念、私も本当に好きな文章であります。一方区では、情報公開手数料として３００円いただく、受益者負担ということで品川区はずっと手数料を徴収しておりますけれども、これは区民憲章に反していると思うのです。私は無料にするべきだと考えていますが、その点についての答弁をお願いしたいと思います。この点についての考えも伺います。","respondent":"中元広報広聴課長","answer":"情報公開手数料のお尋ねです。こちらにつきましては、従来から申し上げているところですが、やはり一部の事業者からの大量請求によるところが大きいところですので、やはり受益者負担という考え方で、こちらは手数料をいただいているという考え方です。","voiceIndex":26,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"区民憲章の理念に反しているのではないかというところの答弁がありませんでしたので、ぜひお願いしたいと思います。この間、大量請求を理由としているのであれば、どの程度そういう状況があったのかの実態もあわせて伺いたいと思います。そういう点についての認識を伺いたいと思います。","respondent":"中元広報広聴課長","answer":"やはり区の職員が大量請求の対応をするに当たりましては、時間を必要とするところですし、区職員が本来行うべき職務に専念できるということも大切なことかと思っているところです。","voiceIndex":28,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"今のところは手数料もお払いするわけです。そういう方向に考え方を変えるべきだと思っています。これは区民の知る権利を品川区としてどういうふうに捉えるかという問題だと思いますので、ぜひ改めるべきだということを強調したいと思います。そしてどこに何を目的で行ったのか、どのような内容で懇談なり要請をされたのかということについて、なぜ保管をしていないのか、その辺について伺いたいと思います。","respondent":"中村都市計画課長","answer":"タウンミーティングに関連してですけれども、一般論になり恐縮ですけれども、個人も含めた区の全ての動きについて公開するための文書を残しているというものではございません。","voiceIndex":30,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、これはきちんと保管をするべきだと考えていますし、ぜひ改善をしていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"私からは、４８ページの特別区たばこ税、３０億６,２８０万円、６３ページの歴史館使用料について、時間がありましたら、１４７ページの歴史館講座等について伺いたいと思います。４８ページの特別区たばこ税についてです。小中学校や医療機関、福祉施設、官公庁について、どのように整備されているのか、あわせて伺いたいと思います。","respondent":"川島健康課長","answer":"今、委員ご説明のございました現行の健康増進法につきましても、多数の者が利用する施設を管理する者は、受動喫煙を防止するために必要な措置を講ずるよう努めなければならないという趣旨がありますので。","voiceIndex":34,"id":"exchange-015"},{"speaker":"松永委員","kind":"質問","question":"先ほどお答えいただいた中で、本区の庁舎にある喫煙所について伺いたいと思うのですけれども、現在、区役所内に何カ所ぐらい喫煙場所が設置されているのか、そして今後どのように変わってしまうのか、その流れについて伺いたいと思います。禁煙外来についてなのですけれども、利用者はどのくらいおられるのかと思いまして、その点についてもあわせて伺います。","respondent":"川島健康課長、立川経理課長","answer":"禁煙外来助成の利用状況ですが、今、３０数件ほどご登録いただいております。３月にもう少し頑張って予算額の５０人にいけばいいなというふうに考えているところです。現在、庁舎の喫煙スペースにつきましては、７カ所あります。今後ですが、国の法律の関係、東京都の条例の関係、その辺、詳しくわかり次第、適切に対応していきたいというふうに考えているところです。","voiceIndex":36,"id":"exchange-016"},{"speaker":"松永委員","kind":"質問・要望","question":"喫煙される方から、残してほしいという意見もありまして、財政としても、約３０億円、昨年よりも６,０００万円ぐらい減っているのですけれども、３０億円という大きなお金です。撤去するかどうかは今後の流れなど、いろいろありますが、ぜひご検討いただきたいと強く要望します。","respondent":"菅生活安全担当課長","answer":"たばこの路面表示シートにつきましては２種類ございまして、地域美化推進地区と、それ以外と２種類というふうになっております。路面に表示してありますシート、これは地面に張ってありますので、どうしても劣化してしまいます。","voiceIndex":39,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"わかりました。エリアについてなのですけれども、例えばステッカー１枚について何m2とかではなくて、その近辺は吸ってはいけないということなのか、その辺についてお聞きしたかったのですけれども、よろしくお願いします。","respondent":"菅生活安全担当課長","answer":"路上喫煙防止条例につきましては、これは区内全域が歩行禁止ということで努力義務になっております。その中でも大井町ですとか五反田ですとか大崎ですとか、そういった５地区につきましては路上喫煙禁止・地域美化推進地区ということで、全く吸ってはいけないです。","voiceIndex":41,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"６３ページの歴史館使用料についてです。初めに、利用者について質問をいたします。書院４５回、講堂５回、来館者６,２４０人とありますが、それぞれ現在どの程度の利用をされているのかお知らせください。","respondent":"鈴木文化観光課長","answer":"講堂につきましては、主に歴史館の事業で使うことが多くなっておりますので、こちらのほうも件数としては約６０件で３,０００人ほどの方が利用されている状況です。","voiceIndex":43,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"書院については、年間５０から６０というふうな形でおっしゃっていたので、この予算書の４５回というのは、もうちょっと目標を高くしていただければと思うのですけれども、その辺について伺います。そこで、この茶室についてですが、いつごろ利用が可能になるのでしょうか。今後、復旧される予定はあるのでしょうか。お知らせください。","respondent":"鈴木文化観光課長","answer":"今年度、改修について関係部署と検討したのですが、実際に使えるようにするためには、建て直すのと同じぐらい経費がかかるということが判明いたしまして、今後、歴史館自体の機能強化、それから観光での活用等も踏まえまして、今後。","voiceIndex":45,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"お茶に関しては、私もやっているものですから、いろいろとありまして、よろしくお願いします。今後、東京２０２０大会を控える中で、多くの方が来館されることも予想されます。改めてアクセス方法や駐輪場の整備、駐輪場といってもシェアサイクルも進んでいる中で、そうした整備について、今後、ニーズに合った施策を進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-021"},{"speaker":"藤原委員","kind":"確認","question":"これも確認なのですけれども、社会福祉法人に対しては利子をとっていないのでしょうか。私は違和感がありますが、お考えをお伺いします。これは平成２９年度もというか、平成２９年度はいつも以上に余剰金が出るという見込みだったからこういうふうにしていると思うのですけれども、そのことの確認と、どうして毎年このように膨大な繰越金を計上しなければいけないのかお伺いします。","respondent":"寺嶋高齢者福祉課長、山崎商業・ものづくり課長、秋山財政課長","answer":"社会福祉法人の貸付金返還金につきましては、主に福祉施設の建設に伴う資金を用意する必要があるということで。商店街のほうは１０％の支出ということになりますが、補助率が大きいので、商店街に対する先ほどの補助金が出るまでのつなぎということで、今回。これにつきましては、前年まで２５億円ということで予算を立てておりましたけれども、１つは、財政規模がこのところ。","voiceIndex":51,"id":"exchange-022"},{"speaker":"藤原委員","kind":"確認","question":"今回、歳入全体で１００億円増加していますね。よく見ると、繰入金が１００億円増えているのです。これは年度の終わりに基金からそれほど出さないで、さらに積み増す結果になるのでしょうか。そのことの確認をしたいと思います。","respondent":"秋山財政課長","answer":"この差額は、歳入を大きく見込むというのは、なかなか財政的にはしがたいものがあります。入ってこないものを入ってくるというふうに予算を立てることはできませんので、歳入はどうしても堅めに見ざるを得ない。","voiceIndex":58,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"最後に、８３ページの国保でお伺いしたいのですけれども、昨日も国保について伺ったのですが、国保の制度が変わるということで、国保の課題があると思うのですが、この課題に対する制度改革があると思うのですが、その辺は区がどういうふうに考えているか教えてください。","respondent":"三ッ橋国保医療年金課長","answer":"引き続き、皆様へのご協力、ご理解を進めてまいります。区といたしましては、区民の皆様の健康や命を守る国民健康保険制度の運営につきまして、国保医療年金課一丸となって、あと１カ月に迫ってまいります平成３０年度からの国保制度改革を進めてまいります。","voiceIndex":60,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に要望になってしまうのですが、この国民皆保険制度は、誇れる制度だと考えています。高額医療も含めて、国民皆保険制度を、守っていっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-025"},{"speaker":"吉田委員","kind":"確認","question":"私からは、８５ページ、１３款国庫支出金、１項国庫負担金、７節障害児通所給付費、８８ページ、１３款国庫支出金、２項国庫補助金、２目民生費補助金、１節地域生活支援事業、１３６ページの１７款繰入金、１項基金繰入金、８目財政調整基金繰入金について伺います。先に財政調整基金の繰り入れの考え方について伺います。財政調整基金条例を確認させていただきました。基金の設置は大変もっともと考えます。","respondent":"秋山財政課長","answer":"財調基金のお問い合わせです。財調基金は、委員ご指摘のとおり、年度間の財源の不均衡の調整ということを設置の目的に掲げしています。","voiceIndex":64,"id":"exchange-026"},{"speaker":"吉田委員","kind":"意見","question":"２０１０年度以降、毎年、特別区民税はずっとプラスの補正をしております。しかし、そのときには、政策的な目的を明確にして、こういう状況で、これに必要だからこういうふうに充てるということが、項目ではなくて政策的なものが明示されて、それでこの委員会の議論に付して、そうやってみんなで決めていくべきなのではないかと思いますが、その点について、もう１回お考えをお聞かせください。","respondent":"秋山財政課長","answer":"一般財源も全て充当事業ということを示すとなりますと、これはなかなか難しいものであり、あまり現実的ではないかなというふうに考えてあります。","voiceIndex":66,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、そのときには目的を明確にして、きちんと政策的な議論がされるべきではないかということを申し上げておりますので、これについては要望にとどめますが、ぜひ明確な基準を持っていていただきたいというふうに思います。次に行きます。８５ページの障害児通所給付費です。報酬改正の趣旨、新旧の表を見たのですけれども、私、理解できなくて、その趣旨をどのように理解したらいいのかも教えてください。","respondent":"中山障害者福祉課長","answer":"２点のお尋ねです。放課後等デイサービスの仕組みがどういうふうに変わるか、報酬体系がどう変わるかです。１点目は、やはり障害の重いお子さんに対して支援を手厚くするということがあります。","voiceIndex":68,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"利用者の中で障害の重い子を重視するというのは理解できるのですけれども、これを利用している子どもたちのことを考えると、軽度だからこういうケアがなくて済むと考えるのは、ちょっと難しいのではないかということと、それから、環境の変化に対応するのが難しいお子さんが多いということを考えると、利用者への急な影響は避けたほうがいいと思うのですが、その辺のことはどのようにお考えか教えてください。","respondent":"中山障害者福祉課長","answer":"今回、放課後等デイサービスを国が報酬改正するに当たっては、より専門的な対応をできる、やはり療育目的ということになりますので、それをきっちりやる事業所に手厚くというのが本来の趣旨だというふうに聞いております。","voiceIndex":70,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。伺いたいのは、このにじのひろばについて、これは伝聞によるもので調べていないのでごめんなさい、その範囲で聞かせていただきますが、年間の登録料があるというふうに聞いたのですけれども、それは事実なのでしょうか。登録料という名目で伺ったのですけれども、あるとしたら、どういう性格のものなのか、それも教えてください。","respondent":"中山障害者福祉課長","answer":"年間登録料といたしましては、月々の請求の郵券、それから銀行振替の手数料、それの１２カ月分を中心としつつ、あとはシステムの運営のための経費を乗せさせていただき、現在、年間の登録料ということで５,０００円をいただいているところです。","voiceIndex":72,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"登録料というものなのでしょうか。ちょっと今のお話で伺うと、登録というのと何か、利用料に上乗せになるものなのか、登録という文字の意味、いわゆる名称の問題ですけれども、どうなのかなというふうに思います。","respondent":"中山障害者福祉課長","answer":"そのほか低所得の方が月額４,６００円、それ以外の方も３万７,２００円を上限としています。","voiceIndex":74,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、課長もおっしゃいましたけれども、やはり登録料というより事務手数料と考えると、軽減措置が必要な方たちにとって、毎年５,０００円ということですから、大きい負担ではないかというふうに思います。必要なものは自己負担ということがあってもいいかと思うのですけれども、その辺の全体の整合性をぜひ考えていただきたいと思うのですけれども、その点について見解を伺います。","respondent":"中山障害者福祉課長","answer":"この年間登録料につきましては、少しこちらのほうでも考えさせていただいて、所得制限に応じたいただき方になるのか、料金の見直しなのか、検討させていただければと考えています。","voiceIndex":76,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。さっき名称の問題と言いましたけれども、やはり、多くの方は名称で意味を受け取るので、もし利用料ということであれば、きちんと軽減措置の中に入れていただきたいし、どういう意味の料金なのかということは、ぜひ明示して皆さんに納得して使っていただけるようにしていただきたいと思います。これは要望です。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-033"},{"speaker":"横山委員","kind":"質問","question":"私からは、８９ページ、シティプロモーション推進経費ほか３事業、１１７ページの予防接種費ほか６事業、１５７ページ、議会運営費についてをお伺いいたします。１点目は、予防接種費ほか６事業についてお伺いいたします。出生時から何歳くらいまで管理可能なのでしょうか。定期予防接種だけではなく、任意予防接種やインフルエンザなどの流行時期に合わせて管理することはできますでしょうか。","respondent":"舟木保健予防課長","answer":"今回、新たにアプリを導入することで、接種のスケジュールの自動調整やプッシュ通知等の機能が追加されます。導入時期につきましては、４月以降、詳細を検討してまいりますので、７月ごろを予定しております。","voiceIndex":80,"id":"exchange-034"},{"speaker":"横山委員","kind":"質問","question":"接種間隔の間違いですとか、接種忘れを防止するなどの効果が期待できると考えているのですけれども、予防接種とともに、生後４カ月児、１歳６カ月児、３歳児の健康診査ですとか、歯科健診などの健康診査のスケジュールなどもあわせて管理していくようになるかと思うのですけれども、こちらの一括の管理の仕方について、もしありましたら、区のお考えをお聞かせください。","respondent":"舟木保健予防課長","answer":"健診スケジュールの一括管理についてですが、現在、乳幼児健診などにつきましては、事前に個別通知を発送しております。予防接種、健診と合わせたその後の健康管理につきましては、担当している所管とも今後このアプリについて相談してまいりたいと思います。","voiceIndex":82,"id":"exchange-035"},{"speaker":"横山委員","kind":"質問","question":"２点目は、シティプロモーション推進経費ほか３事業についてお伺いいたします。第５５回の宣伝会議賞に品川区が参加しているかと思います。こちら、受賞したキャッチフレーズと応募総数、一次通過作品は、コピーライターの方ですとか、プロの広告クリエーターの方が審査されていると聞いておりますけれども、こちらの一次通過作品数をお聞かせください。","respondent":"木村報道・プロモーション担当課長","answer":"応募総数が７,０５５作品、うち一次審査を通過した作品が８２です。それから、いわゆる品川区賞としてこちらのほうで授賞を決めたキャッチフレーズですが、「東京の玄関というよりリビング」というようなキャッチフレーズを選ばせていただきました。","voiceIndex":84,"id":"exchange-036"},{"speaker":"横山委員","kind":"意見","question":"こちらは私も『宣伝会議』で見せていただいたのですけれども、課題のところに、「いっぱいある魅力をイマイチ伝えきれていない品川区をエッジの効いたインパクトのある表現でアピールしてください。面白ければ少々自虐的でも破天荒でも構いません。もし少々自虐的ですとか、破天荒、エッジの効いた思わず笑顔を誘うようなキャッチコピーがありましたら、一部ご紹介ください。","respondent":"木村報道・プロモーション担当課長","answer":"「私たちは住み続けたいと答えなかった人が１割もいたことを反省しています」、これはどちらかというと、ちょっと自虐的なほうになると思います。それから、「東京に疲れました。品川区に帰ります」というようなこともありました。","voiceIndex":86,"id":"exchange-037"},{"speaker":"横山委員","kind":"質問","question":"「わ！しながわ」のキャッチコピーやロゴと合わせて、受賞作品は、今後、どのように展開していくのでしょうか。品川区シティプロモーションの特設サイトに、一次通過作品の掲載をすることによって、応募者の方々にさらに品川区の魅力を感じていただくことで、繰り返し発信をしていただく機会にもなると考えますが、いかがでしょうか。続けて３点目も入ります。議会運営費についてお伺いいたします。","respondent":"木村報道・プロモーション担当課長、久保田区議会事務局長","answer":"ご提示いただきました特設サイトへの作品の掲載につきましても、４月以降になりますけれども、随時進めていきたいと考えております。もしこれに違反した場合の対応ですけれども、同じ規則の第７条に、規則違反者に対する措置ということで、「傍聴人がこの規則に違反したときは、委員長はこれを制止し、その命令に従わないときは。","voiceIndex":88,"id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"キャッチコピーの件については、ぜひ進めていただけたらと思います。傍聴規則のほう、ありがとうあります。品川区議会委員会傍聴規則の遵守を要望いたしますが、一言お願いします。","respondent":"久保田区議会事務局長","answer":"私ども、傍聴される方には、傍聴券をお渡しする際に、こういった規則を守ってくださいということをお願いしていますが、これからも徹底してやっていきたいと思います。","voiceIndex":91,"id":"exchange-039"},{"speaker":"つる委員","kind":"確認","question":"１５１ページ、公園駐車場運営事業納付金、１５７ページ、本会議場等バリアフリー化、８５ページ、児童扶養手当給付費について伺いたいと思います。納付金の件ですが、まず最初に確認で、この納付金が入る法令等の根拠、また仕組み、そして運営事業者がどこなのか、それを教えてください。","respondent":"溝口公園課長","answer":"これにつきましては、都市公園法第５条に、公園施設の設置管理許可という項目があります。この制度を使いまして、有償の運営を民間事業者に委託しているものです。実際、今現在、民間駐車場を運営しているのは、タイムズ２４株式会社が運営を行っているものです。","voiceIndex":94,"id":"exchange-040"},{"speaker":"つる委員","kind":"確認","question":"それで、この歳入に関連してなのですが、公園の維持管理にかかる経費、補助金等を除いた経費ですが、区の経費は、歳出を確認すると、一般財源として２０億６,０００万円余あるわけですが、細かく見ていくと、公園そのものよりも、それに付随するウエブの管理とか、その辺のお金も入っていたり、年度によっていろいろ変わってくる、トイレの改修等も入っていると思うのですが。","respondent":"溝口公園課長","answer":"委員ご指摘のように、予算を計上している２０億円余、さまざま改修等により、いろいろ変わってくるところはありますが、傷んでいるところ、そういったものを直しながら公園の維持管理に当たっているものですので、年間ですと、大体２０億円ぐらいが公園全体。","voiceIndex":96,"id":"exchange-041"},{"speaker":"つる委員","kind":"質問・要望","question":"そこで、国家戦略特別区域法の一部が改正されて、都市公園法の特例を活用して、既に品川区内にも保育園が設置されておりますけれども、先ほど冒頭でご答弁いただいた都市公園法に基づく駐車場以外で民間事業者が収益を上げる事業として取り組んでいることがあれば教えていただきたいと思います。しながわ区民公園内のレストランとか、そうしたものが挙げられると思うのですが、確認の意味で教えてください。","respondent":"溝口公園課長","answer":"そのほかにつきましては、公園内にある自動販売機の一部についても、こういった都市公園法の第５条の設置管理許可を活用して、実際、民間事業者が自動販売機を設置しているといったところもあります。","voiceIndex":98,"id":"exchange-042"},{"speaker":"つる委員","kind":"質問・要望","question":"区として同制度の活用についてのお考え等があれば教えていただきたいのと、また、活用に際しては、区の関係条例等の改正が必要になるのかどうかという点、公園の今後のあり方等も含めて教えていただければと思います。","respondent":"溝口公園課長","answer":"今回、施設を設置するに当たっては、公園施設の建蔽率、そういったところが条例で定まっておりますので、そういったところをどういう形に設定していくのか、そういったところの条例改正が場合によっては必要になってくると思いますので。","voiceIndex":100,"id":"exchange-043"},{"speaker":"つる委員","kind":"質問・要望","question":"法律を確認すると、管理許可の期間が１０年から２０年であるとか、面積については２％だったものが１０％増えて１２％になる、こういうふうにしていくと、条例改正が必要になってくるという理解をいたしました。韻松亭は今もありますけれども、そういった経緯がある。ちょうど平成３３年を目指して戸越公園内に体験型環境学習施設ができるわけです。","respondent":"溝口公園課長","answer":"さまざまな観点で、今回の都市公園法の改正に合わせて、さまざまな制度ができておりますので、今後、そういったものも含めてしっかりと公園のあり方については検討していきたいと思っているところです。","voiceIndex":102,"id":"exchange-044"},{"speaker":"つる委員","kind":"提案","question":"今、大きい部分でありましたけれども、細かい部分では、議会より２００９年ぐらいからネーミングライツの提案が各議員からされております。そこで、公園またトイレなどに対するネーミングライツについて、改めて提案をさせていただきたいのと、これまでの検討状況を教えていただければと思います。","respondent":"溝口公園課長","answer":"そういったことも含めて、今後、おもてなしトイレということでトイレ整備を進めておりますので、そういった中でネーミングライツの活用もしっかり検討していきたいと考えているところです。","voiceIndex":104,"id":"exchange-045"},{"speaker":"つる委員","kind":"質問","question":"今回はたまたま公園ということでありましたけれども、やはり自治体としてもしっかりと税外収入を得ていくということは、今後、法体系を含めて必要な観点の１つかなという部分で、非常に可能性のあるところかと思いまして質問させていただきました。本会議場等バリアフリー化でありますが、この中に議会棟５階のトイレ改修工事も含まれていると思いますが、どのように改修するのか教えてください。","respondent":"久保田区議会事務局長","answer":"本会議場等のバリアフリーですけれども、５階のトイレをだれでもトイレに改修する予定であります。","voiceIndex":106,"id":"exchange-046"},{"speaker":"つる委員","kind":"提案","question":"簡潔に答えていただいて、だれでもトイレへの改修は、非常にいいことかと思います。この前広便座というのは、オストメイトの方が便座に座った状態でパウチ処理ができる便座で、合理的配慮の観点でも、一般便所への設置拡大を進めるべきと私は思っておりますけれども、今回この議会棟の５階トイレの改修工事に合わせて、前広便座の設置をしたらどうかと提案させていただきたいと思いますが、いかがでしょうか。","respondent":"久保田区議会事務局長","answer":"委員からご提案のありましたこういった便座も含めまして検討の項目として入れまして、あと３階の本庁舎のトイレを参考にしながら、関係部署とこれから協議をして詳細を決めていきたいと考えております。","voiceIndex":108,"id":"exchange-047"},{"speaker":"つる委員","kind":"質問","question":"残りの時間で、児童扶養手当給付金について伺っていきたいと思います。国のほうでも法改正が進み、２０１９年度を目指して、隔月支給にしていくということでありますけれども、今回の当初予算の中に、２０１９年度に開始できるシステム改修費などの財源が確保されていますので、次々年度、確実に実施できるようになっているかどうかということを教えてください。","respondent":"廣田子ども家庭支援課長","answer":"取り込めない場合については、すぐに改修ができるよう平成３０年度中に調整をする予定です。","voiceIndex":110,"id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ２０１９年度にしっかりと対応ができるように、実際、当事者のお母様からもお声をいただいているところでありますので、また、実際に実施した後もしっかりとそうしたお声を窓口として受け取っていただいて、推進していただきたいと思います。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-049"},{"speaker":"筒井委員","kind":"提案","question":"りんかい線についてです。そして、私、ある会合で、天王洲アイルに来た人、区外の方だったのですけれども、何人かとお話しして、そうした方に天王洲アイルはどうですかといろいろお聞きしたのですけれども、やはりなかなか来ない、行かないというお答えでした。そこで品川区の水辺、天王洲アイルに来ていただくべく運賃の値下げをぜひ提案していただきたいのですけれども、区のご所見はいかがでしょうか。","respondent":"中村都市計画課長","answer":"そのような中で、鉄道事業者の料金に対する認識もあるというところで、今後、引き続き、料金についてご意見があるというのは、区のほうもお伝えはしていますが、料金の設定につきましては、なかなかやはり経営の方法や方針もあると思いますので。","voiceIndex":114,"id":"exchange-050"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひこの要望を東京臨海高速鉄道株式会社のほうにお伝えいただければと思います。特別区民税、今年の予算は補正予算を見て比べると控えめになっていると考えられますが、これはふるさと納税が原因だと考えていますけれども、確認として、今年度を含めた過去３年分の推移を確認したいと思います。確認としてお聞きいたします。よろしくお願いします。","respondent":"伊東税務課長、秋山財政課長","answer":"平成３０年度におきましては、減収額として１５億４,０００万円ほどを見込んでいるですので、それがどうしても影響してしまいまして、そのような数字になっているところです。その理由ですけれども、これは地方消費税は消費地に交付することが基本ですけれども、その基準を消費の実態に合わない基準に国が一方的に変えて、大都市部から地方への還流といいますか。","voiceIndex":116,"id":"exchange-051"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。１０年やっている、ふるさと納税は本当にうまくいっているのですかという話なのです。ぜひとも、今も特別区長会を通じて要望しているかと思われますけれども、さらに徹底して強く見直し、廃止、そうした抗議を行っていただきたいと考えております。やはり区民の方を巻き込んでＰＲを行っていただきたいと考えております。それについてご意見、ご所見はいかがでしょうか。","respondent":"秋山財政課長","answer":"これについては、都とも連携しながら、いわばこれは基本的な税の話ですので、区としても強力に主張していきたい、また、区民へのＰＲも、今後、いろいろなチャンネルを通じて行っていきたいというふうに思っています。","voiceIndex":119,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"７３ページの区営住宅、１３５ページの地所賃貸料、旧第一日野小学校跡地について伺います。区営住宅です。そこで質問いたします。２０００年の都区協議では、おおむね１００戸までの規模の団地を移管対象とし、元芝以外に区内４つの都営住宅が移管対象団地として挙げられましたが、移管を受けるべきだと思いますけれども、いかがでしょうか。対象となる４つの団地それぞれ伺いたいと思います。","respondent":"長尾住宅課長","answer":"そういった建設当時の経緯や今後の建て替えの時期の活用の方針など、そういったことを総合的に考慮して、慎重に検討する必要がある対象になっていると考えております。","voiceIndex":123,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"私は、人権保障の観点から、また、住み続けたいまちしながわと言うならば、区内の都営住宅は１戸も減らすべきではないと思います。移管を受けるべきです。元芝アパートの入居者には都がほかの都営住宅への移転を今後調整すると伺っているという答弁だけでした。伺いますけれども、これは区内で都営住宅戸数が減るのは問題ないという認識なのでしょうか。伺いたいと思います。","respondent":"長尾住宅課長","answer":"公営住宅につきましては、公益的な観点のもとで、都と区が役割を分担して実施している施策となっております。こういった観点から、都内の都営住宅戸数が変更になるものではない状況です。","voiceIndex":125,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"今住んでいる方が区内の都営住宅に移るということ自体は、万が一廃止になってしまった場合に、それは当然やるべきことだと思いますし、私が伺っているのは、住宅政策を預かる品川区として、区内の公営住宅である都営住宅の戸数が減るということについて問題と感じていないのですかと伺ったので、きちんとお答えください。","respondent":"長尾住宅課長","answer":"繰り返しになってしまいますが、都は都の役割のもと、公益的な観点に基づいて必要な公営住宅の建設・維持を行っていると伺っております。","voiceIndex":127,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"都の役割があると、都のやることだから区はあずかり知らないということだと私は思います。それは大問題ではないですか。区内で区民の方が入れる公営住宅の戸数が減ることに対して、何も問題意識を持たない、問題だと思わないというのは問題ではないのですか。もう一度伺います。","respondent":"長尾住宅課長","answer":"繰り返しになってしまいますが、都は都の役割のもとで都営住宅の建て替え、維持を行っており、区は区で区営住宅の維持管理、または必要なタイミングでの建て替え等を行っており、適切に公営住宅を供給していると考えております。","voiceIndex":129,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"都営住宅といった公営住宅があれば助かる、あるいは貧困から抜け出せる、あるいは生活保護の受給を申請する必要がなくなる方がたくさんいますから、これは認識を改めていただきたいと思います。区の建て替え時に複合施設として有効活用が可能であるという移管の条件は、これはおかしいのではないでしょうか。伺います。単独でも建て替えるべきだと思いますけれども、いかがでしょうか。","respondent":"長尾住宅課長","answer":"そういった観点からも、区営住宅の建て替え等におきましては、他の行政需要との関連性も見ながら、複合化や集約といったことを考えて建て替えについて検討するべきものと考えております。","voiceIndex":131,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"区民の生存権の住まいからの保障の観点から、区は区営住宅の増設と移管対象の都営住宅の移管を強く求めたいと思います。契約期限が来た際には速やかに返還していただく考えとの答弁もありましたけれども、その契約期限とは、議会にも住民にも約束していたおおむね８年という２０２０年９月６日のことなのか、それとも契約書上の２０２２年９月６日のことなのか、どちらなのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"区といたしましては、引き続き早期着手に向けて働きかけをしているといったところです。返還の部分につきましては、契約書上、平成３４年です。これは法的なところの最後のリミットといいますか、契約書上のリミットになります。","voiceIndex":133,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"議会と区民との約束は、おおむね８年、当時の委員会の議事録を見ても、８年、でも、契約書上は仕方がないので１０年にしましたということを言っていました。契約期限が来た際には速やかに返還していただく考えとの答弁が本会議でありましたけれども、それは２０２０年９月６日には返還を速やかにいただく考えはないということになったのでしょうか。お聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"こういった賃貸借、土地の貸し借りというところでは、行政も民間も同じでございまして、契約というものが法的な根拠です。そういった意味で言いますと、先ほど申しましたとおり、平成３４年の秋というのが法的なところのリミットというところで捉えてあります。","voiceIndex":135,"id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"法的なリミットは平成３４年９月６日ということなのですけれども、私が伺ったのは、地元の住民説明会でも、議会の委員会の審議の中でも説明されているとおり、２年間の暫定貸付をしているのです。ですから、それとあわせておおむね１０年、つまり、おおむね８年でということですが、しかし、契約書上は地上権などを主張されるかもしれない。どうでしょうか。","respondent":"柏原企画調整課長","answer":"契約内容の期間というところについてです。この第一日野小学校旧跡地を貸し付けることを、議会をはじめいろいろなところで説明、回答もさせていただいてきたところです。そういった中で、ＴＯＣのほうからおおむね８年というお話はありました。","voiceIndex":137,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"仮に２０２２年だとしても、これは、間に合わないのではないですか。今の時点で工事着手しても間に合わない。貸付の目的が宙に浮いた以上、速やかに返還を求めることを要請したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-061"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"本日は、８７ページの感染症予防費、感染症対策事業についてお伺いいたします。梅毒についてお伺いします。梅毒患者は２０１０年から増え出し、２０１４年ごろから急激に届出数が増加しています。昨年の予算特別委員会でも梅毒流行について注意を喚起し、区に対策を要望してきましたが、梅毒の流行は衰えるどころか拡大する一方です。現在の梅毒の大流行に対する区のご認識を伺いたいと思います。","respondent":"舟木保健予防課長","answer":"梅毒は性感染症の１つでもありますので、性感染症をみずからの問題と捉えて予防手段などを知ることや、感染が疑われた場合には、すぐに医療機関を受診するということなどの普及啓発が重要だと認識しております。","voiceIndex":141,"id":"exchange-062"},{"speaker":"鈴木（博）委員","kind":"意見","question":"梅毒は梅毒トレポネーマによる性感染症で、１９９６年の時点で世界中で１,２００万人が新しく感染したと推定されており、ＨＩＶ感染症と合併しながら世界中で流行が続いています。すなわち、昨年は数万人が実に梅毒に感染したと推定されているのです。なぜ梅毒が流行すると問題なのか、淋病とか性器クラミジアなど他の性感染症との違いを含めてご説明をお願いいたします。","respondent":"舟木保健予防課長","answer":"梅毒につきましては、症状が出てもすぐにおさまって、また出てくるというような形で、無症状になりながら進行してしまって、検査とか治療がおくれたりとか、無治療でそのまま経過してしまうと、脳や心臓などに重大な合併症を起こすことがあります。","voiceIndex":143,"id":"exchange-063"},{"speaker":"鈴木（博）委員","kind":"意見","question":"昔、コロンブスが西インド諸島の風土病であった梅毒をヨーロッパに持ち帰ってから、わずか２０年で梅毒は日本にも上陸しました。国立感染症研究所による７例の先天梅毒児を産んだ母親のインタビューの記録を見ると、全員、学校教育やメディア、雑誌、妊婦健診等のいずれの情報源からも妊娠中に気をつけるべき性感染症の情報を得ていなかったということでした。","respondent":"舟木保健予防課長","answer":"梅毒に対する対策についてです。現在、区におきましては、性感染症について、相談と検査を月１回、保健センターで毎月実施しております。","voiceIndex":145,"id":"exchange-064"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"梅毒が大流行している現在、区が先頭に立ってあらゆる予防策を行うことを強く要望いたしまして次の質問に移ります。次に、先天性風疹症候群対策についてお伺いいたします。妊娠を希望される夫婦間等に対する風疹抗体検査と予防接種の接種助成事業が平成３０年度も継続されることを高く評価いたします。平成２９年度の風疹抗体検査と予防接種の実施数は、現段階の集計ではいかがでしょうか。","respondent":"舟木保健予防課長","answer":"風疹抗体検査と予防接種の実施状況ですが、１月末までの実施状況ですが、抗体検査が８０２件、予防接種が４５４件となっておりまして、昨年度の実績と大きな増減はない状況です。","voiceIndex":147,"id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"昨年の一般質問において、風疹に感染する方を減らすために、大人への風疹予防接種事業に準じた対応を要望いたしました。今の実績をお聞きすると、昨年度とほとんど実績は横ばい、変わらないように感じますが、風疹に対する積極的な対策、対応は、何かお考えでしょうか。","respondent":"舟木保健予防課長","answer":"風疹につきましては、２０２０年度の風疹排除に向けて、現在、国を挙げて取り組んでいるところですので、まだこの事業の対象者の方で利用されていない方への周知については引き続き努めてまいりたいと思います。","voiceIndex":149,"id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"先天性風疹症候群が一刻も早く根絶されるように、一層の努力を要望して質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-067"},{"speaker":"木村委員","kind":"質問","question":"私は、１５７ページの中ほどより下にあります本会議場等バリアフリー化、１,９４６万円余からです。来年度予算として、１,９４６万円余が計上されており、第２回本会議と第３回本会議の間に工事を始めると言われております。先ほど、ほかの委員からバリアフリーの質問がありました。だれでもトイレの質問でしたが、バリアフリーはトイレだけなのでしょうか。お答えください。","respondent":"久保田区議会事務局長","answer":"本会議場のバリアフリーですけれども、だれでもトイレを５階に設置するほか、本会議場の演壇のところを車椅子対応にするということと、もう１つ、委員会室に、耳がちょっと聞こえにくい傍聴者のためヒアリング支援システムを入れるというものです。","voiceIndex":153,"id":"exchange-068"},{"speaker":"木村委員","kind":"質問","question":"本会議場と傍聴席のバリアフリーを行うということであります。車椅子の区民の皆さんが傍聴に来られることも十分考えられます。傍聴席をどのように変えていくのでしょうか。そして、区としては、バリアフリーをすることで、障害を持っている人や車椅子の区民の傍聴者が増えることを願っていると思いますけれども、それでよろしいでしょうか。","respondent":"久保田区議会事務局長","answer":"私の説明が足りませんで済みません。今回、議場のバリアフリーをするのは、本会議場の中の一般質問を行っています演壇のところを車椅子対応ができるように改修するというものです。","voiceIndex":155,"id":"exchange-069"},{"speaker":"木村委員","kind":"質問","question":"以前から思っていましたけれども、現職の議員の皆さんは元気でいらっしゃるから考えられませんけれども、これからひょっとして車椅子の方が立候補などということもあり得ます。現に、文京区や足立区、葛飾区には、車椅子を使う議員がいるそうです。これから本区にも車椅子を使用する議員の可能性も十分考え、改修していくことが必要だと思いますが、そう理解してよろしいでしょうか。","respondent":"久保田区議会事務局長","answer":"私どもは、委員おっしゃるように、障害者差別解消法等も施行されましたので、私ども、そういったことに基づきまして、本会議場の中もバリアフリー化を進めていくというものです。","voiceIndex":157,"id":"exchange-070"},{"speaker":"木村委員","kind":"質問・要望","question":"人は元気なときは感じないものですけれども、私自身も体を悪くして初めてあらゆるところに目がいくようになりました。あるとき、議場の段差に不安を感じて、議場の壁に手すりがあったら、自分の体を支えられるのでいいのになと思いました。議場の中も手を入れていただきたいと思いますけれども、いかがでしょうか。今以上にバリアフリーをお願いしたいのですが、いかがでしょうか。","respondent":"久保田区議会事務局長","answer":"議場内のバリアフリー化についてですが、私どもは、今、一般質問をする演壇のところをバリアフリー化ということで、あと、段差がありますので、その解消についてもいろいろ検討はしているのですが、角度が急になるということもありますので、そういった場合には。","voiceIndex":159,"id":"exchange-071"},{"speaker":"木村委員","kind":"質問","question":"先ほど言ったのですけれども、区役所の中、区民の皆さんが区役所にいろいろな手続をしにやってきますけれども、そういう中で、高齢化が進んでおりますので、そういう人たちのためにもバリアフリー化をお願いしたいと思うのですが、いかがでしょうか。","respondent":"立川経理課長","answer":"庁舎のバリアフリー化につきましては、不特定かつ多数の人が利用する施設ということで、国のほうで建築物移動等円滑化誘導基準という指針が出ておりまして、窓口業務を行う事務室に至るまでの扉の自動扉化、また、大型ベッドを備えた多機能便所設置など。","voiceIndex":161,"id":"exchange-072"},{"speaker":"木村委員","kind":"質問","question":"いい言葉が出ました。次に、その下にあります図書室運営費、３７８万円余ですけれども、運営費ということですが、３７８万円余のお金の使用目的は何でしょうか。議会棟の４階にある図書館のことと思いますけれども、そんなに使用されているようには見えないのですけれども、この３７８万円余はどのようなところに使われているのでしょうか。","respondent":"久保田区議会事務局長","answer":"一般にも開放していますが、一般の方の閲覧等につきましては、１桁台の数字ということで、利用はあまりないという現状です。","voiceIndex":163,"id":"exchange-073"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたしますけれども、年６回発行して、２,８４２万円余なので、６回で割りますと、１回大体４７０万円前後になります。品川区全体の戸数は、２月１日現在で２１万５,８００少々ということでありますから、２２万部を製作することと思いますけれども、余ったものはどのようなところに使われるのか。","respondent":"久保田区議会事務局長","answer":"区議会だよりの１回の発行部数は、２２万４,０００部です。このうち２２万部は全戸配布で、シルバー人材センターより各家庭に配布をさせていただいてあります。","voiceIndex":167,"id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、本日も区民相談の内容をもとに２点お伺いをしたいと思います。１つ目は（仮称）障害児者総合支援施設について、２つ目が、８９ページ、民生費補助金、母子・父子家庭自立支援給付金事業補助金で、離婚相談について伺います。離婚相談のほうから伺いたいと思います。その際いただいたご相談の中で、年金分割という制度をご存じでしょうかと、こういうことを聞かれました。","respondent":"三ッ橋国保医療年金課長","answer":"離婚時の年金分割ですけれども、制度としては、離婚した場合、お二人の婚姻期間中の厚生年金を分割いたしまして、それぞれ自分の年金とすることができる制度です。これには２つございまして、合意分割、そして３号分割というものがあります。","voiceIndex":170,"id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ただし、ここからが問題なのですけれども、これは自動的になるわけではなくて、離婚した日の翌日から２年間で請求の手続をしなければ、法の不知でいたずらに期間が経過してしまいますと、その請求権を失ってしまうということがあります。行政評価局に対する厚労省、日本年金機構の回答にありますように、品川区に対してこういう周知を依頼するような事務連絡とか通知等があったのかまず伺いたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"関東・甲信越年金機構からですけれども、国保医療年金課のほうに周知の依頼がございました。関連部署に周知するようにという依頼がございました。","voiceIndex":172,"id":"exchange-076"},{"speaker":"あくつ委員","kind":"意見","question":"婚姻中で離婚のご相談に訪れる子ども家庭支援課、それと、離婚届を提出する戸籍住民課、そして、離婚後の年金の相談や手続に訪れる国保医療年金課、そして離婚の相談等を受ける区民相談を担当する広報広聴課、実際にこういう区民の声も上がっておりますし、全国的な課題にもなっておりますので、この年金分割の制度について徹底した周知をお願いしたいのですが、それぞれご答弁をお願いいたします。","respondent":"廣田子ども家庭支援課長、提坂戸籍住民課長、中元広報広聴課長、三ッ橋国保医療年金課長","answer":"その他、窓口で、もし離婚した場合に、手当であるとか、どのようなサービスが受けられますかというご相談も少なからず受けておりますので。現在は年金分割については触れておりませんけれども、その中に年金分割についてもわかりやすいような形で簡潔にまとめたいと思いまして。引き続き、周知に努めてまいりたいと思います。今後また年金関連の依頼などがございましたら、関連部署に周知徹底してまいります。","voiceIndex":174,"id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問・要望","question":"パンフレットもありますので、対象になる方、ならない方がいらっしゃいますので、それについてはパンフレットを活用していただきたいと思います。１点だけ、先ほども家庭支援課のほうで、「ひとり親家庭のしおり」をつくっていらっしゃるのですが、ここについても、もし記載をできるのであればお願いしたいと思うのですが、いかがでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"毎年、「ひとり親家庭のしおり」につきましては５月に配布を予定しておりまして、もう編集が大分進んでおりますので、平成３０年度分に間に合えば平成３０年度分に掲載しますが、間に合わない場合には、平成３１年度にしおりに載せて。","voiceIndex":179,"id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問","question":"続きまして、（仮称）品川区立障害児者総合支援施設について伺います。アール・ブリュット美術館のパース図もそこにあったのですけれども、非常に天井が高くて、フリースペースというよりも、まさに美術館という感じの絵があったのですが、これをどのような活用を考えていらっしゃるのか、まず伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"今度の（仮称）品川区立障害児者総合支援施設で、美術館、展示室を設置するわけですが、そちらは委員もおっしゃったとおり、１階から入りまして、２階が吹き抜けになっており非常に広いスペースで、光も取り入れた感じを考えております。","voiceIndex":181,"id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この中で生活介護事業として、表現活動としてのアトリエ活動や音楽、リズム等、こういった芸術活動にもしっかり施設の中で行われていくということも表明されています。ここで１つ要望したいのが、やはりこれはフリースペース的なというよりは、学芸員もしっかり入れていただいて美術館としての機能を備えた、区として日本に、世界に冠たる美術館にしていただきたいということが１つであります。","respondent":"飛田障害者施策推進担当課長","answer":"今回、こちらの障害児者総合支援施設は、旧品川児童学園ということだったので、児童学園の子どもたちに協力していただきまして、普段の創作活動、そういうところで行っている作品を準備していて、感触遊びとか、そういう中で絵の具を手に触れて。","voiceIndex":183,"id":"exchange-080"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはり芸術としての人の心を動かす力があるのかどうか、子どもがつくったものに動かす力がないとは私はもちろん言えないのですけれども、さっき私が前段でアール・ブリュット美術館をつくる、また障害者の芸術活動に力を入れていく、世界に発信する施設ということで申し上げましたが、やはりそれに加えて、いわゆる評価のあるアール・ブリュットの展示、これは中野区等でも愛成会がやっていますが。","respondent":"飛田障害者施策推進担当課長","answer":"まさに今回、こちらの展示室なのですけれども、中野の愛成会が一緒に協力して展示室の運営をしていきますので、そういう意味では、広くいろいろな作家、また発掘も含めまして、障害者の理解促進を進めていきたいと考えています。","voiceIndex":185,"id":"exchange-081"},{"speaker":"本多委員","kind":"質問","question":"４７ページの特別区交付金と、１３５ページのふるさと納税寄附金、２つ質問します。ふるさと納税寄附金５４０万円の計上について聞いていきますが、昨日も渡部委員、石田秀男委員が取り上げ、提言もありました。引き続き聞いていきますが、昨日の答弁では平成２９年度に１１０万円の寄附があったとのことです。平成３０年度では５４０万円予算計上しておりますが、その根拠について教えてください。","respondent":"秋山財政課長、伊東税務課長","answer":"１つは、固定資産税があります。固定資産税について、今年の３年に一度の評価額の見直しの年ということで、４.２％の伸びというふうに見込んでいるもの。ふるさと納税のご質問です。確かに平成２９年度の見込みとしては１１０万円ということで、年度的には残りわずかですため、これぐらいの収入しか見込めないかと思っているところです。","voiceIndex":189,"id":"exchange-082"},{"speaker":"本多委員","kind":"確認","question":"財調のほうは、都の見立てと区の見立てを聞こうかと思っていたのですが、相互間で確認しているということで、これでやめます。ふるさと納税のほうなのですけれども、品川区へ納税された方の心遣いですとか、個人的な部分があるので必ずしも理由を把握することができないかもしれないのですが、その辺の分析についてはいかがでしょうか。","respondent":"伊東税務課長","answer":"なかなか細かく個々の分析まではしていないところですけれども、応援する意味での寄附ということで理解をしています。返礼品を出していますけれども、辞退される方もいらっしゃるところです。","voiceIndex":192,"id":"exchange-083"},{"speaker":"本多委員","kind":"質問・要望","question":"やはりイベントへの参加、大井競馬場が関東で一番のイルミネーションをやる、その入場券ですとか、例えば品川は国際交流事業を行っている都市がありますが、オーランドで言えばヒツジの製品がありますですとか、食べ物はよくないと思うのですが、物ですとかイベント参加ですとか、区民に対しては郷土愛、区外に対しては品川の魅力という、その辺の展開についてはいかがでしょうか。","respondent":"伊東税務課長","answer":"それと、逆に品川区のほうにご寄附をいただく方策ですけれども、委員、今、ご提案ありましたけれども、その辺のことはこれからどういう形がいいのか、物というのがなかなか難しいところはあるかと考えていますので、別の形で何かいいものがあるかどうかというのは、今後。","voiceIndex":194,"id":"exchange-084"},{"speaker":"本多委員","kind":"質問・要望","question":"これまでの答弁でも、返礼品競争をやらないということで、今現在の考えはよくわかります。ただ、何かしら手を打っていくべきだと思いますので、何がいいのか、昨日もイベントとか、ゴルフ場の割引券、いろいろな考え方があると思いますので、ぜひこういったことを今後もみんなで協議していくというようなことでお考えいただければと思います。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-085"},{"speaker":"のだて委員","kind":"提案","question":"就学援助についてです。さて、就学援助への国からの補助金は１８６万円と毎年数％の補助率になっていますが、国や東京都へ支援を要望したらどうかという私の提案に、区は東京都への財調単価の改定を求めていくことが先決との答弁でした。東京都への支援を要望したのか、現在の状況を伺いたいと思います。","respondent":"有馬学務課長","answer":"したがいまして、今の段階では２３区それぞれ増額するのかしないのか、さまざまな動きがあると思います。ある程度、２３区の金額がまとまったような段階で、都のほうには申し入れをしていくということになろうかと思います。","voiceIndex":198,"id":"exchange-086"},{"speaker":"のだて委員","kind":"質問・要望","question":"今の段階ではないということでしたけれども、就学援助という制度は子どもたちの教育機会を保障する大事な制度の１つですから、引き続き、他区とも連携して支援の要望もしていただきたいと思います。これまで同様、生活保護の引き下げに連動させないようにしていただきたいと思いますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"今回、また平成３０年度の秋に生保基準が見直しされるですけれども、これについても上限５％で数年間にわたって段階的にというようなことも言われており、詳細がまだ確定していないところもありますので、そういった意味から。","voiceIndex":200,"id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"戸越公園駅南側の戸越五丁目１９番地再開発について伺います。初めて１９番地再開発に補助金が今回つくことになりました。補助金が出るということは、総事業費が決まったのではないかと思いますけれども、この１９番地再開発の総事業費、補助金、そして公共施設整備負担金でしたか、公共施設を整備するときに出されるお金、これが幾らなのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"補助金額の合計につきましては、約４０億円ほどを予定しています。こちらについてもまだ精査をしている段階です。それから、再開発事業に係ります社会資本整備総合交付金につきましては、平成３０年度に予定されております権利返還計画作成費に対しての補助金です。","voiceIndex":202,"id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"それに対する区の見解は、課題解決を図りつつ、事業採算性を確保する上で、高度利用地区に伴う容積緩和が妥当だということで超高層ビルにしていくということでしたけれども、事業採算性を確保するというのは、どういう意味なのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"私ども区といたしましては、老朽化した建物の耐震性の確保、それから不燃構造化、また駅前というところを捉えますと、公共空間の確保でありますとか、狭い道路を拡幅したりとか、そういう基盤整備を再開発事業で進めていくことが妥当というような考えです。","voiceIndex":204,"id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"事業採算性は準備組合の考え方ということでしたけれども、区の出した意見書に対する見解が事業採算性を確保するために妥当だということでしたので、これが区の見解だということではないのか、改めて伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"区としても事業を進める中で、事業者の見解については承知しています。","voiceIndex":206,"id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"事業者の見解は承知しているということですけれども、つまりは、４０億円の補助金を出して、大企業の利益を確保していく、事業採算性を確保していく、そういったことのために容積率の緩和を行うのが妥当だということなのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"あくまでも町としての課題の解決、それから駅前の基盤の整備、そういったものについて区として再開発事業を進めることが妥当というような考えで進めているものです。","voiceIndex":208,"id":"exchange-091"},{"speaker":"のだて委員","kind":"質問","question":"今回の地区計画で、１９番地が高度利用地区に指定され、事業計画に合わせて容積率が４００％から６５０％に上げられました。この変更をしなければ、２４階建て、９０ｍの建物を建てる事業はできないということになると思うのですけれども、やはりこの容積率の緩和は大企業のもうけのためではないのかと思いますが、改めて伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"再開発を進めるに当たりましては、先ほどから委員がお話があるような事業が成立するかどうか、そういった観点も必要だと考えています。再開発については、そればかりが目的ではございません。こちらにつきましては、やはり町の課題の解決、そういったものが念頭にあるものです。","voiceIndex":210,"id":"exchange-092"},{"speaker":"のだて委員","kind":"質問","question":"企業の利益の観点も必要だということですけれども、企業は当然、利益を出すことを目的にやっているとは思いますが、自治体として４０億円も補助金を出して利益を確保していく、そういった観点が必要だというのは、自治体がやることなのかと思います。地域課題の解決は、超高層ビルでないとできないのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"地域課題の解決方法はいろいろあると思います。こちら、戸越五丁目１９番地地区におきましては、権利者である皆様方が再開発事業として進めたいという意思のもと進めているものです。","voiceIndex":212,"id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"「生まれ育ったこの町が好きだ」と、「再開発によって町が壊されてしまう、１９番地再開発をやめさせたい」というお話を伺いました。この間、品川区は、戸越公園駅のまちづくりビジョンも作成しておりますけれども、作成に向けて、まちづくり協議会の方だけでなく、幅広く周辺住民の方にも意見を聞いて作成したものなのか、そして計画を進めているのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"まちづくりビジョンで定めている将来像を区として今後も進めていきたいと考えています。","voiceIndex":214,"id":"exchange-094"},{"speaker":"のだて委員","kind":"質問","question":"だからこそ、今、この周辺の方からも、１９番地再開発をやめてほしいという声が上げられております。品川区は、戸越公園駅周辺の町をどういう町だと認識しているのか、私は町の方々がおっしゃっているとおり、肩肘張らずに出かけられ、商店街もありますので、町のコミュニケーションも活発に行われて親しみのある町だと思いますけれども、いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"私どもも町会の方、それから商店街の方とお話しする中では、委員と同じ考え方です。この町について今後も維持し続けられるような取り組みを続けたいと考えています。","voiceIndex":216,"id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"同じ考えだということでありましたら、やはり再開発が進むと町が壊されてしまうということも近隣の方が危惧されておりますので、こういった考え方を改めるよう要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"私は、例年要求資料を使わせていただいて、その中の７ページにあります保育園に対する国、都の補助金等々の金額がそれぞれ入っております。その中でお聞きしたいのは、保育園を設置するといった場合に、私立、認証、それぞれどのぐらいの補助金が入るのか、品川区も当然負担をしていると思うのですが、品川区の負担はどうなるのでしょうかということ。そして、運営費です。","respondent":"大澤待機児童対策担当課長","answer":"補助金としましては、平成３０年度、運営費で、国と都から入ってきます合計額が４３億円余というふうになっております。開設経費に関しましては、平成３０年度予算で、国および都から、準備経費として２６億円余が歳入となる予定です。","voiceIndex":220,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"それと品川区の負担も増えてきていますよねということを言いたいのです。推移も聞いているのは、品川区の負担がどんどん増えてきているのではないでしょうか。そのもととなる数字があればということでお答えをいただきたいのです。なので、推移のほうは数字がないということなので、品川区の負担がどのぐらいになっているのかをお聞かせください。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年度の予算で、私立保育園等の運営費は１２６億円になりますので、区の負担割合が６６％というふうになっております。このパーセンテージ自体は毎年大きく変わるものではございません。","voiceIndex":222,"id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"今、６６％ということで、この割合は毎年変わらないということですか、私立保育園は非常に多くなっています。１０園とか、今年も１２園でしょうか、増やしていくという形になるので、当然ながら運営費ですから、毎年毎年、私立保育園、認証保育園に対する運営費が品川区にかかってくるのだと思うのです。","respondent":"大澤待機児童対策担当課長","answer":"金額はもちろん毎年園数が増えれば上がりますけれども、運営費全体にかかる区の負担割合は、毎年大きく変わるものではないです。","voiceIndex":224,"id":"exchange-099"},{"speaker":"西本委員","kind":"質問","question":"この待機児童解消に向け、いつまでこの事業をどこまで大きくしていくのかということです。そして、その根拠がどういうところにあって、今後の５年先、１０年先の保育園を計画していくのか。次に民営化です。その民営化になったときの品川区の負担といいますか、ほかのところからの補助金等々が出ると思うのですが、どういう形になってくるのか、それを教えてください。","respondent":"大澤待機児童対策担当課長、吉田保育施設調整担当課長","answer":"ですので、子ども・子育て計画に基づいて、平成３１年度までは開設の予定が立っておりますけれども、平成３２年以降の開設につきましては、来年、ニーズ調査等をいたしまして。私からは、公設民営についてと、運営費についてもご説明申し上げます。公設民営につきましては、区の持ち出しはほぼ１００％という形になります。","voiceIndex":226,"id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"今の公設民営に関してですが、持ち出し１００％とはどういう意味なのでしょうか。要するに、公立保育園をつくるというのは、１００％一般財源から出るわけです。今の公立保育園を民営化することによって、どういう形になってくるのですかという話です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":229,"id":"exchange-101"},{"speaker":"西本委員","kind":"質問","question":"もう一度。新設はわかります。運営費が変わってくるわけですね。要は、民営化をすることによって変わってくると思うのです。それによって予算の立て方も変わってくると思うのですが、どういう形になってくるのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"公設民営のところの運営費ということでよろしいでしょうか。公設民営の運営費となりますと、これは区立保育園と同等になりますので、区の持ち出しがほぼ１００％という形で運営する形になります。","voiceIndex":231,"id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"済みません、私の質問が悪いのかもしれませんが、では、なぜ民営化するのですかという話になってしまうのです。では、民営化になるとどういう形になるのですかという話です。民営化しても、品川区からの持ち出しが変わらなければ、なぜ民営化するのですかという話になってくるのです。では、公立保育園の意味は何でしょうかという話です。そこを答えていただけますでしょうか。","respondent":"佐藤保育課長","answer":"先ほどの答弁があったように、運営費に関しましては、公立の保育園のスキームと同じで、利用者の負担が大体１５％、それ以外に関しましては区の税金で負担をするというものでありまして、第一義的には待機児童対策です。","voiceIndex":233,"id":"exchange-103"},{"speaker":"西本委員","kind":"質問","question":"品川区は公立の民営化をやろうとしているわけではないですか。そうなったときに、予算立ても変わってくるのですか。今の答弁ですと、いや、変わらないです、委託するにしても全て区がお金を出すことになるのです、品川区の負担が同じなのですというのであれば、民営化にする必要はないではないですか。だったら、ではなぜ公立保育園を民営化にする意味があるのですかということです。答えられますか。","respondent":"佐藤保育課長","answer":"その関係で一度に民設民営に切り替えるのではなくて、一度、公設民営という形で民間に委託をしてから、徐々に民設民営に切り替えていくという考え方に基づいてやっているものです。","voiceIndex":235,"id":"exchange-104"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"すまいるスクール関係です。児童指導に携わる方の人材確保を要望するという質問をさせていただいた中で、国の子ども・子育て支援交付金の運営費補助は、人件費基準額が引き上げられ、増額分を要求しますという答弁をいただいております。これは具体的に言うと、さっきもちょっとお話が出ましたけれども、工事現場を見ると、来年の２月の完成、４月の運営開始に間に合うのでしょうか。","respondent":"高山子ども育成課長、小林施設整備課長","answer":"今回の歳入に関します部分につきましては、利用児童の増加に伴いまして、必要額を最大限要求するというものでございまして、こうしたものが回り回ってではありますが。現在、現場のほうでは、５月末ごろまで、地下の部分の工事を進めております。それから鉄骨を建てまして、８月ごろから仕上げに入ります。そして、平成３１年２月を目標に竣工できるように、今現在、一丸となって頑張っています。","voiceIndex":238,"id":"exchange-105"},{"speaker":"鈴木（真）委員","kind":"質問","question":"契約は５年ですね。その中で人件費分を乗せていただいている、乗せてもらいたい部分なのですけれども、その辺に関して教えてください。全然反対もなく、あれだけのものが立ち上がるというのは、本当に地域の方のご協力があると思っているのですが、その中で近くの小学校の児童の作品も一緒にしたらどうかというお話もあったのですが、今そういうお話は進んでいないのでしょうか。","respondent":"高山子ども育成課長、飛田障害者施策推進担当課長","answer":"すまいるスクールは委託による運営形式ということでございまして、平成２９年度の総事業費に占めます委託料の割合は、大体５９％程度だったのですが、平成３０年度の当初予算におきましては６３％ということで。近隣の小学校ということで、今後、城南小学校に声をかけて、どういうふうな作品、どういう展示方法があるかを検討していきたいと考えております。","voiceIndex":241,"id":"exchange-106"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"運営のほうです。４つの団体というか、法人が一緒になってこれから指定管理を受けていく方向にあると思うのですが、やはり４つの団体が一緒にとなると、まとまりがなかなかつきにくいというのは以前からお話を伺っています。最初のプロポーザルのときから４つで来ているのですから、ぜひそのまま進めていただきたいのですが、今の進捗状況、そのまとまり状況について、もう一度教えてください。","respondent":"飛田障害者施策推進担当課長","answer":"運営に関しても、なかなかこちらの考え方と相違が出ることもありますが、そこが大きな課題と言えば課題になってしまいますが、いずれにしましても、区と運営事業者ともに平成３１年４月より、しっかり運営ができるよう、今後とも協議を図っていきたいと考えております。","voiceIndex":244,"id":"exchange-107"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"地方消費税の関係です。このままいくと、品川区は３０億円という数字になってくると思うのですが、この辺につきまして、区は当然、先ほど来、お話はわかっておりますが、これから例えば特別区長会として、さらなる要望をどのようにしていくのか、この辺をどう対応なさっていくのかお聞きしたいと思います。","respondent":"秋山財政課長、柏原企画調整課長","answer":"法人税も含めて、税制改正案が上がって、国はこちらのほうを見ているですので、これを、繰り返しになりますけれども、区長会を通じて、また東京都とも連携をとって強力に主張してまいりたいというふうに考えているところです。全国連携プロジェクトの関係です。今、委員ご指摘もあったとおり、区としてもさまざまな都市と交流連携したいというところで、区長会のほうでも連携プロジェクトの強化ということで、さまざまな取り組みを今、検討しています。","voiceIndex":246,"id":"exchange-108"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"全国連携プロジェクトはぜひ、やっぱりわかってもらわないと、せっかく２３区でやっているものが何も伝わらないのではないかと思います。ぜひその辺もしっかり区長会等で検討していただきたいと思います。ぜひよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":249,"id":"exchange-109"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは、８３ページ、国庫支出金の国民健康保険負担金、また同じく１０３ページに、都支出金としての国民健康保険負担金というところで、いわゆる国保の広域化にかかわる質問をさせていただきたいと思います。これまでも、昨日も含めて幾人かの委員からもこのご質疑がありましたけれども、平成３０年度から広域化ということで、国保が東京都に移管をされる。","respondent":"三ッ橋国保医療年金課長","answer":"その中で区といたしましては、やはり統一保険料方式の、２３区内同一世帯同一所得であれば同じ保険料という考えに基づきまして、区といたしましては、その考え方に賛同しております。","voiceIndex":251,"id":"exchange-110"},{"speaker":"塚本委員","kind":"質問","question":"将来的な方向性で示されている法定外繰入金の解消または縮減というふうになっていますけれども、改めて法定外繰入金に対する特別区の方針、ならびに、その特別区の方針の中において、さらに品川区としてそれをどのように受けとめ、また理解をしているのか、何か独自の考え方等あるのか、お伺いしたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"法定外繰入金の部分ですが、国からは法定外繰入金を解消・縮減するようにと求められております。その考え方に基づきまして、区といたしましても法定外繰入金を解消・縮減する方向で考えております。","voiceIndex":253,"id":"exchange-111"},{"speaker":"塚本委員","kind":"質問","question":"医療費の適正化に向けた取組等に対する支援ですけれども、これはどういうものなのか。品川区として、今、この支援制度の活用にあたり、どのような状況であるか教えてください。","respondent":"三ッ橋国保医療年金課長","answer":"保険者努力支援制度ですが、これは国の追加で１,７００億円が予定されておりまして、それは国保共通の指標、そして一方では、保険者共通の指標というものがそれぞれあります。","voiceIndex":255,"id":"exchange-112"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういうさまざまな財政支援で国保の負担を下げていこうという動きがあるわけですけれども、そういう中でも、どちらかといえば医療費が高くて、そして所得としてはそんなに高所得の被保険者がいないという特性がありますので、この中で区として、今後の、保険料負担をどのような形で安定化していくのか、持続可能なものとしていくのか、そういうところについてご見解をいただきたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"今回、財政運営の安定化といたしましては、東京都が財政運営の主体となっております。区や特別区長会、そして全国自治会連合会からも国庫負担金の増額の要求はしておりますので、なるべく保険料が値上がりしないようにしていく所存です。","voiceIndex":257,"id":"exchange-113"},{"speaker":"塚本委員","kind":"質問","question":"いわゆる支援というところを含めまして、あとは医療費の抑制というところで最後にもう１つ伺いたいのですけれども、これまでも医療費の抑制ということで質疑がございましたけれども、医療費をなかなか少なくしていくということは難しいのかもしれませんが、増加を少しでも抑制していくというところで、いろいろな手段があるかと思います。","respondent":"三ッ橋国保医療年金課長","answer":"医療費の適正化につきましては、データヘルス計画の中でいろいろな取り組みを行っております。その中で、やはり医療費、重症化予防対策や薬剤の関係のさまざまな取り組みを行っておりますけれども、できるだけ保険料が上昇しないように抑制してまいりたいと考えています。","voiceIndex":259,"id":"exchange-114"},{"speaker":"いながわ委員","kind":"確認","question":"それと、１４７ページの雑入の広告料収入について、要するに、広告料収入ですから税外収入の観点から考えて大変必要なものだと思っておりまして、おそらくこれは大半が区のホームページのバナー広告料だと思っていますが、これに関して、その詳細と、今後の事業展開をどうお考えなのかということ。","respondent":"今井土木管理課長、稲田都市開発課長、池田スポーツ推進課長、溝口公園課長、中元広報広聴課長、松山高齢者地域支援課長","answer":"７５ページの土木使用料、土地建物使用料につきましては、五反田ふれあい水辺広場内の地域貢献施設として貸し出しを行っているところです。西大井駅周辺の西大井作業所というところで、従前居住者への仮移転先としてお貸ししているという状況があります。１０７ページのスポーツ施設整備費の補助金です。新たにという形ではありませんが、今後もこういった補助金等は活用しながら整備等を進めていきたいというふうに考えているものです。こちらも引き続き広告等の掲載に努めていきたいです。","voiceIndex":262,"id":"exchange-115"},{"speaker":"いながわ委員","kind":"質問・要望","question":"スポーツ施設整備費は、オリンピックに向けてということだったのですが、ということは、オリンピックはあと２年後なのですが、２年たったら、それは打ち切られる方向性なのかどうなのか、もちろん計画的に整備はしっかりと進めていただきたいという思いがありますので、よろしくお願いします。","respondent":"秋山財政課長、松山高齢者地域支援課長","answer":"区としましては、税外収入については、各所管に工夫をするようにという通知をしておりますので、それぞれ各所管の立場で工夫をしてやっているというところで。ただし、シルバーセンターの老朽の度合いですとか、お困りの状況を総合的に勘案しながら進めてまいりたいと考えています。","voiceIndex":269,"id":"exchange-116"},{"speaker":"いながわ委員","kind":"質問","question":"要するに、例えば広告料収入はすごく考え方が幅広いと思うのです。そのバナーの上には広告募集についてなどというものが書かれているのです。そこを押すと、バナーのみです。では、ほかの例えばデジタルサイネージに載せたいという人たちは、どこにいけばいいのかもわからないですし、それをしっかりと管理するべきではないですかということを申し上げております。よろしくお願いします。","respondent":"秋山財政課長","answer":"どのようなことをやっているかという調査も含めて、こちらのほうで取りまとめて、今後、ワンストップでできるようなことを検討していきたいと思います。","voiceIndex":272,"id":"exchange-117"},{"speaker":"渡辺委員","kind":"質問","question":"１３１ページ、オリンピック・パラリンピック教育推進事業について伺いたいと思います。その中で、まず東京都委託事業の、主な内訳を教えてください。数値目標か何かおありなのか、そういう認知度、学ぶという観点になるかと思うのですが、こと３競技の応援ということでおありでしたら教えてください。","respondent":"熊谷指導課長","answer":"特に都のパラリンピック応援校になっております荏原第六中学校におきましては、ブラインドサッカーに特化して選手たちの競技会場、練習会場として活用する中で、生徒との取り組みを進めているところです。","voiceIndex":275,"id":"exchange-118"},{"speaker":"渡辺委員","kind":"質問","question":"そこで１つ伺いたいのが、映像の活用をどのように考えられているか。だからこそファンになったというケースを最近ちょっと感じたものですから、映像等を活用して、今まで３０人が限界だった、１００人が限界だったものが、またそこからの広がりという意味で浸透できるのかなと、教材にもかかわってくるかと思うのですが、何か考えがございましたら、よろしくお願いします。","respondent":"熊谷指導課長","answer":"この都の委託金ですけれども、こちらにつきましては、全ての幼稚園、学校に、次年度は２０万円ずつ支給となっております。こちらにつきましては、平成２８年度が３０万円、平成２９年度が２５万円、来年度が２０万円ということになっているところです。","voiceIndex":277,"id":"exchange-119"},{"speaker":"渡辺委員","kind":"質問","question":"体験会も、今、所管のほうでやっているスポーツ団体から今度は違うところへ、文化団体等へというのも伺ったことがあります。一方で障害者の方が友達や家族にいますかというと、手を挙げた方は３分の１ぐらいでした。そのような形で障害者理解を高めるための手段としては最高のものだと思いましたので、その辺の発信力を学校が、先生がリーダーとなって力を入れていく、そんな抱負を最後に伺えればと思います。","respondent":"熊谷指導課長","answer":"障害者スポーツのレベルが非常に高いというようなことも含めて、保護者や地域にも一緒にかかわって参加していただくような仕組みをとっておりますので、これからも学校だより等で周知していきますけれども、参加型ということも含めて行っていきたいと思います。","voiceIndex":279,"id":"exchange-120"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、国庫補助金、また都補助金の地域生活支援事業から、日中一時支援事業についてと、そこに関連して放課後等デイサービスについて伺いたいと思います。先ほどもあったのですけれども、登録料について伺いたいと思います。先ほども答弁があったのですけれども、改めて登録料とは何か。なぜ徴収するのか。そして、なぜ生活保護世帯や非課税世帯からも徴収されているのかを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"お尋ねの生活保護世帯ですとか、所得の低い方からもいただいているのかというお尋ねですが、現在のところ、登録料は全員の方からいただいているところです。","voiceIndex":282,"id":"exchange-121"},{"speaker":"石田（ち）委員","kind":"質問","question":"この利用料の月々の請求や銀行振替手数料等々の事務的なものということなのですけれども、先ほどもありましたが、この事業だけが登録料なるものを徴収しているということで、２３区で見ても、品川だけなのです。月々の請求や銀行の振替、こうした業務は誰がやっているのでしょうか。どこかが代行などされているのでしょうか。","respondent":"中山障害者福祉課長","answer":"それが社会福祉協議会のほうに、もともとのＮＰＯ法人がもうこれ以上事業ができないというようなお話をいただき、社会福祉法人に移管をしたものです。そういった当時のところから事務的な経費ということでいただいていたものです。","voiceIndex":284,"id":"exchange-122"},{"speaker":"石田（ち）委員","kind":"確認","question":"この事務手数料等々の代行としては、にじのひろば戸越では、明治安田生命が収入代行として月５０数件を請け負っているというふうに伺ったのですけれども、そこをまず確認したいと思います。最初はＮＰＯの方々がやっていたと、それから社会福祉協議会に移管される時点で、この登録料を委託料、品川区の委託料の中に入れることで、親御さんからの負担をなくすということはできなかったのでしょうか。","respondent":"中山障害者福祉課長","answer":"済みません、多分、代行手数料のところのお話かと思います。明治安田生命のほうは、私、申しわけございませんが、存じ上げません。社会福祉協議会に事務移管をしたときの話ですが、利用料金制度自体の中身の見直しは特にその時点ではしておりませんでした。","voiceIndex":286,"id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほどの生活保護世帯や非課税世帯、要は、収入の低い世帯からもこういった５,０００円の登録料は減免なしにとっていくということでしたので、ぜひここをなくしていくべきだと思います。そして、委託料として区が払うということを進めていくべきではないかと思うのです。その辺はいかがでしょうか。利用料軽減等により利用料ゼロで通われている方はどれくらいいるのでしょうか。","respondent":"中山障害者福祉課長","answer":"先ほどもご答弁申し上げましたが、この５,０００円ということにつきましては、料金の見直し、それから負担軽減策をあわせて検討していきたいというふうに考えております。","voiceIndex":288,"id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"登録料は廃止すべきだと思います。これがなければ運営できないというものではないと思いますので、ぜひ廃止していただきたい。低所得の方で９名の方はゼロということですが、そしてまた、昨年引き下がった利用料で多くの方が利用できるようにすべきだと思いますけれども、いかがでしょうか。ぜひ検討をお願いしたいと思うのですが。","respondent":"中山障害者福祉課長","answer":"日中一時支援のにじのひろばの利用料につきましては、今年度から利用料金の負担軽減の策もとってきたところです。利用者の方のお声も聞きながら、登録料についても見直しを検討していきたいと考えています。","voiceIndex":290,"id":"exchange-125"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひ廃止の方向で検討をお願いしたいと思います。にじのひろば戸越を見せていただきました。ですけれども、目的のところには、障害者等の日中における活動の場を確保し、障害者等の家族の就労支援や、障害者等を日常的に介護している家族の一時的な休息等を確保するためとあるので、障害児に絞る必要は、この目的から見てもないのではないかと思うのですけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"日中一時支援を大人の方にもご利用できないかというようなお尋ねかと思います。今現在でも、小学校１年から高校３年生までということで、幅広い年齢層のお子様、障害児の方に対応しています。","voiceIndex":292,"id":"exchange-126"},{"speaker":"石田（ち）委員","kind":"質問","question":"日中一時支援事業の対象を障害児にした理由は何なのでしょうか。","respondent":"中山障害者福祉課長","answer":"やはりこの事業を、ＮＰＯ法人の方が始めたときの成り立ちがございまして、特別支援学校の放課後において、なかなか障害児の方が楽しく過ごせる場所がない、あるいは、働いているため親御さんが見られない、そういったときの預かりの場が必要だということから。","voiceIndex":294,"id":"exchange-127"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。では、ぜひそういった障害者の方が心を休める時間をとれる場所を工夫してつくっていっていただけたらと思います。ですので、やはり放課後等デイサービスの利用日数、品川区の方針では、基本月１０日、これがやはり壁になっているというふうに思います。塾や習い事とは違うと思うのですけれども、なぜこれと同じ扱いになるのか伺います。","respondent":"中山障害者福祉課長","answer":"そういった中では、１５日の利用の方も大変増えておりますので、これからもご利用される方のお声を聞きながら、何がそのお子様にとって最適かを一緒に考えていければと考えています。","voiceIndex":296,"id":"exchange-128"},{"speaker":"石田（ち）委員","kind":"質問","question":"療育への偏りという答弁があったのですけれども、療育というのは、機会を増やすことでつらくなるというものではないと思うのです。ですので、やはり塾や習い事と同じ考え方で基本月１０日にしていくという考えを改めるべきだと思うのですけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"放課後等デイサービスは、やはり特別支援学校などと連携をすることというのが、今回、国の方針でもあります。そうしたことを見ながら適切な支援ができるよう支給のほうも決定してまいりたいと考えています。","voiceIndex":298,"id":"exchange-129"},{"speaker":"浅野委員","kind":"質問","question":"歳入、５９ページの集会所使用料、１２５ページの緊急放送設備整備補助金、９５ページのがけ・擁壁安全化支援について質問します。このような形で集会所が増えると、また地域の活動がより活発になるのかというふうにも考えられます。このたびの改修に関して、部屋が増えたとか、そういうことはあるわけですけれども、特徴的な内容、何かほかにもプラスアルファがあるのかどうか教えてください。","respondent":"伊崎地域活動課長","answer":"荏原第四連合のほうに貸し付けておりました旧荏原第四地区会館が閉鎖することに伴いまして、カラオケをやっていらした方の活動の場がなくなるということのご意見も受けまして、音響設備を入れて、３階の集会室でカラオケを利用できるにしたところが大きな特徴です。","voiceIndex":302,"id":"exchange-130"},{"speaker":"浅野委員","kind":"質問・要望","question":"１２５ページの緊急放送設備整備補助金１,０００万円、国庫補助金２分の１ということですが、大井埠頭に３カ所、品川埠頭に１カ所、この緊急放送設備が受信設備を含めて設置をされるというふうに伺いました。この意図といいましょうか、当該地域に３カ所、また１カ所設置をされる意図があれば教えていただきたいと思います。","respondent":"古巻防災課長","answer":"今年度から品川区において防災行政無線の更新を進めておりますけれども、それに際しまして、品川埠頭、大井埠頭のほうに防災行政無線の設備を増設するということで、補助金の申請をしまして、補助金を受けるというような形で事業を進めるものです。","voiceIndex":304,"id":"exchange-131"},{"speaker":"浅野委員","kind":"質問","question":"続きまして、がけ・擁壁の安全化支援ということで質問いたします。このがけ・擁壁については、今まで手をつけるというのが非常に難しかったと思うのですけれども、今回このような形でスタートといいましょうか、やっていきますということになったわけですが、何か大きな変化があったのか、それとも特別なやり方とか、そういうものがあるのかどうか教えてください。","respondent":"鈴木建築課長","answer":"大きな動きとしましては、やはり広島あるいは大島の土砂災害を受けて、東京都でも、昨年と一昨年かけて擁壁の緊急地域を指定に向けて調査を行ってあります。そういったところと連携しながら、来年度も擁壁の改修事業を進めていって、擁壁の改修を進めていきたいです。","voiceIndex":306,"id":"exchange-132"},{"speaker":"浅野委員","kind":"確認","question":"私がよく回っている地域につきましても、これは完全に切り立ったところもあるわけでありまして、やはりそういうところが少しでも安全に改修できれば、これは地域にとってもプラスになる、そのように思いますので、この点についてはこれからも確認しながら進めていただければと思います。","respondent":"鈴木建築課長","answer":"箇所数としましては、約２,２００カ所というところでございまして、調査結果につきましては、目視の調査でございましたが、区のホームページ上でも分布図として公表しまして、さらには所有者宛てに調査結果の概要を周知し、事業の案内も行っているところです。","voiceIndex":308,"id":"exchange-133"},{"speaker":"浅野委員","kind":"質問","question":"実際にできるところといいますと、なかなかこれは難しいと聞いております。簡単にはいかないところが多いと思いますけれども、粘り強く地域住民の方の意向も踏まえて、持っている方とも当然ですけれども、しっかりと連携をとりながら改修できるようにしていただければと思いますが、いかがでしょうか。","respondent":"鈴木建築課長","answer":"その辺の不安をアドバイザー派遣等を通じて、しっかりまず擁壁の安全化についてご理解いただいて、あるいは、日ごろの維持管理についてもしっかり技術的なアドバイスを差し上げて、１箇所でも擁壁の改修が進んで。","voiceIndex":310,"id":"exchange-134"},{"speaker":"石田（秀）委員","kind":"質問","question":"初めに、予算全体のことを伺います。それで、プレスなどを見ると、長期基本計画の最終年であり、集大成の予算だというような形でありますけれども、この予算をどのように捉えて、今、予算を提出されたか、積極的にいろいろな事業をやって、新規事業とかいろいろ載っているのだけれども、どうゆう気持ちの中でこの予算を組んで、そして１００億円増の過去最大規模にしたというところをお考えを教えてください。","respondent":"秋山財政課長","answer":"平成２９年度に比べて、民生費が１１３億円伸びておりますけれども、そのうちの７０億円強が子どもに関する施策ということで、そういうところに注力をして区民の期待にこたえている予算だというふうに認識しております。","voiceIndex":313,"id":"exchange-135"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その中で義務教育などは学校３校プラス施設建設で３０億円増。特に今度、待機児童もあるけれども、そういうところへ入れていったら１００億円になったけれども、そうではなくて、にぎわいの町をつくるため品川区としてこういうことをしていくのだということを明確にすべきだと思っているのですが、こういう考え方がどこかあれば教えていただきたい。","respondent":"秋山財政課長","answer":"そういう中でも、例えば今回、投資的経費の中でも障害児者総合支援施設とか、かけるところにはかけていって、こちらの施策を進めていきたいというふうに思っております。","voiceIndex":315,"id":"exchange-136"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ未来志向で、区長も答弁でいろいろな形でにぎわいをつくっていくのだというふうにおっしゃっていて、にぎわいがある品川区を今後４年間でもつくっていこうという形で力強く発言をされているわけですから、そのにぎわいをつくるためには、もちろんそれにはソフトもハードも必要だと思っているので、そういうところにしっかり予算をつけていくということをぜひやっていただければと思います。","respondent":"濱野区長","answer":"２０２０年東京オリンピック・パラリンピック競技大会があります、多くの方々が区に訪れていただきます。","voiceIndex":317,"id":"exchange-137"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。次に、５５ページの庁舎管理費負担金に関連して質問します。スクエア荏原でシナモロールカフェが開かれます。今回は、スクエア荏原でいいけれども、そういう発想をぜひしていただきたい。そういう発想もあったのか、それから、今後もそういう発想で人の流れを変えていくということも考えていくのか、ここだけ最後にお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"これは委員おっしゃるとおりでございまして、そういった流れを政策的といいますか、戦略的にといいますか、考えてつくるというのは、これは今後にぎわいという観点では非常に重要なポイントであると考えていますので、シナモロールだけではなくて。","voiceIndex":319,"id":"exchange-138"},{"speaker":"高橋（し）委員","kind":"質問","question":"これは６４ページの使用料及び手数料か、それとも１４４ページの雑入なのか、どこに入るかちょっとあれなのですが、健康センターの利用料金と指定管理に伴う区への還元金というのでしょうか、それに関してと、それからもう１つは、７５ページ、総務手数料の住民票等の証明発行にかかわって、目黒のサービスコーナーについてお尋ねします。","respondent":"川島健康課長","answer":"健康センターの利用料金収入のお話です。ここ数年の還元金の推移からお話ししますと、平成２６年度が７６０万４,２９６円、平成２７年度が９７０万５,６５２円という推移になっております。","voiceIndex":322,"id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問","question":"それが今お話しあったように、９００万円、１,０００万円近いということは、ただ、収入の２０％というと、もっと多くなると思うのですが、その算定方法は、料金が出てから幾ら還元するかということを決めるというお話ですが、今度どうなるかということをあらかじめ決めないで、収入料金が出てから決めるのですか。そこがちょっとあれで、ここ数年において見直をしているのかもお尋ねします。","respondent":"川島健康課長","answer":"失礼いたしました。今委員がおっしゃったとおり、収入額から見込額を引いた部分ということで見込額が１億６,７００万円、これは最初に決めたものですけれども、収入からこの見込額を引いた部分の２割が区の還元金になるという計算です。","voiceIndex":324,"id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問","question":"指定管理の運営委託の成功例だと思います。さらに還元金がこのように１,０００万円近く入ってくるということに関しても、区の歳入を増やす非常に効果的な施策であると思います。これまでのこちらの指定管理運営委託としての評価と、このような形式、つまり、利用料金、水族館はまた違った形式なのかもしれませんが、このようないわゆる歳入を生むような指定管理の仕組みに関するお考えをお願いします。","respondent":"柏原企画調整課長","answer":"ですので、こういった形での指定管理のあり方というのは、進めていくべきであると考えていますし、そういった事業の内容によっては、なかなかそういうものが生みづらい事業の施設もありますけれども、そういった効果が望めるようなところについては。","voiceIndex":326,"id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"意見","question":"健康センターについては２箇所でこのような形で進められているのは大変よいことだと思っています。サービスコーナーのほうに移りまして、目黒のサービスコーナーが大井町、武蔵小山に続いて民間委託ということなのですが、期待される成果、それと、また逆にこういった課題を克服しながら進めていかなければいけないのではないかという、その点についてお尋ねいたします。","respondent":"提坂戸籍住民課長","answer":"目黒サービスコーナーにつきましては、大井町、武蔵小山に次ぐ第３のサービスコーナーということで、４月７日にオープンを予定しております。運用形態ですけれども、大井町は今年度から委託を開始しておりますけれども、武蔵小山は今のところ直営でやっております。","voiceIndex":328,"id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"期待される成果というのは、サービスの向上や直営で行うことによる経費削減という、そういったところの観点でお話しいただきたいのですが、その点についてはいかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"もちろん接遇の向上、あと、コスト減ですと、職員を以前の大井町サービスコーナーですと１０人以上雇用していたのですが、それが約半分程度で済むのではないかということで、サービスコーナーだけではなくて、戸籍住民課全体のコスト減につながると期待しております。","voiceIndex":330,"id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"サービスコーナーは区全体の窓口でもありますから、大井町も含め、サービス向上と経費節減を、このまま進めていっていただければと思います。ほかの分野においても、このような民間委託についてはさまざまな課題を検討しながら進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":332,"id":"exchange-144"},{"speaker":"若林委員","kind":"質問・要望","question":"質問に入ります前に、平成３０年４月から新しい公会計制度、いわゆる複式簿記の発生主義による新しい制度がいよいよ始まるということで、またそれに合わせて、今回いろいろ工夫を、特に明日からの歳出の審議に当たって１課１目に合わせた新しい予算書の作成とか、しっかりとこういうものを私たちはツールとして活用させていただきたいと思います。","respondent":"齋藤会計管理者","answer":"歳入、歳出、日々仕分けに当たってのパソコンの操作研修です。日々、管理職も含めて、延べで８００人近い職員が研修に携わっておりまして、実際にパソコンを使って間違いのないようにきちんと対応できるようにということで取り組んでいるところです。","voiceIndex":334,"id":"exchange-145"},{"speaker":"若林委員","kind":"質問","question":"空き家等対策事業ですけれども、まずは平成２８年度から空き家相談会、これは年に２回ですか、それから電話相談が毎週の月・水・金の午前中に行われております。こういう中で、区民等からのご相談でどのような内容があるかをお聞きしたいと思います。あわせて、昨年の決算特別委員会でもお聞きしましたけれども、平成２９年度、今年度、空き家対策等の計画策定をする予定というふうになっております。","respondent":"長尾住宅課長","answer":"対策計画につきましては、現在、作成を進めているところです。現行のこれまで中心に行っておりました空き家に関する調査の内容でありますとか、あと、先ほど申しましたホットラインでの相談の窓口のお話などをまとめるとともに、これから取りまとめを進めていくところです。","voiceIndex":336,"id":"exchange-146"},{"speaker":"若林委員","kind":"質問","question":"今の計画の内容は、その大きな２つをもって、いわゆる空き家等対策の計画といわれるのでしょうか。もうちょっと内容を、私のほうで去年のご答弁を紹介しましたので、不足があればつけ加えてください。","respondent":"長尾住宅課長","answer":"その中でどういった地域を空き家対策を進めるエリアとして指定するのか、また、その計画の実施年数についてであるとか、あとは、大きなところで言いますと、空き家の適正な管理に関しての施策、空き家の活用に関しての施策といったものもまとめることになっております。","voiceIndex":338,"id":"exchange-147"},{"speaker":"若林委員","kind":"質問・要望","question":"もう１つ、居住支援団体、これは東京都のほうで指定をするというふうに法的に決まっていますけれども、こういった都の指定も受けなければいけないという、まだまだそういう意味では、これまでのご答弁どおり、なかなか居住支援協議会の立ち上げには壁が厚いというか、高いというか、国のほうでは平成３２年度を目標にすべての自治体での立ち上げを掲げていて、一方、一昨年の決算特別委員会では。","respondent":"長尾住宅課長","answer":"そういった国や都の動きなども含めて、効果的な品川区版の住宅確保要配慮者に対する支援体制というところを構築していきたいというふうに考えておりますが、既存の事業などもいろいろ既にやっているものもありますので、そういったところとのバランスも見ながら。","voiceIndex":340,"id":"exchange-148"},{"speaker":"若林委員","kind":"質問","question":"取り組んでいくということで、先ほどご紹介したいわゆる残る２つ、３つの大きな課題をどうやって乗り越えていくのかというところの、課題を指摘したわけですので、そこについてのご答弁をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":342,"id":"exchange-149"},{"speaker":"伊藤委員","kind":"質問","question":"７７ページの個人番号カード再交付手数料に関連して、それから１２ページのオリンピック・パラリンピック施設周辺道路整備工事に関連して、それから１４１ページの社会福祉法人貸付金返還金に関連して質問します。は個人番号カードのほうですけれども、これは去年も質問しました。国のホームページによれば、公平公正な社会実現云々かんぬんで、全国民が対象であるということ。お願いいたします。","respondent":"提坂戸籍住民課長","answer":"マルチコピー機の端末体験セミナーというのを何回か開催しまして、コンビニで設置しておりますマルチコピー機がいかに使いやすいかということをＰＲして、マイナンバーカードの普及につなげたいと考えています。","voiceIndex":344,"id":"exchange-150"},{"speaker":"伊藤委員","kind":"確認","question":"だって、国はあくまで公平公正な社会実現、利便性向上のためにやるというわけだから、おそらくこの目標は変えないでしょうから、そうなってくると、必ず全ての国民の方々がこのカードを持つことが前提としてあるわけだから、やはり今までの取り組みだけではなくて、さらにそういう国の方向性を確認した上で、積極的な取り組みをしていかないと、３８万、３９万人の区民に対して。","respondent":"提坂戸籍住民課長","answer":"マイナンバーカードの個人番号が情報漏洩ということにつながらないように、安全なカードですということをあわせて十分ＰＲしてまいります。","voiceIndex":346,"id":"exchange-151"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひよろしくお願いいたします。これは私も何回か質問させていただいたので、大井競馬場入り口から大井ふ頭中央海浜公園、それからホッケー会場までの無電柱化、これはぜひ進めてくださいということをお願いしているのですが、やはり立会川駅周辺が抜けているのです。だから、そこからのアクセス、そこからのルートについても、やっぱり配慮していくべきではないかと思うのですが、いかがでしょうか。","respondent":"多並道路課長","answer":"私からは、オリンピック・パラリンピック周辺の無電柱化についてお答えします。","voiceIndex":348,"id":"exchange-152"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、もちろん看板設置なり、さまざまなことをこれからソフト、ハードやっていくのでしょうけれども、改めてこの立会川駅から大井ふ頭中央海浜公園までの間のアクセス、道路整備、それから案内看板の設置等、さまざまな検討をして、ぜひ２０２０年に間に合うようにしていただきたいと思うのですが、いかがでしょうか。答弁をお願いいたします。","respondent":"多並道路課長","answer":"整備の考え方ですが、立会川駅の近くの浜川橋のちょうど補修工事が入ることで、来年度の予算に計上をしています。その補修工事をやりながら、前後の舗装の修復もやっていこうと思っているところです。","voiceIndex":350,"id":"exchange-153"},{"speaker":"伊藤委員","kind":"質問・要望","question":"改めてよろしくお願いいたします。今、社会福祉法人のＩＣＴ化は、厚生労働省が非常に積極的でありまして、２０１８年に現場スタッフの報告を電子化、そして２０２０年に全面展開を目指すということが厚生労働省の方向性であるとわかりました。これはぜひ品川区の社会福祉法人の中でも展開をしていっていただきたいと思うのですが、まずは品川区のお考えをお聞かせください。お願いいたします。","respondent":"寺嶋高齢者福祉課長","answer":"いずれにいたしましても、ＩＣＴ化につきましては、全国的にも注目されておりまして、品川区も他の自治体の例なども参考にしながら、鋭意情報収集に努めているところで、今後の検討課題の１つであると認識しています。","voiceIndex":352,"id":"exchange-154"},{"speaker":"伊藤委員","kind":"質問","question":"だから、これからは間違いなく高齢者の数が増えていくわけであって、そこにＩＣＴ化の導入を図ることによって、総体的に個々のサービスが向上していくということ。同時に、介護のサービスにかかる費用も下がっていくということ。だから、今の検討する方向は正しいのだけれども、もっとより主体的に具体的に、国の方向性をつかみながら品川区がリードしていくべきだと思うのですが、いかがでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"これは民生費の款の中でのお話にもなってくるのですけれども、来年度、データ分析の費用として１,１００万円ほど計上させていただいている、ＩＣＴ化に向けてデータ分析をやるという、そういった事業も検討しているものがあります。","voiceIndex":354,"id":"exchange-155"},{"speaker":"伊藤委員","kind":"質問","question":"これももちろんあるでしょうけれども、できれば最期の看取りの部分については、社会福祉法人の中では、円満な形で、さまざまなことがあり、もちろん簡単にはいかないことはわかってはいるのだけれども、個人の最期のところは、やっぱりさまざまな専門家が合同ですばらしい形で送ってあげたほうがいいと思うのですが、品川区のお考えをお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"これからもその部分につきましては、しっかり取り組んでいくというふうに聞いているところです。","voiceIndex":356,"id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"８９ページ、シティプロモーションについてお聞きしたいと思います。品川区も地方も、それぞれシティプロモーション事業を各自治体でやっております。さまざまな事業をやっておりますが、そもそもシティプロモーションの始まった理由は何ですか。教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"そのときにそれぞれの自治体で都市間競争のような、そのときに定住人口の確保というような形で、住み続けていただきたい、あるいは訪れていただきたい、住んでみたいというふうに思っていただきたいというところで、そういう方々を増やしていきたいということで始めた事業です。","voiceIndex":359,"id":"exchange-157"},{"speaker":"須貝委員","kind":"意見","question":"今、人口減少に伴って、人を誘致したり、また、生き残れる自治体ということもあるのでしょう。観光事業をさまざまやったり、企業の誘致をしたりしております。もちろんその中には、人口だけではなくて、減少する税収に対しても何とか抑制しようという努力もあると視察に行って聞いております。その一方で、品川区は人口も税収も増えています。もう一度お聞かせ願いたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"これから全国的なそういう流れの中で、そういうところも見据えた形で、ある程度、基盤といいますか、愛着を持ってこのまま住み続けていただきたいというような、そういう活動です。","voiceIndex":361,"id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"我々も地方、さまざまなところを視察しております。そのような状況にあるわけですから、今、課長がおっしゃったような、今後、心配だ、それはどこと比較して心配と言うのでしょうか。今この状況で２３区、ますます人口が増え続け、まして都心一極集中している状況ですから、人口や税収が増え続けている品川区にとっては、このシティプロモーションの役割は終わっているのではないでしょうか。","respondent":"木村報道・プロモーション担当課長","answer":"確かに定住人口も必要でしょうけれども、実際に訪れていただく、品川区のよさをもっと知っていただく、区外の方に知っていただく、魅力を発信していくというような形の動きはこれからも続けてまいりたいと思います。","voiceIndex":363,"id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"これだけ年々税収が増えて、人口も増え続けています。これは先ほど課長がおっしゃいました。その中において、この品川区は、事業費をかけて、そして人件費もかけてやる必要があるのですか。税収は増えて、人も増えて、増え続け過ぎているではないですか。ならば、シティプロモーション事業による他の地方自治体とのアピール競争も私はやめるべきだと思うのですが、それはどう思いますか。","respondent":"中山企画部長","answer":"課長の説明にもあったわけですけれども、まずは外に向けて品川の魅力を発信するという面がありますけれども、内外、これは品川の魅力を外にも発信するし、区民の方にしっかりと品川の魅力を伝え愛着を持っていただく。","voiceIndex":365,"id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"部長、十分魅力があるから来ているのではないですか。品川区に住んで、住宅もきちんと供給しています。魅力を発信しなくても来ているのではないですか。今の答弁はおかしくありませんか。それをしなくても人がなぜ集まるのか、先ほど言いましたが、２３区はこの場所がそもそも、交通網を含めて生活環境がいいわけです。それが、区民のためになるのですか。区民は何を望んでいるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":367,"id":"exchange-161"},{"speaker":"須貝委員","kind":"質問・要望","question":"区民のためになるのですか。その辺についてお聞かせいただきたいと思います。私は、これだけもう品川区は、立派なものを持っているのだから、地方自治体とのアピール競争はするべきではないと思うし、また、区民にとってどれだけ役立っているかということをもう一度教えてください。","respondent":"中山企画部長","answer":"そういうものの総合的な積み重ねが現在に至る品川の魅力につながり、転入増、あるいは定住率が高まっている、９割以上に方に住み続けたいと思っていただく、こういうものにつながっているわけですので、そういうものの延長線上にシティプロモーションはあると。","voiceIndex":369,"id":"exchange-162"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、まず６５ページの八潮北公園スケートボード場について、それと１１７ページ、地域自殺対策強化交付金についてお伺いします。初めに、八潮北公園スケートボード場ですが、まず、利用時間についてお伺いしたいのですが、小学生以下は１８歳以上のつき添いが必要というふうに明記されているのですけれども、時間帯が書いていないので、小・中学生の利用時間についてお知らせください。","respondent":"池田スポーツ推進課長、溝口公園課長","answer":"現在、教室につきましては、公園を運営している委託業者のほうでお願いしていますけれども、今後も定期的な教室を開催する予定ではありますけれども、この後どのような拡大をしていくかというところは。ただ、先行事例として、やはり企業としてＰＲが十分できるようなところについて導入しているというところがありますので、ネーミングライツについては、今後。","voiceIndex":372,"id":"exchange-163"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"利用時間なのですが、それはスケートボード場の利用時間であって、その利用時間帯は、中学生も夜９時まで保護者なしで使うことができるのかどうか、その辺を改めてお聞かせください。次に、地域自殺対策強化交付金についてですが、いわゆる自殺総合対策の中で、対策の大綱も昨年の７月ですか、閣議決定がされ、また、全ての都道府県および市町村に対して、対策の計画を策定するようにということになりました。","respondent":"池田スポーツ推進課長、溝口公園課長、舟木保健予防課長","answer":"ですので、ご提案いただいたキッチンカーということにつきましては、こちらのほうでは考えていないところです。そういった中でいきますと、やはりスケートボード場という特性をしっかり踏まえた中で、スポーツ用品店ですとか、またスケボーのショップですとか。教育との連携ですが、そちらは若年層への取り組みということで、ここ２年くらい強化しているところなのですが。","voiceIndex":377,"id":"exchange-164"},{"speaker":"石田（し）委員","kind":"提案","question":"たばこを吸う人はわかると思いますが、喫煙所に１人でいるときに、たばこを吸っているだけではなくて、いろいろ考えごともしたりしている中で、その時間帯は、その喫煙所の中を見渡したりもするので、そういったいわゆる人間が何かをするときの目線というところに注目していただいて、ぜひそういうところにそういった広報を、月間だけでも打っていただきたいというふうに思いますので、もう時間がないので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":381,"id":"exchange-165"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"８５ページの障害者自立支援給付費について伺いたいと思います。金子山のグループホームが開設しましたけれども、２０１６年１１月に行われた厚生委員会では、福栄会が得意とする重度知的障害、おおむね愛の手帳２度の方を中心に入れていきたい、かがやき園の入所の方の地域移行にもチャレンジしたいという報告でした。","respondent":"中山障害者福祉課長","answer":"その中では、ご本人の希望、ご家族の希望、それから、やはり今回、緊急対応というところもありましたので、ご家族の介護の状況、そして、グループホームになりますので、ご本人様の日中活動の状況、そういったものを総合的に勘案して入所の決定をしたところです。","voiceIndex":383,"id":"exchange-166"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その中に地域移行の希望を、ぜひ区内、区外の入所者が今、２８１名ということで計画書にも書かれていますけれども、この方にもぜひ意向を確認して、区はグループホームに入りたいという希望がある人がどれくらいいるのかということをまずは把握していただきたいと思うのですけれども、その点についてもお聞かせください。","respondent":"中山障害者福祉課長","answer":"この間、実施計画上では、民間活用型ということで、毎年２つ分のグループホームの建設の準備はしているところです。ただ、区が主導となって区立で建てるという計画は、現在、持ち合わせていないです。それから、区外の利用者の方への意向調査というところになります。","voiceIndex":385,"id":"exchange-167"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今も民間主導でということなのですけれども、私は、林試の森隣の荏原地域に、１つのグループホームも就労支援Ｂ型もないというところで、先日も厚生委員会でこのことが議論されたところですけれども、ぜひ荏原地域につくっていただきたい、これは行政需要ということであれば、最も高い行政需要の１つではないかと思うのですけれども、いかがでしょうか。","respondent":"中山障害者福祉課長、柏原企画調整課長","answer":"計画相談の中では、中期目標、長期目標みたいなものも立ててまいりますので、丁寧に相談に乗る中で、今後の生活、在宅から例えばグループホームで自立した生活をしたいというようなところも聞き取っていけるように。これは行財政改革特別委員会でもご報告申し上げたところですが、こちらについては購入に向けて、今、調整をしているといったところで、使用の用途については、地域のにぎわい、それから防災の強化というところを軸にしながら。","voiceIndex":387,"id":"exchange-168"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ぜひ行政需要が最も強いというところで計画に入れてください。それから、今年の施政方針の中で、今度できる障害児者総合支援施設に対して、区長が、全国的にも類を見ない施設ということで言われたのですけれども、この全国的にも類を見ないというのは、どういう意味なのかについてお聞かせください。","respondent":"中山障害者福祉課長","answer":"併設される美術館ですとか、あるいはパフォーマンススタジオ、こうしたところを使いながら、地域にも広げていけるような、そんな施設になればと考えているところです。","voiceIndex":390,"id":"exchange-169"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川よりもかなり規模も大きいというところなのですけれども、そういう点では、私はここを１カ所だけにしないで、荏原地域からはあそこまで通うのはなかなか厳しいものがありますので、今度できる施設に加えて、私は、荏原第四中学校跡に、ぜひ第２の総合支援施設をつくっていただきたいと要望させていただきまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":392,"id":"exchange-170"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうしたときに、先ほど、居住支援協議会というお話もしましたけれども、都の住宅供給計画案も示されている中で、賃貸住宅の確保、供給、これについて、やはり各自治体も居住支援協議会を立ち上げ、こうしたことを検討していくことが大事であるというふうにもうたってありますけれども、その点はいかがお考えでしょうか。","respondent":"松山高齢者地域支援課長","answer":"委員おっしゃられる居住支援協議会につきましては、東京都の居住支援協議会にオブザーバーとして私どもも参加しています。他区の先駆的な動向を見極めながら、今後、検討してまいりたいと考えています。","voiceIndex":394,"id":"exchange-171"},{"speaker":"こんの委員","kind":"質問","question":"でも、町なかには、空き家、空き室がたくさんある。これが活用されていないというところで、私は、福祉の部分と住宅の部門とがやはり連携をしていかないと、このことはソフト面でやっていただく大変にありがたい制度だからこそ、それを生かすために供給する物件、そうしたことへの流れをつくるためにも、住宅課を中心とする居住支援協議会が必要であると考えますけれども、いかがでしょうか。","respondent":"長尾住宅課長","answer":"ただ、個別に丁寧にお話をいろいろな主体の団体等も含めて話を伺う中で、困難な事例を解決しているというところも同時に伺っているところです。そういった機能を居住支援協議会も一定果たしているところは認識しております。","voiceIndex":396,"id":"exchange-172"},{"speaker":"こんの委員","kind":"質問","question":"そうしたことも活用できるでしょうということと同時に、品川区としては、新しい事業として、高齢者地域支援課でこうしたソフト面もしっかり立ち上がるわけですから、そこと連携をしたら、この国交省が出している補助金も使いながら、きちんと手当てができるのではないかと考えるからこそ、そのほかにも理由はありますけれども、居住支援協議会が必要であると、このように思っております。次に行きます。","respondent":"大関教育総合支援センター長","answer":"防犯カメラ等につきましては、警察等関係機関の要請には、柔軟に学校は即対応しておりますが、そのほか地域の方、あるいは警察署の方などをお呼びして防犯教室を子どもたちだけでなく、保護者も対象に開くなど、さまざまな形で検討を進めてまいりますので。","voiceIndex":398,"id":"exchange-173"},{"speaker":"こんの委員","kind":"質問","question":"今のご答弁のとおりだと思うのです。いろいろな人が入ってきます。そうしたことを考えたときに、その不審者、侵入してくる者を防御する体制にはなかなかない。そうしたことを考えたときに、学校の裁量で何か防犯対策を打ちたいといったときには、どういったことまでできるのでしょうか。","respondent":"大関教育総合支援センター長","answer":"現状におきましては、今、委員よりご指摘ございましたように、入り口での名札等の確認の徹底ですとか、ＰＴＡの協力も得ながら人を配置する等もしておりますが、さらに、例えばさすまた等をもう少し数を増やすですとか、そういった相談がありました際には。","voiceIndex":400,"id":"exchange-174"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、具体的なものが出ました。さすまた、これは、改良されたものが出ておりますので、もし学校裁量で購入ができるのであれば、それをぜひ支援をしてあげていただきたいと思います。教育委員会全体でそろえるというのは非常に難しいと思いますが、学校裁量でできるようお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":402,"id":"exchange-175"},{"speaker":"渡部委員","kind":"質問・要望","question":"１４０ページの東京臨海高速鉄道株式会社貸付金返還金に関連して、りんかい線について伺うのですが、済みません、数字を少し聞いていきますので、お答えできる範囲でお教えいただければ、確認を含めてですのでお願いいたします。ここ数年来、１億８,０００万円でしょうか、貸付金が戻っています。その都度、事前に定められた授権資本の中で増資をされていっているのか教えてほしい。","respondent":"中村都市計画課長","answer":"毎年利益に応じて増資も、これは利益追求の企業ですので、この辺は経営方針に従って、減資はなかったかと思いますが、増資が繰り返されているです。","voiceIndex":404,"id":"exchange-176"},{"speaker":"渡部委員","kind":"質問","question":"今の増資のところがちょっとわからなかったのですけれども、要は、平成２０年のところで１.７７％ですよね。だとしたら、品川区が今まで幾ら資本金を入れていて、増資のときには品川区も入れたのか、逆に、増資になることによって品川区のパーセンテージが下がってきたのか、その細かい金額は結構ですから、その辺の考え方を教えてください。","respondent":"中村都市計画課長","answer":"品川区といたしまして、この東京臨海高速鉄道株式会社にかかわっている部分といたしまして、貸付金と、それから持ち株分の比率に応じた金額です。資本にかかわるところは以上です。","voiceIndex":406,"id":"exchange-177"},{"speaker":"渡部委員","kind":"質問","question":"済みません、私の認識違いだったのか、貸付金の残金もこの資本の中に入っているということなのでしょうか。それ以上にりんかい線に対して、例えばＪＲから何かアプローチがあったのかとか、国土交通省とのやりとりがこの数年間で何かあったのか、あれば教えてほしい。この数年間の中でそういう動きがあるのかどうなのか、品川区は働きかけができるのかどうなのか教えてください。","respondent":"中村都市計画課長","answer":"ただ、この空港線につきましては、空港の動き、またＪＲ、それからりんかい線、さまざまな事業者が関連をしているところから、まだ実現というところの具体的な話には至っておりませんけれども、まず、りんかい線も将来的にそういった発展性については認識を持っているですので。","voiceIndex":408,"id":"exchange-178"},{"speaker":"渡部委員","kind":"提案","question":"ただ、この事業計画年度が２０３０年ですから、今の今という話では全くないと思うのですけれども、ぜひ品川区も株主にはなっておりますので、しかるべき時期に、そのようなことができるように、にぎわいづくりにもなりますので、ぜひぜひ進めていただきたいと、これは要望しますし、また、何年か後に質問が出てくるかもしれませんので、よろしくお願いいたします。","respondent":"柏原企画調整課長","answer":"そのやり方等については、関係部門とも共同して検討していきたいと思いますけれども、区全体、区民の皆様全ての課題として捉えていきたいというふうに思ってあります。","voiceIndex":410,"id":"exchange-179"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1074#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":120504,"voices":413}},{"id":"h30-20180306-10","meetingId":"h30-cm03","date":"2018年3月6日","dateIso":"2018-03-06","committee":"議会運営委員会","time":"午後 ５時５２分～午後 ６時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議会報告会等準備会議からの報告事項","agenda":"議会報告会等準備会議からの報告事項","exchanges":[{"speaker":"たけうち委員","kind":"意見","question":"お手元、資料５のとおりです。新たなところは、５のワークショップによる意見交換が「品川の魅力発見！」というところに決まりました。今までと変わりございません。既に会派を通じてご案内になっている日程かと思いますが、ここにはありませんけれども、４月２３日（月）午後１時半から第１委員会室で、全体リハーサルをやらせていただくことになっていますので、合わせてご報告します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5266#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":3804,"voices":25}},{"id":"h30-20180308-3","meetingId":"h30-c-budget","date":"2018年3月8日","dateIso":"2018-03-08","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"本日の議題に入ります。 第５号議案、平成３０年度品川区一般会計予算","agenda":"本日の議題に入ります。 第５号議案、平成３０年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"私からは、１７７ページ、補助２６号線開通記念事業、そして、もう一つが１７３ページ、公有財産管理費の中の豊町一丁目遺贈物件解体等工事についてお伺いいたします。初めに、１７７ページ、補助２６号線開通記念事業についてお伺いいたします。当初の予定ですと、開通が平成３１年３月ということだったのですけれども、変わりがないのかお知らせいただきたいと思います。","respondent":"中村都市計画課長","answer":"予定の変更があるとは聞いておりません。途中、ＪＲ横須賀線の地下を、浅いところを掘ったり、あるいはこれから隣接地の配管が複雑に関連するところ、こういったところの難工事がまだ残っているですけれども、現在のところは、工期は来年３月です。","voiceIndex":6,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"意見","question":"来年３月ということで予定しているということで了解いたしました。これは２,０９９万円余という記念事業の金額なのですけれども、この内訳、あと運営をどういうふうにされていくのかを、お知らせをお願いしたいと思います。","respondent":"伊崎地域活動課長","answer":"運営ですが、開通の記念式典あるいはイベントに向けまして、地域の方を中心とした実行委員会を設置いたしまして、そちらの中で事業内容等を検討していただくということになっております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"意見","question":"事業、イベントの内容ということで、実行委員会がもう既に開催されているのか、いないのか。そして、２００６年に東海道４００年祭で記念事業がありました。その中でも記念パレード等をして、約２０基のおみこしが出て渡御があったということで、今回の補助２６号線の記念事業についても、みこしの渡御があるのか、ないのか。それを、お知らせをお願いしたいと思います。","respondent":"伊崎地域活動課長","answer":"地域の、特に荏原地区の町会長の皆様から、連合渡御をやりたいというお声を受けましたので、どういった形で実現できるかということは、今、鋭意、検討を進めているところです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"みこし渡御は、やはり荏原地区もありますので、荏原地区の方たちのおみこしの会等とも通じて、実行委員の方にもお伝えして、このお祭りの渡御はぜひ開催していただきたいと思います。続きまして、１７３ページ、公有財産管理費の中の豊町一丁目遺贈物件解体等工事についてお伺いいたします。これはまず、どういった経緯で取得したのかどうか、お聞きしたいと思います。","respondent":"立川経理課長","answer":"こちらは戸越小学校の前にありまして、ゆたか図書館、また、ゆたか教職員住宅の隣接地でございまして、２０年ほど前から、生前、いわゆる寄附の申し出というものを受けておりまして、それで昨年、持ち主の方がお亡くなりになりまして、区としまして寄附を受領したというものです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"意見","question":"遺贈の物件解体等工事ということで、２,２５０万円余という中で、私も現場を何回か見させていただきました。その中で、地形、形がいい土地で、木造２階、約５２坪、土地が約８９坪あります。そうすると、解体だけを考えると、坪当たりの金額がかなり高額になっていると思うのですけれども、解体等という中で「等」というところで、解体以外の工事があるのか、ないのか、お聞かせをお願いしたいと思います。","respondent":"立川経理課長","answer":"これは、解体のほか、整地をいたしまして、アスファルト舗装にする。スロープを築造する。そういった経費を含めて２,２５０万円余です。","voiceIndex":14,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２,２５０万円余ということで、単純に考えても、かなり金額が、それこそ少し高台というか、根切りして地べたを整地しなければいけないというのもあると思うのですけれども、その辺についてもう少し詳しく教えていただければと思います。","respondent":"立川経理課長","answer":"こちらは、一般的に考えて、確かに高いです。ただ、東京都の最新の積算単価、また国の最新の労務単価といったところから積算いたしますと、こういった額が出たです。","voiceIndex":16,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"わかりました。では、ぜひそれはまた、整地をしていただいて、やっていただきたいと思います。それで、今後の活用方法、そして今後のスケジュール感をお知らせいただきたいのと、隣接している、ゆたか教職員待機寮の活用方法とスケジュール感をお聞かせいただければと思います。","respondent":"柏原企画調整課長","answer":"近くの公園も今後、工事が入ったりというところがありますので、一時、暫定的な活用というのも考えられるかと思いますけれども、トータルで見ながら、解体後の活用については今後、検討していきたいと思ってあります。","voiceIndex":18,"id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今後の活用方法がまだ未定だということで、特に戸越公園のほぼ前面にあるということで、しばらく整地して、その状態で放置していくのだと思うのですけれども、そこで一定期間の活用方法として、例えば駐車場貸しとか、そういうのもあると思うのですけれども、その辺のところをもう一回、お聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"本格的な活用は今後検討というところで引き続きやっていきます。今、委員におっしゃっていただいたように、戸越公園があります。それから戸越公園の中も工事が今後見込まれますので、そういったところの暫定的な活用というのもあわせて検討していきたいと思ってあります。","voiceIndex":20,"id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ有効に活用していただきたいと思います。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"平昌オリンピックでは日本人選手が大活躍で、過去最高の１３個のメダルを獲得いたしました。これまでオリンピック・パラリンピック準備課、商業・ものづくり課、文化観光課、また道路等も含めて建築課でしょうか、それぞれ対応していただいたと思いますけれども、できたら、この商店街の皆様と各課とが一堂に会する場を設けていただいて、声を聞いていただきたいと思いますが、いかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"個別にはいろいろやっているところではありますが、委員ご指摘のように、商店街のほうでお声があり、一堂に会するような場を設けてほしいということでありますれば、準備課が中心となって、そういった場は積極的に設けてまいりたいと考えています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。そのお声を聞く中で、商店街にフラッグがもらえるのだと、喜びの声がありました。このフラッグとはどういうものかお知らせいただきたいと思います。オリンピック・パラリンピックに関してはさまざまな規制があると聞いておりますので、取組みの様子を教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"現在、大会組織委員会に申請中でございまして、許可の関係が、時間がかかっているところではありますが、こちらが実現しました折には、この実例を他の商店街にも展開していければと考えているところです。","voiceIndex":26,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"大変に楽しみにもしておりましたので、よろしくお願いします。さらなる機運醸成のため、２点要望します。飾っていただくところに、ただ置いてあるだけではなくて、一言、説明書き、オリンピックの競技なのですよ、こういう内容なのですよというようなことを、ぜひ添えていただきたいと思いますが、いかがでしょうか。この２点をよろしくお願いいたします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"施設によっては、独自に説明書き等を書いていただいているところもあるのですけれども、そういったご要望を踏まえまして、オリンピック・パラリンピック準備課として、展示する意味やルールの説明等を書いたひな形を各施設に配付してまいりたいと考えております。","voiceIndex":28,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"次の質問にいきます。自動通話録音機購入についてお伺いいたします。いまだなくならない振り込め詐欺などの特殊詐欺のことについてお伺いしたいと思います。全国では、平成２９年度の被害額は、何と８０億円に上っているということです。全国のこの数字を受け、品川区の現状がどのような現状なのか、そしてまたそれをどのように認識されているのか、お伺いいたします。","respondent":"菅生活安全担当課長","answer":"中でも４つの類型に分かれますけれども、オレオレ詐欺、架空請求、融資保証金、それから還付金の４つに大きく分けられるのですけれども、特にオレオレ詐欺と還付金のほうが大幅に増えているという状況です。","voiceIndex":30,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"本当にすごく大きな数だと思います。品川区は、これまでに、平成２８年度４００台、平成２９年度５００台、また新年度も５００台ということで、この自動通話録音機を高齢者の方に貸与されておりますけれども、数が倍増になったということですので、これが始まってからの効果が出ているのか、どうなのかというところでの、効果的なところを教えていただきたいと思います。","respondent":"菅生活安全担当課長","answer":"件数なのですけれども、自動通話録音機の購入台数につきましては、平成２８年度が４００台です。本年度が５００台。来年度は、また東京都の助成を活用しまして５００台を購入する予定ということで、合わせて来年度中には１,４００台ということになるかと思います。","voiceIndex":32,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問","question":"やはり、抑止力にはなっていると思います。それで、現在、品川区では、ひとり暮らしの高齢者、また高齢者のみの世帯が約２万２,０００人ぐらいいらっしゃるのではないかと思うのです。その中で１,４００台というのは、数的にはまだ足りない。本当は、高齢者世帯の皆様のところには、全ご家庭に配置してもらいたいぐらいの思いなのですけれども、さらに増設を望みたいと思いますが、いかがでしょうか。","respondent":"菅生活安全担当課長","answer":"都の助成を使っているということもございまして、都の予算を見ながらということになるかと思います。区内の発生状況、それから区内各警察署のご意見を聞きながら、購入数は増やせれば増やしていきたいと考えているところです。","voiceIndex":34,"id":"exchange-015"},{"speaker":"新妻委員","kind":"提案","question":"戸籍事務費についてお伺いいたします。昨年の１１月２２日のいい夫婦の日から、私が提案させていただきました、オリジナル婚姻届の配布がスタートいたしました。この状況をお聞かせいただきたいと思います。あわせて、新年度の予算でオリジナルの出生届が作成されるですが、いつぐらいから始まるのかというところを教えてください。","respondent":"提坂戸籍住民課長","answer":"こちらについても、新たに誕生されたお子様の記念になるようなもの、お父様、お母様が記念になるようなもの、それから誕生されたお子様が大きくなってからご覧になって記念になるような、かわいらしいようなデザインのものを考えているところですけれども。","voiceIndex":36,"id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひ、いい、かわいいデザインをお願いいたします。そして、婚姻届も、１１月２２日以前に出された方もさかのぼってお渡ししていただいておりましたので、オリジナル出生届におきましても、そのスタートの日以降だけではなくて、さかのぼって、ぜひ配布していただきたいと思いますが、いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"オリジナル出生届についても、さかのぼって欲しいという方がいらっしゃれば、こちらから差し上げる予定です。","voiceIndex":38,"id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、選挙費についてお伺いいたします。今年は９月に区長選が予定されております。障害のある方のためのわかりやすい演説会、また模擬投票等を要望します。これは、育成会の方からもご要望をいただきました。今年の９月の区長選の前に、模擬投票、またわかりやすい演説会をぜひ開催していただきたいと思いますが、いかがでしょうか。","respondent":"安井選挙管理委員会事務局長","answer":"知的障害者の団体に対する模擬投票の実施ですけれども、こちらについては前回１度やっております。新たにそういうご要望があれば、ご相談に応じて、選挙期間中ではなかなか難しいので、時期等も含め検討してまいりたいと考えております。","voiceIndex":40,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"１６９ページの人権啓発費、多様性尊重啓発講座について伺いたいと思います。私はたびたび、性的マイノリティーなど多様な性のあり方や生き方を認め合い、誰もが自分らしく生きることができる社会の実現を取り上げてきました。この多様性尊重啓発講座について、どのような事業なのかお伺いしたいと思います。そして、改めて性の多様性について、第５次行動計画策定ではどう位置づけるのか、ご説明ください。","respondent":"島袋人権啓発課長","answer":"１つの柱として、やはり多様性に関することは重要であると認識しております。","voiceIndex":43,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回のこのような講座を通じて、品川区としても、性的マイノリティーなど社会的少数者が自分らしく生きることを応援しているということを、しっかりとアピールしていただきたいと思いますけれども、いかがでしょうか。そして、当事者の力に、さらには応援するアライを増やしたり、職場のセクハラをなくしたり、家族や友達の力になっていただきたいと思いますが、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"こちらの講座に参加された方たちに、上映会にももちろんそうなのですけれども、アンケートを実施させていただきまして、今後、男女共同参画センターにおきまして、交流室事業等の検討の参考にさせていただきたいと思っているところです。","voiceIndex":45,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"こうしたことも大事だと思うのですけれども、いかがでしょうか。参加者に区のカウンセリング相談を紹介したり、また、こうした事業は継続性が大事だと思いますので、継続的に実施したり、男女共同参画センターのフリースペースや会議室で区民の自主活動につなげたりと、今回の講座を機に次のステップにつながるような工夫も進めていただきたいと思いますが、それぞれいかがでしょうか。","respondent":"島袋人権啓発課長","answer":"なかなか、マイノリティーの方が直接、私どもの計画します講座に足を運んでくださるかというと、その辺は非常に慎重に検討していく必要があると考えております。初めに、私たちが考えたところは、区民の皆様にマイノリティーに対する理解を持っていただくこと。","voiceIndex":47,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"長期基本計画の改訂についても伺いたいと思います。先ほど、第５次行動計画の位置づけについてはお伺いしましたけれども、長期基本計画について、本会議では、「必要があれば盛り込んでいきたい」というご答弁だったと思います。そして、改訂については、必要があれば盛り込んでいきたいということですけれども、私は必要だと思うのですけれども、それぞれいかがでしょうか。","respondent":"柏原企画調整課長","answer":"今後、策定にあたっては、こういった課題を含めて、トータルの中で、どういう問題意識を持っていくかというのは検討を深めていきたいと思ってあります。","voiceIndex":49,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"改訂の中で、その一つとして進めていきたいというお話ですけれども、もう少し伺いたいのですけれども、性の多様性についての理解や、性自認や性的指向について理解していく、差別をなくしていく。さまざま、社会でもテレビでも生活の中でも取り上げるようになってきましたので、ぜひ改訂の中で、性の多様性について位置づけていただきたいと思うのですけれども、改めていかがでしょうか。","respondent":"柏原企画調整課長","answer":"そういったものの一つ一つに対して、区としてどう取り組むべきなのかというところを考えながら、今、検証作業、それから今後の改訂作業に向けて進んでいきたいと思ってありますので、そういった視点で、こういった課題についても検討を深めたいと。","voiceIndex":51,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"自分をどう思うのか、どうありたいのか。昨日ですけれども、住民票や印鑑登録書の申請用紙も確認しましたけれども、性別表記はないということも確認させていただきました。この男女共同参画のための品川区行動計画と長期基本計画の改訂を機に、もう一度、総点検していただいて、性別表記の必要性を確認していただきたいと思いますけれども、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"確かに、平成１６年の３月にですけれども、当時の総務部長名で通知を出させていただいているものがあります。この中には、「今後、新たに様式を定めるもので、性別記載等を設けようとするものは、その必要性について十分検討すること」とあります。","voiceIndex":53,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"平成１６年のときに一度見直しを行ったということですけれども、それから大分、日もたちますし、さまざまな書類やさまざまな申請用紙もあるかと思いますので、今回、改訂を機にぜひ総点検をしていただいて、また、こういう改訂の機に、また職員の方の研修や意識づくりにもつながっていくと思うのですけれども、改めて、この改訂を機に総点検をしていただきたいと思いますけれども、いかがでしょうか。","respondent":"榎本総務部長","answer":"今、申請用紙の件がありました。既に過去にもそういう調査をいたしましたけれども、その間、時間がたっておりますので、その部分を十分加味しながら、点検したほうがいいのかどうかなど、その辺は庁内で検討を進めてまいりたいと思います。","voiceIndex":55,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-026"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１９３ページのスポーツ推進費、全国大会等出場者支援について、それに関連して質問します。しっかりと推進していただきたいのですが、いかがでしょうか。内容の充実というのは、近年、やはりクラブ活動、いろいろな部分で費用がかさむケースがありますので、そういった部分も含めて助成金の増額を、以前にも質問させていただきましたが、前向きにお考えいただきたいということが１点。","respondent":"池田スポーツ推進課長","answer":"全国大会出場支援事業につきましては、平成２８年４月から実施している事業でございまして、平成２９年度から内容を一部変更しています。","voiceIndex":59,"id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひ実効性の担保がなされるよう、しっかり周知徹底をしていただきたいと思います。これは多少、教育費に触れるかどうかはわからないのですけれども、触れてしまったら、関連なのでお許しいただきたいと思いますが、品川区児童・生徒教育長表彰というのがあると思います。非常に少ない。卒業後に受賞該当者が判明した場合、どういった対応をされるのかということをお聞かせください。","respondent":"大関教育総合支援センター長","answer":"そのほかに、善行部門としても、地域のさまざまな活動に努力した児童生徒を表彰することで、身近な人々のために貢献する、あるいはほかの模範となるような子どもたちをたたえることで充実させてまいりたいと考えております。","voiceIndex":61,"id":"exchange-028"},{"speaker":"いながわ委員","kind":"質問・要望","question":"どのようなスポーツ、文化、芸術に携わっているかというのは、保護者はもちろん、自分の子どもたちですから知っていると思うのです。では、結果はどうだったの。これは本当に申し訳ないですが、１つ事例があったので質問しています。それをしっかり連携をとってやっていただきたいのが１点と、新しく来た先生、既存の先生に対しても、いま一度、周知していただきたいと思いますが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"大会への参加費助成等を含めまして、また表彰につきましても、学校に周知徹底してまいりたいと考えております。","voiceIndex":63,"id":"exchange-029"},{"speaker":"いながわ委員","kind":"質問・要望","question":"とにかく連携をしっかりとしていただきたいと思います。続いて、１９５ページ、パラリンピックの啓発講演会についてであります。今年でたしか４年目になると思いますが、パラリンピック啓発講演会、１月２６日にスクエア荏原で開催されました。こうした取組みを、今後、東京２０２０大会に向けてさらに推進することは、大変重要なことと考えておりますが、いかがでしょうかというのが１点。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"３５３名の方が参加していただきまして、講演後のアンケート調査でも１００％に近い方が満足を感じていらっしゃったという結果です。こうした取組みは東京２０２０大会に向けてさらに充実させてまいりたいと考えています。","voiceIndex":65,"id":"exchange-030"},{"speaker":"いながわ委員","kind":"質問・要望","question":"最後にホスピタリティハウスの誘致調査なのですが、今年度もこの予算は３００万円余ぐらい、たしかついていたと思います。来年度にも４５８万４,０００円ということで予算がついておりますが、今、現状、どういう状況、進展があるのか、ないのか、言えないこともあろうかと思いますので、その辺は言わなくて結構なので、話せる範囲でお願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"具体的に、まだマッチングというところまでは至っていないのですけれども、平成３０年度につきましては、さらに具体的なプロモーションを進めてまいりたいと考えているところです。","voiceIndex":67,"id":"exchange-031"},{"speaker":"いながわ委員","kind":"質問・要望","question":"よろしくお願いします。リオを視察に行って、いろいろヒアリングをした中で、やはり１年８カ月前、ほぼ２年前には大体もう決まっていて、あとは段取りをどうするかとか、どういう工事日程でいくかという話になってきていると思いますので、今回、来年度１年間で、早い段階で方向性をしっかりと見出していただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"１６３ページ、シティプロモーション推進経費、１６５ページ、区民相談経費、同じくペーパーレス会議導入検討費、１７１ページ、被災地支援事業、同じく職員研修費、同じく働き方改革推進事業、１７３ページ、庁舎管理費、１７７ページの補助２６号線開通記念事業、１８１ページの歩行喫煙防止推進経費、同じく生活安全推進事業、１８３ページ、市町村交流事業、１８５ページ、明治維新周年関連事業、同じく。","respondent":"木村報道・プロモーション担当課長、中元広報広聴課長、立川経理課長、仁平情報推進課長、黒田人事課長、伊崎地域活動課長、菅生活安全担当課長、鈴木文化観光課長、池田スポーツ推進課長","answer":"年齢を重ねているということで、いろんな方とお話しするというところの接遇のところでも一定程度の対応が可能ということで。こちらについては、まず都から、至急撤去してほしいという要請もありますので、優先順位をつけて。導入予定の会議ですけれども、具体的にどうという方向性は、まだ決めてはおりませんけれども、例えば定例の課長会等、事務連絡等で。働き方改革につきましては、人事課としましては、企画調整課で行っております、いわゆる業務分析と連携しまして、公務能率の向上を図って。","voiceIndex":71,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"総務管理費、情報公開等経費について伺います。東京都は手数料を無料にしました。品川区でも無料にするべきだと思いますが、本日伺いたいのは手続の書式についてです。選択肢には、閲覧とコピーの交付という別の項目もあるのに、結局、書類の写しの交付と閲覧料が求められてしまうケースがあります。情報公開請求の書式に、閲覧ができない場合もあると記すべきではないでしょうか。","respondent":"中元広報広聴課長","answer":"初めに、私のほうで前回答弁した内容を、少し修正させていただきたいと思います。閲覧というところなのですけれども、情報公開制度というのは、そもそもが、お見せする、閲覧するというのが基本的な考え方となっております。","voiceIndex":83,"id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"実際に閲覧だけを求めたときに、閲覧ができない場合があるのです。それについては明日やろうかと思うのですけど。それで、繰り返しますが、本来は手数料は無料とするべきです。もし手数料を残すとしても、閲覧という項目だと紛らわしいと思います。表記と実態の整合性をつけてほしいと求めますが、いかがでしょうか。閲覧だけで対応した件数をお知らせください。","respondent":"中元広報広聴課長","answer":"それで、閲覧ができないというものは、やはり、もとの文書が存在しないとか、そういうものにつきましては、当然、閲覧ということもできなくなってくるです。すみません。この閲覧だけの件数というのは出てきません。","voiceIndex":85,"id":"exchange-035"},{"speaker":"田中委員","kind":"提案","question":"次にいきます。人権啓発費、男女共同参画推進事業について伺います。昨年の予算特別委員会で、ＤＶ月間について、パネルの展示を提案しました。それができないという法的な根拠はあるのでしょうか。教えてください。ところが、仮の申出書の表記が、「仮」だとわかりづらいため、生活者ネットワークは、書式を見て、一目で「仮」だとわかるように改善するよう求めましたが、何か工夫をされたのか伺います。","respondent":"島袋人権啓発課長、提坂戸籍住民課長","answer":"最初にパネルの件です。１１月１２日から２５日にかけまして、「女性に対する暴力をなくす運動」という週間があります。今年度は、１１月に開催予定ですフォーラムの中で、パネルを借りることによりまして展示する予定です。ただ、例外的に、警察へ行っている時間がないということでご相談をお受けした場合は、先ほどおっしゃった、申出兼職権処理書でお受けするのですが、この申出兼職権処理書というのは、ＤＶの対応だけのためのものではなくて。","voiceIndex":87,"id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"だから仮なのです。そして、加害者に被害者の情報が漏れるということは、本当に命に関わることなので、書式の改善を早急に求めます。申請書の２段階の書式を、資料として男女共同参画の窓口に置いておくことや、資料とわかるように、相談に来られたＤＶ被害者の方へ渡してもよいのではないでしょうか。なので、自治体間ではできているのですから、同じ自治体の中でもできるのではないでしょうか。伺います。","respondent":"提坂戸籍住民課長","answer":"「仮」の表記については、ほかの事例、理由の方もいらっしゃいますので、その辺は少し研究します。男女共同参画センターの窓口で、申出兼職権処理書と支援措置申出書を置くか、置かないかということについても、人権啓発課と検討を重ねてまいりたいと考えております。","voiceIndex":90,"id":"exchange-037"},{"speaker":"田中委員","kind":"確認","question":"では次にいきます。生活安全推進事業と青少年健全育成事業について伺います。地区委員会の調査は、東京都青少年の健全な育成に関する条例が制定される前から独自で行っているということを議事録で確認しています。調査報告書を地区委員が警察署に報告されたと伺いましたが、その後、報告書はどのような取扱いをされるのか、区は把握しているのでしょうか、伺います。","respondent":"伊崎地域活動課長","answer":"区といたしましては、こちらの調査を行うことで、今、委員がご指摘のとおり、地域のＰＴＡ、地区委員たちが、きちんと青少年の健全育成について、不健全図書などの見回りをすることで地域浄化に努めているということを。","voiceIndex":92,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"都条例では、本の陳列などは店舗側の努力義務としていますが、地区委員会の調査結果を活かし、区でも何らかの制度をつくっていくべきだと考えます。地区委員会の調査結果を活かし、子どもや保護者、区民の声を反映させ、青少年の健全な育成環境を整備するためにも、成人向け雑誌を子どもの目に触れない位置への陳列の工夫を店舗に求められるような制度の構築を求めますが、いかがでしょうか。","respondent":"伊崎地域活動課長","answer":"これからも、そういった地域に密着した視点での健全育成という立場で、区としては進めていきたいと考えております。","voiceIndex":94,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"地域活動費、生活安全推進事業について伺います。１１０番通報があった後、警察から区へどのように情報が発信され、子どもたちや保護者、学校、すまいるスクール、保育園等へ情報が届くのか確認したところ、生活安全担当課と教育支援センターと子ども育成課の答えにずれがありました。この場で改めて伺います。１１０番通報があり、警察から情報が届いた後、どのように情報伝達がされるのか伺います。","respondent":"菅生活安全担当課長、大関教育総合支援センター長","answer":"そうした重要事案につきましては、教育総合支援センターあるいは子ども家庭支援センターに情報提供して、また危機管理室等にも情報提供しまして、広報・周知をしています。学校の場合には、まず教育委員会、教育総合支援センターのほうに、生活安全担当課長を通じて情報をいただいたりしたものを……。","voiceIndex":96,"id":"exchange-040"},{"speaker":"横山委員","kind":"質問","question":"私からは、１８５ページ、都市型観光プラン推進事業、１８７ページ、フィルムコミッション事業についてお伺いいたします。１点目は、フィルムコミッション事業についてお伺いいたします。今年度のフィルムコミッションの進捗状況と、開設予定のホームページの掲載内容について教えてください。あわせて、撮影誘致の方法と新ロケ地発掘の考え方についてもお聞かせください。","respondent":"鈴木文化観光課長","answer":"今後の誘致につきましては、ホームページや観光パンフレット、それからさまざまな媒体による情報発信を行って品川区をロケで使っていただけるよう取り組みたいと考えております。","voiceIndex":100,"id":"exchange-041"},{"speaker":"横山委員","kind":"提案","question":"来年の本格稼働に向けて、着々と進んでいるということを確認させていただきました。私は、平成２８年の第１回定例会において、区民参加型の映画祭の開催を要望させていただきましたが、例えば１つのステップとして、区民参加型の動画企画制作ワークショップを提案させていただきたいと思います。ロケ地といいましても、それは私たち区民の日常の中に存在しております。","respondent":"鈴木文化観光課長","answer":"ただ、文化観光課でやっていますフィルムコミッション事業というよりは、観光の情報発信、それからシティプロモーションでの魅力発信というところとの連携もかなり効果がありそうに考えられますので、今後少し具体的な方策について検討したいと考えております。","voiceIndex":102,"id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目は、都市型観光プラン推進事業についてお伺いいたします。観光フェア開催とイルミネーション設置についてお伺いします。昨年の決算特別委員会において、私は目黒区との連携を要望させていただきましたが、荏原地域における現在の他区・他団体・民間企業とのコラボレーションの事例をお知らせください。","respondent":"鈴木文化観光課長","answer":"西小山駅前における観光フェア、イルミネーションについてのご質問ですが、まず、イルミネーションは現在実施中ですが、昨年度に引き続きまして、地元の商店街の皆様の協力をいただきながら、区のイルミネーションによるにぎわい創出、集客と。","voiceIndex":104,"id":"exchange-043"},{"speaker":"横山委員","kind":"質問・要望","question":"引き続き荏原地域に重点を置いていただきながら、観光のほうも進めていただきたいと要望いたします。次に、明治維新周年関連事業についてお伺いします。次世代を担う若い方々に、これからの品川区、東京、日本のあり方を考えていただく機会としても、明治維新１５０周年記念イベントを活かしていただきたいと考えていますが、二十歳の龍馬企画をはじめとする区の事業内容と、期待する効果を教えてください。","respondent":"鈴木文化観光課長","answer":"その上で品川区の観光を楽しむというようなツアーも、また観光業界や観光振興協議会の皆さんと協議しながら進めたいと考えております。","voiceIndex":106,"id":"exchange-044"},{"speaker":"横山委員","kind":"質問","question":"体験して、強く心を動かすことによって、品川区の魅力アップですとか印象アップにつながっていくと思いますので、ぜひお願いいたします。品川歴史館と品川宿交流館における、明治期に関する文書や写真等の資料の収集・整理、またデジタルアーカイブ化の推進について、現在の区の取組み状況と今後の考え方を教えてください。","respondent":"鈴木文化観光課長","answer":"歴史館のほうでも、資料のデジタルアーカイブ化にも取り組んでおりますので、今後も地域と連携しながら、しっかりと遺産を残しながら活用するというところで取り組んでいきたいと考えております。","voiceIndex":108,"id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"国、他自治体、地域団体が主催するイベントなどの動きをキャッチしながら、品川区への来訪者の増加につなげていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-046"},{"speaker":"つる委員","kind":"提案","question":"最後の集会所用備品等購入ですが、これは、細かく見ていきましたら、地域センターにスピーチプライバシーシステムを導入するということで、２０１５年の予算特別委員会で、まさにこのスピーチプライバシーシステムそのものを導入したらどうですかという提案もさせていただいておりました。","respondent":"伊崎地域活動課長","answer":"スピーチプライバシーシステムですが、まず来年度、大崎第一地域センター、荏原第二地域センター、荏原第三地域センターの３カ所に導入いたします。これはモデル実施として行いまして、そちらでの状況を見ながら、全地域センターへの拡充を考えていきたいと考えています。","voiceIndex":113,"id":"exchange-047"},{"speaker":"つる委員","kind":"確認","question":"今回の代表質問の質疑の中にもありましたけれども、改めて品川区の基本構想を確認させていただいて、その策定にあたって、品川区基本構想の「かがやく笑顔住み続けたいまちしながわ」、その将来像、それから「暮らしが息づく国際都市」、「伝統と文化を育み活かす」、「区民と区との協働」の３つの理念を基本姿勢として、新たな長期基本計画を策定して、さらに総合実施計画。","respondent":"柏原企画調整課長","answer":"それで、総合実施計画は長期基本計画をさらに具体化するための計画。それから総合戦略につきましては、今回、この長期基本計画をもって総合戦略というのを長期基本計画の中に包含しながらつくっていければと思ってあります。","voiceIndex":115,"id":"exchange-048"},{"speaker":"つる委員","kind":"質問","question":"策定にあたっては、策定委員会と区民はもちろんのこと、さまざまな方が、品川区の将来像、それから３つの理念を実現して、何よりも区民の福祉向上に資する積極的な計画が策定されることを期待したいと思います。そこで、基本構想の３つの理念で最初に掲げられているのが、「暮らしが息づく国際都市」とあります。これはこの１０年の中でどのように実現されてきたか、簡単に教えてください。","respondent":"柏原企画調整課長","answer":"具体的なところで言いますと、交通の関係で言いますと、羽田空港の国際化であったり、それから今後リニア新幹線が品川駅から開通すると見込まれるというころがあります。","voiceIndex":117,"id":"exchange-049"},{"speaker":"つる委員","kind":"質問","question":"そこで、品川区もオリンピック競技の会場となる都市として、国際的な機運がこれからより一層高まっていくわけでありますが、さらにその先を見据えた国際都市品川区として、新たな長期基本計画策定にあたって、今いただいたご答弁も含めて、国際都市としての品川区の意思表示として、東京都や近隣自治体との連携も含めて、国際会議を誘致して。","respondent":"柏原企画調整課長","answer":"ということで、国際会議については、ぜひ品川区で開いてもらいたいとか、開くということでの動きというのは、ぜひとも検討していきたいとは思いますけれども、ただ、場所であったり、いろいろ課題もあると認識していますので、そういった課題の克服も検討しながら、そういった。","voiceIndex":119,"id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"次にいきたいと思います。これにまさに関連してということでお聞きしたいと思いますが、スクエア荏原の中にできるということで、１つは確認ですが、放送設備についての確認をしたいと思います。店内については、当然、ＢＧＭ等を流す関係でつけるのかと思いますが、当然、スクエア荏原ですから、もともと、そうした文化イベント行事が行われる場所でありまして、当然、広場にもいろいろな方々が集われる。","respondent":"鈴木文化観光課長","answer":"年に２度か３度ほど、地区のお祭りや町会のイベントのときに、以前、学校のときから使っていたという関係で特別にお貸しする場合があるだけですので、常設の音響を二、三度のイベント用に整備するという予定は現在ないというのが現状です。","voiceIndex":121,"id":"exchange-051"},{"speaker":"つる委員","kind":"質問・要望","question":"しながわ平和の花壇事業でありますが、これは何度も花という観点で訴えしていますけれども、ぜひオリンピックという１つの目標の到達点も含めてなのですが、区民の方にもご協力いただきながら平和の周知を図ってもらいたいというところで、私も映像でしか見たことがありませんが、ヨーロッパなどでよく見られるまち並み、路地裏等で、ウインドーボックスというのでしょうか、窓際に花を飾って。","respondent":"米田総務課長","answer":"次年度で一旦、平和の花壇事業ということで、カンナの花の植栽については一定の区切りを迎えることから、その後の区民への意識の醸成については、また改めて考えてまいりたいと思ってあります。","voiceIndex":123,"id":"exchange-052"},{"speaker":"つる委員","kind":"提案","question":"それで確認できましたので、ぜひ品川区内、コロンビア大使館をはじめ、１２の大使館、４つの領事館がありますので、より、関係する大使館といいましょうか、国といいましょうか、そうしたところとしっかりと今後も連携を図っていただいて、品川区との今後のさまざまな施策に発展できるようなホスピタリティハウスが誘致できるように、ぜひ積極的な検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":125,"id":"exchange-053"},{"speaker":"筒井委員","kind":"質問","question":"私からは、１６７ページ、新年賀詞交歓会経費、１９３ページ、区民スポーツ大会、１８１ページ、屋外における受動喫煙防止啓発に関連して質問します。ただ、これは無料です。それで、その原資は何かといいますと税金です。したがいまして、品川区も新年賀詞交歓会にあたり、１,０００円から３,０００円程度の会費は徴収するような形にすべきだと考えますけれども、区のお考えはいかがでしょうか。","respondent":"米田総務課長","answer":"この辺につきましては、今のところ、適切な食糧費の支出ということで考えておりますので、当面、このような形で続けるのが妥当であると私どもは考えてあります。","voiceIndex":127,"id":"exchange-054"},{"speaker":"筒井委員","kind":"提案","question":"会費を徴収している区も、そうした顔合わせ、親睦という形でやられているのですから、それはあまり理由にはならないと考えております。そういった面でも、またマラソンというのは何よりオリンピック競技ですから、品川区も、品川区のまちなかを走るマラソン大会、名前はどうするのかなど、いろいろとアイデアはありますけれども、そうした品川区のまちなかを走るマラソン大会はいかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"コースとしましては、一般の方１０キロと５キロ、小学生・中学生については２キロ・３キロということで、多くの方が参加されていまして、今年も来週３月１８日に大井埠頭でマラソン大会を開催する予定です。","voiceIndex":129,"id":"exchange-055"},{"speaker":"筒井委員","kind":"質問・要望","question":"これは要望で終わります。ですから、今、国は法律制定が混迷しておりますし、また東京都の条例はそれによっておくれておりますけれども、品川区は、そうした法規制の前に、啓発や、そうした国際標準の受動喫煙防止というのを、区民の方に周知・説明を積極的に行っていただきたいと考えておりますけれども、その点のお考えはいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-056"},{"speaker":"筒井委員","kind":"質問・要望","question":"オリンピックでは、受動喫煙防止対策というのは徹底されているのです。それで、区としてはやはり都と国の動向を見守るというお考えでしょうけれども、区としてやれるべきことはしっかりと、区民に対する、受動喫煙に対する啓発をしていく。そうした啓発をぜひとも行っていただきたいのですけれども、そのお考えはいかがでしょうか。","respondent":"川島健康課長","answer":"ただ、別の款のときにも説明させていただきましたが、区としましては法律や……。","voiceIndex":135,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"１７３ページの大崎図書館解体費用、大崎図書館について伺います。解体費用予算ですけれども、債務負担行為を含めて総工事費が１億４,４５０万円です。工事設計委託費は５９１万円。工事管理委託費が３０７万円。解体にかかる総予算は１億５,３４８万円だということになります。どのような改修工事だったのか、またその経費は幾らだったか伺います。","respondent":"横山品川図書館長","answer":"昨年のゆたか図書館の改修工事についてのお尋ねです。こちらの工事は、１０月１日から３１日まで閉館し、排水設備の改修と防犯カメラ設置、書架の入替え工事を行いまして、排水管工事、カメラにつきましては６３９万円、書架の入替えについては８８６万円を要しています。","voiceIndex":138,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"大崎図書館は１億５,０００万円かけて解体すると。今後のことについて、解体後のスケジュールをどう考えているのか。２９号線の事業代替地として都に協力することを表明してまいりましたが、その代替地の主要な候補となっている大崎幼稚園との話し合いは現在どうなっているのか伺います。大崎図書館の敷地、１,６８１平米の全部を道路代替地として都に売却する考えなのか、伺いたいと思います。","respondent":"柏原企画調整課長","answer":"我々といたしますと、図書館の跡地につきましては、そのときどきに、そういった事由があったときの協力をですので、そういった話し合いであるとか動きを見ながら、東京都に対しては協力をする姿勢ということで、話を見守っていきたいと思ってあります。","voiceIndex":140,"id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"品川区は大崎幼稚園とは一切話していないのか。活発な会議だったから、まだいいのですけれども、静寂な図書館だったらどうなのかと思わされました。区内に、ほかにこういったところもあるかもしれないのですけれども、そこでは問題や苦情というのは起きていないのでしょうか。今回の大崎図書館分館設置にあたっては、こうした体育館の振動や騒音の件は検討されたのか、されなかったのか、伺いたいと思います。","respondent":"横山品川図書館長、柏原企画調整課長","answer":"芳水小学校における大崎図書館分館の方針ですが、騒音等につきましては、最新の設備で防音するように検討してまいっているところです。私立幼稚園の支援という部分がありますので、所管部門においても、今後の幼稚園がどういった形がよろしいのかといったところの話はしておるものです。","voiceIndex":142,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"これは、音がしない、振動しないということでよろしいですか。しっかり伺います。それと、代替施設のほうには、文教委員会の資料によりますと、児童コーナー（調べ学習）という部屋もありますが、これまでのように近隣保育園がやってきて本を借りたりというようなことは保証されるのでしょうか。現在の保育園でどんなフォローを行うのか伺います。","respondent":"柏原企画調整課長、横山品川図書館長","answer":"先ほどと同様の答弁になってしまうと思うのですけれども、大崎幼稚園に対しては、東京都が道路のこういった開通の動きといいますか、そういった動きがありますというお話はさせていただいていることと、大崎幼稚園が移転等々して。これからの図書館についても同様に図る予定です。調べ学習というお尋ねだったと思うのですが、こちらについては、サービスについては引き続き行う予定です。","voiceIndex":145,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、生前、そもそもここは松原伝吉さんの強い気持ちもあって図書館用地として譲り受けたにもかかわらず、今回、移転して、道路の代替地にするというのは許されるのでしょうか。２つ目は、この日本庭園ですが、開館を知らせる当時の区報にもこうありますが、「区民の皆さんのご要望を入れ、松原邸跡地にあった樹木や庭石などを配置し、四季の美しさをたたえた日本庭園を中庭に再現」とあります。","respondent":"柏原企画調整課長","answer":"いずれにしましても、文教的なエリアという部分ですので、そういったところに資するような施設になればという願いを持ってありますけれども、そういった区の思いも、新しく譲渡といいますか、そういった部分において。","voiceIndex":148,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"ですから、去年の１１月のタウンミーティングでも、参加者の方、読み聞かせをしている方でしたけれども、大崎図書館を現在の場所に存続して、生涯学習の拠点として発展するようお願いしたい、利用者や図書館を必要としている方、環境・建物を大切に思っている方々の声をぜひ聞いてほしいと、大崎図書館の存続を希望する意見が出されました。それは何を指すのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"先ほどもご答弁申し上げたところですけれども、大崎図書館の部分に関しましては、先ほど申し上げた大崎図書館が行っていたビジネス機能の部分といったところが、新しく大崎の向かい側のところですけれども、反対側の部分で新しく開発されたところで。","voiceIndex":150,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"もう一度、先ほどの区長の回答を紹介しますと、残念だと。先ほど、他人事云々というのは撤回しますけれども、残念だと思っていると。ですから私は伺ったのです。移転の理由である地域のありようの変化とは一体何を指して言っていらっしゃるのですかということを聞いたので、これは区長にしかお答えできないと思うので、ぜひ答弁いただければと思うのですが。","respondent":"濱野区長","answer":"大崎のあのあたりの変化というのはご存知ありませんか。大崎のまちの変化というのをご存知ありませんか。もしご存知ないのでしたら申し上げますが、大崎というところは大きく変わりました。巨大なビルが建っている。あるいはビジネスの拠点になっている。","voiceIndex":152,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"まちのありようの変化と大崎図書館の移転は何が関係あるのですかと伺ったのです。これは、老朽化、老朽化と言っていたのですよ。まちのありようの変化が移転の理由にならないですよね。私はそこを言ったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-065"},{"speaker":"鈴木（真）委員","kind":"確認","question":"地区委員会関係です。地区委員会運営費は今年は２,７００万円の予算が立っていまして、前年比８００万円、これは事項別を見ていくと、６００万円は保険ということになっているから保険料だと思うのですが、その保険の内容について、１回、確認したいと思います。それからオリンピック関係です。先ほど来、ホスピタリティハウスの誘致というお話が何回か出ています。その点を教えてください。","respondent":"伊崎地域活動課長、小川オリンピック・パラリンピック準備課長","answer":"地区委員のほうの保険は、現在のところ、ボランティア保険を検討しているのですが、さらにいいものがあれば、そちらにしていきたいと考えています。参加者向けの保険は、傷害保険、賠償保険ということで考えております。ただ、区といたしましても、大会期間中に区内のホスピタリティハウスを設置したいということで、現在、調査検討をしているところで、このような中で、ＪＲ広町社宅跡地も１つの候補として現在も考えているところです。","voiceIndex":156,"id":"exchange-066"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"保険のほうはわかりました。それから、今までも事前キャンプというお話もあったのですが、今年の予算を見ていると、事前キャンプで９万３,０００円ぐらい計上しているのですけれども、これも、例えば今度、ブラインドサッカーの国際大会、日本を入れて８カ国の中で、そういうところにも積極的にお声をかけることはできないでしょうか。そういうことでお答えいただければと思います。","respondent":"伊崎地域活動課長、小川オリンピック・パラリンピック準備課長","answer":"区といたしましても、今回は地区委員会からのお声を受けまして、主に地区でのバスの経費ということで増額をいたしましたが、またお声を聞きながら対応していきたいと考えております。これは事前キャンプの誘致としても最大のチャンスだと捉えておりまして、各チームに事前キャンプについてプロモーションをしてまいりたいと考えているところです。","voiceIndex":159,"id":"exchange-067"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"地区委員会のバス代というお話を伺いました。それ以外にも、事業はまだまだ増やしていっていただきたいと思いますので、ぜひよろしくお願いします。ブラインドサッカーのほうも、ぜひ誘致に向けてお話を進めていただきたいのと、それから大井のホッケー場で、今度実際に開会になった後に、なかなかホッケーは人が集まりにくいと思います。その辺も検討していくことはできないでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"区といたしましては、かねてより、あれだけの公園が会場になるわけでありますので、ホッケー競技場だけではなく、同時に文化イベントやスポーツが体験できるような空間ができないかということは、準備局ですとか組織委員会には要望しています。","voiceIndex":162,"id":"exchange-068"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ、オリンピックのときには、そこに人に集まっていただきたいし、ホッケーはなかなか人が集まりにくいということを考えても、空席ができないように、とにかく品川区の子どもたちが、小学生、中学生が、ぜひこの会場に行って体験してくるということもやってもらいたいと。これは、答えにくいところもあると思うので、ぜひお願いしたいと思います。この辺について教えてください。","respondent":"柏原企画調整課長","answer":"そういったもの、諸々を、公有地検討の中でやっていきたいと思ってあります。","voiceIndex":164,"id":"exchange-069"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この金額で、どこまでボリュームを持ってやっていくのかと。それと、この中で質問しようと思っていたのは、品川消防署の出張所跡地も、前に濱野区長が都知事に会ったときにも要望したが、答えが出なかったというのが都政新報に出ていましたけれども、ぜひ活用もこれから考えてもらいたいと思うのですが、今、区として、あそこの行政需要は何か考えているということはあるのでしょうか。","respondent":"柏原企画調整課長","answer":"出張所の跡地につきましては、近隣に、区の施設であったり、いろいろありますので、そういったところの連携であったり、どういった形ができるのかというのを、研究といいますか、検討していきたいと思ってあります。","voiceIndex":166,"id":"exchange-070"},{"speaker":"木村委員","kind":"質問","question":"私は、１６５ページの上から７行目、人権の花運動からです。先ほども、ほかの委員からこの質問がありましたけれども、重複しないようにいきたいと思います。この運動は、昭和５７年から実施されて、小学校を対象とした人権啓発活動ですけれども、昭和５７年から行われている行事の一つだと思いますが、それで間違いないでしょうか。","respondent":"中元広報広聴課長","answer":"昭和５７年から開始ということで間違いございません。","voiceIndex":169,"id":"exchange-071"},{"speaker":"木村委員","kind":"意見","question":"都では、平成２８年度、区町村が１１５校、多摩西地区では３２校、多摩東地区では２８校、計１７５校が参加していますけれども、昭和５７年当時は、これほど大きな規模ではなかったのではないかと思いますけれども、大体どれぐらいの規模でスタートされたのか。この事業を始めてからの児童たちに何らかの変化が感じられることがあったのか、どうか。ふだんの授業に役立つことが何かあればお聞かせください。","respondent":"中元広報広聴課長","answer":"は１点目の、昭和５７年当時、開始当時の統計的なものが、すみません、持ち合わせてございませんので、そちらのほうはわからないところですが、こちらは学校で始めていただきまして、やはり学校内で、全校ではないのですが。","voiceIndex":171,"id":"exchange-072"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたしますけれども、品川区の歩行喫煙および吸い殻等のポイ捨て防止に関する条例が施行されてから、本年で１５年目になろうかと思いますが、現行の品川区の歩行喫煙防止は、施行された当初より、区民の感覚やマナーは目に見えてよい方向へと変わっていっていると感じますでしょうか。区民の皆さんがマナーアップされたと感じるかどうか、お聞かせください。","respondent":"菅生活安全担当課長","answer":"ポイ捨てや歩行喫煙につきましては、推進地区内を中心に取締まりをしておりますので、マナーの悪い喫煙者は減少していると認識しています。","voiceIndex":173,"id":"exchange-073"},{"speaker":"木村委員","kind":"意見","question":"２０２０年のオリンピック・パラリンピックが、あと２年後に迫ってまいりましたけれども、多くの海外からの来訪者が来日される中、マナーを守る日本、クリーンな東京、居心地のいい品川区を世界の人々に楽しんでいただくためには、行政としてこれから２年間、どのように指導していくのか、お聞かせください。","respondent":"菅生活安全担当課長","answer":"推進地区、それから推進地区外、それぞれ横断幕や路面表示シートといったものを、今、日本語以外の、中国語、英語、韓国語の４カ国語を表記したものを作成しておりまして、これを順次、２０２０年に向けまして、それぞれ張りかえて設置を増やしていきたいと考えているところです。","voiceIndex":175,"id":"exchange-074"},{"speaker":"木村委員","kind":"意見","question":"１８７ページの上から３行目、外国人観光客誘致事業。２年後に開催される世界のスポーツの祭典、オリンピック・パラリンピックをスタートラインにし、今以上に来訪者を迎えるため、品川区の魅力を発揮しなくてはなりませんけれども、水辺や歴史など以外にも、品川区をアピールするところがあればお聞かせください。","respondent":"鈴木文化観光課長","answer":"観光客、特に外国からの観光客に向けたアピールポイントですが、今年度の事業でも、外国人向けの観光ＰＲ動画を作成したときに、区内在住の方、またそのとき日本を訪れていた方のアンケート、それから座談会などで意見をいただいた中で、１つは商店街、生活に身近なところで。","voiceIndex":177,"id":"exchange-075"},{"speaker":"木村委員","kind":"意見","question":"もう時間がありませんけれども、２３３ページの下から９行目の青少年地域貢献活動支援事業費からですけれども、以前のしながわ役立ち隊から、事業名が変わりました。そういう中で、しながわ役立ち隊とは、中学生以上、おおむね２５歳ぐらいまでの青少年の組織を支えたボランティアグループですけれども、基礎的な、規約的なものというのは、そのまま受け継いでいるのかどうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":179,"id":"exchange-076"},{"speaker":"あくつ委員","kind":"提案","question":"そこで伺いたいのが、政府ＳＤＧｓ実施方針においては、各地方自治体に、各種計画や戦略・方針の策定や改定にあたっては、ＳＤＧｓの要素を最大限反映することを奨励するとあるのですけれども、今後、品川区におきましても、長期基本計画の策定委員会の策定作業の中において、各委員に対しても、ＳＤＧｓとはそもそも何なのかということ、また。","respondent":"柏原企画調整課長","answer":"今ご紹介いただきましたように、他自治体等いろいろ動きが出ているというのはありますので、これは十分勉強しながら進めさせていただければと思います。","voiceIndex":183,"id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問・要望","question":"決して国際協力の枠にとどめるべきものでもないと。続きまして、成人式経費です。それで、どのタイミングで出たり入ったりしたらいいのかというのが、やはり５階にいると全くわからないので、８階の状況を何かモニターできるような工夫をお願いできないでしょうかと、これはそこの職員の方にもおっしゃられていたのですけれども、ここについて私からもご要望したいのですが、いかがでしょうか。","respondent":"米田総務課長","answer":"ただ、ご要望の趣旨に沿って、いかなる合理的配慮を行っていくかということは、常に持ち合わせておかなければいけないと思いますので、ご要望の趣旨にどのように沿えるかということについては、考えをめぐらせてまいりたいと思います。","voiceIndex":185,"id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問・要望","question":"力強いご答弁だと思います。まさにそのとおりだと思いますので、どうぞよろしくお願いいたします。これもお聞かせいただきたいと思います。私どもも、昨年の水辺の観光フェスタで、東京のヘブンアーティストというところの方をお招きして、２組、１日やっていただいたということがあるのですけれども、これはどういうコンセプトでお考えなのか、この２つについてお伺いしたいと思います。","respondent":"鈴木文化観光課長","answer":"フィルムコミッションのほうのお尋ねですが、平成２９年度の成果といたしましては、平成３０年度からの本稼働に向けました体制整備のための調査、それからパンフレットやホームページ等、情報発信のためのツールの制作、それから各庁内や民間の土地のロケ候補地の選定や調整です。","voiceIndex":187,"id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問・要望","question":"フィルムコミッションを大事に育てていっていただきたいと思います。それと、スポーツフェスティバルですけれども、内容を見ると、非常にわくわくするような内容となっておりますので、期待しております。どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１５９ページの公有地活用等検討経費に関連して、荏原第四中学校跡地、小山台住宅跡地などについて質問いたします。荏原第四中学校跡地ですけれども、現在、暫定活用が示されて、区立保育園の改築や暫定保育園ということで、平成３５年度まで使うということになっております。その後の、平成３６年度以降の本格活用について検討されているのか、また検討されていたら、どう検討されたのか伺います。","respondent":"柏原企画調整課長","answer":"荏原第四中学校跡地の検討の状況です。暫定活用につきましては、今、委員にご案内いただいたとおりでございまして、その後の活用です。今後の検討ということで、細かい内容についてはこれからというところになってあります。","voiceIndex":191,"id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"校庭や体育館の利用も引き続きしていきたいということで、さまざまな意見が出されておる中で、やはり地元の住民の方の、また利用者の意見を反映させて、この跡地活用の検討をしていっていただきたいと思うのですけれども、住民参加を位置づけて、開かれた跡地活用検討委員会を立ち上げて、検討を進めていっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"さまざまな形での意見という部分については、これまでも地元の方々、いろいろな行政ニーズというところでお聞きしています。そういったところを勘案しながら、どういったものがいいかというのは、まずは区のほうで、十二分に検討してからということになってこようかと思います。","voiceIndex":193,"id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、そういった視点で進めていっていただきたいのですけれども、やはり地域に本当に必要な施設にするためにも、また地域に愛される施設にしていくためにも、計画段階からの住民参加が必要だと思いますので、それをしっかりと位置づけていただきたいと思いますし、そうしていくべきだと思いますけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"これまでも、こういった施設の検討といったところでは、我々も、手法といいますか、やってきたところですが、区の中での検討、それからさまざまなニーズを聞きながらです。","voiceIndex":195,"id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"議会などに聞いてというお話でしたけれども、議会にも聞いていただいて、そして利用者の方ですとか周辺住民の方も、ぜひしっかりと意見を反映していくために、開かれた跡地活用検討委員会を進めていただきたいというお話をお聞きしたので、そこのところをもう一度伺いたいと思います。","respondent":"柏原企画調整課長","answer":"再度のご答弁になってしまいますけれども、そういったご意見を伺うということは、これまでもいろいろな形で行っておりますので、そういった形で進めていきたいと思ってあります。","voiceIndex":197,"id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、八潮でも、住民から発意があって検討してきた事例があると思うのですけれども、それで公募で２７人の方が参加したということがありますけれども、まだこれも開かれたというところまではいきませんので、まだ不十分な部分はありますけれども、そういった形で、やはり住民の参加を位置づけていくといったことが必要だと思いますけれども、改めて伺います。","respondent":"柏原企画調整課長","answer":"今、例示いただいた八潮の部分につきまして、八潮のまちづくりの検討委員会のことだったかどうかというところは、私も今、ご質問を聞いていてわからない部分はあったのですが、さまざま地域の特性等々があります。それから、その施設の立地の条件であったり、諸々あります。","voiceIndex":199,"id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"地域の実情に応じてということで、八潮の事例もぜひ、知らないということでしたので、調べてみていただきたいと思いますけれども、区の考えを持ってやるということも、私はそういうこともあるかとは思いますけれども、やはりそれは、がちがちに決めた段階で住民の方に意見を聞くのではなくて、基本方針を決めた段階で意見を伺っていくといった姿勢が必要だと思います。","respondent":"柏原企画調整課長","answer":"それで、地元の方のご意見も、いろいろな段階、段階において、お話を聞きながら進めているです。それは、アンケートの手法であったり、さまざまな手法、チャネルを使ってやってきているです。","voiceIndex":201,"id":"exchange-086"},{"speaker":"のだて委員","kind":"質問・要望","question":"荏原第四中学校だけでなくて、今、林試の森の隣の公有地、５,０００平米買うということも決まっております。ここでもいろいろな要望が出されていると思いますので、そういったさまざまなところで、計画段階から住民の方の参加を位置づけていただきたいと思いますけれども、これからの進め方について、改めてになるかもしれませんが、伺いたいと思います。","respondent":"柏原企画調整課長","answer":"これからも、そういった形で、さまざまなご意見で、まずは区の考え方というのはしっかり持たないと、これはいろいろな判断というところで、いろいろなぶれがあってもいけませんので、そういうものを持ちながら、しっかりご意見を伺いながら進めていきたいといったものです。","voiceIndex":203,"id":"exchange-087"},{"speaker":"本多委員","kind":"質問","question":"１６７ページの元号改正対応経費と、同じく１６７ページの、総務課で行う企業・大学等との連携促進、大学との協働の推進について質問いたします。これに対応していく中で、まず事務的にどういったものがあるのか、種類等を教えてください。それとスケジュール、それと経費負担のあり方、予算では４,４７０万円ですけれども、概要、内訳をお知らせください。","respondent":"仁平情報推進課長","answer":"私から元号の改正の対応ということでお答えします。こちらの経費の内容ですけれども、区で抱えております各業務システムがあります。","voiceIndex":206,"id":"exchange-088"},{"speaker":"本多委員","kind":"質問","question":"主にシステム改修ということだと思うのですが、それと、あと、例えば戸籍住民課のペーパーの関係とか、いろいろな、諸々全庁的に、ペーパー等が全部変わると思うのですが、そういった経費が全部、入ってくるのか。その辺だけ教えてください。","respondent":"秋山財政課長","answer":"紙類につきましては、所管がそれぞれの事務用経費の中で、その年々で使う分を予算で持っておりますので、その辺は各所管の中に入っているです。","voiceIndex":208,"id":"exchange-089"},{"speaker":"本多委員","kind":"質問","question":"よくわかりました。カレンダー業界等で、今年の夏の公表でも２０１９年のカレンダー製作には間に合わないと言われておりましたけれども、区としての手応えといいますか、その辺の関連についてはどのように感じ取っているのかだけ教えてください。","respondent":"秋山財政課長","answer":"区としては、今回の元号対応というのは、平成のときも経験はしていますけれども、事前にわかっているというところで、平成のときよりは、きっちり進められるのかというところで考えているものです。","voiceIndex":210,"id":"exchange-090"},{"speaker":"本多委員","kind":"質問・要望","question":"やはり、その１年ぐらい前から言うということで、これは都の１つの例なのですけれども、品川区もいろいろなさまざまな行事がありますが、例えば何かそれに準ずるようなことというのは、特になければないでいいのですが、そういった、早目、早目に、何か手を打っていったほうがいいのではないかとも思いますので、少し確認だけさせていただきたいと思います。","respondent":"柏原企画調整課長","answer":"区も当然、そういったところでのイベント等には影響が出るものも出てくると思いますので、具体的に今、何というのはないのですけれども、そういったところに影響がないような形で早目の対応というのは、全庁にアナウンスはしていきたいと思ってあります。","voiceIndex":212,"id":"exchange-091"},{"speaker":"本多委員","kind":"質問","question":"諸々の行事を、早目、早目に決めていただいたほうがいいかと少し思いました。最後に元号のことについて、公表は官房長官が行うと一般的に知られるところなのですけれども、新しい元号について最新情報を何かつかんでいれば、教えてください。例えば、我々が知るところだと、ハ行はないのではないかとか、そういう一般的なことは認識しておりますが、何かそれ以上の最新情報をつかんでいれば教えてください。","respondent":"仁平情報推進課長","answer":"昭和から平成のときも、これは非常に、何になるかによって、業界のほうも自治体のほうも大変でした。次にどんなものかというのは、今のところ、何の情報もつかんでおりません。","voiceIndex":214,"id":"exchange-092"},{"speaker":"本多委員","kind":"質問","question":"人生１００年時代における社会人の学び直しを含め、大学や専修学校における教育・人材育成を拡充ということで、新しいと思ったところは、６年間一貫制教育による光学情報大学院の創設、４年・２年の６年間の一貫制ですとか、学科縦割り行動の抜本的見直し等、新しいと思ったのですが、あと、人材力の強化により経済成長の実現をという取組みについては、品川区はこれまで着眼してきたものかと思って。","respondent":"米田総務課長","answer":"今回、総務課では、今、４つの大学ですが、立正大学、星薬科大学、清泉女子大学、昭和大学の４大学が一堂に会しまして、もう少し大学間の連携も含めた、区と地域との協働ということが模索できないかというようなことで、この１年間、ちょうど１年前ぐらいに総会を行って。","voiceIndex":216,"id":"exchange-093"},{"speaker":"本多委員","kind":"質問","question":"それぞれの部署と連携ということで答弁いただきましたので、そこに入ると思うのですが、商業・ものづくり課との連携も、方向的に進めていくと思えばいいのですか。","respondent":"米田総務課長","answer":"お尋ねのような形での連携というものも入ってくるかと思いますが、今のところ、大学の事務局では、同地域に大学の知的部門の地域貢献ということで、どういうふうに地域に還元していくかというようなことをやっておったり、それから学生ということでは、学生ならではの。","voiceIndex":218,"id":"exchange-094"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひ充実できるように進めていただきたいと思います。少し時間があるので、一つ、二つ、聞いていきます。大体、土曜日・日曜日または祝日だと思うのですが、土日、いろんな区内の各地域の行事ですとか、祝日においても、例えば２月１１日は建国記念日であって、さまざまな行事があったり、そういう行事と重ならないように、日にちの設定にあたっては調整していただきたいと思います。いかがでしょうか。","respondent":"伊崎地域活動課長","answer":"先ほど都市計画課長からご答弁申し上げましたとおり、平成３１年３月が、今のところの予定となっておりまして、まだ細かい開通の日程が提示されておりませんが、区といたしましては、今、委員ご指摘のように。","voiceIndex":220,"id":"exchange-095"},{"speaker":"本多委員","kind":"質問・要望","question":"よろしくお願いします。先ほどの図書館に関連して少し発言しますが、大崎駅西口図書取次施設、愛称、おおさきこども図書室。２月１９日でしたか、オープンされまして、こういったものを、ぜひ多くの方に利用していただけるようなＰＲを進めていただきたいと思います。やはり、よく見て、木を見て森を見ずということにならないようにＰＲをしていただきたい。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"１５９ページの全庁共通プロジェクトの中のＢＰＲ、働き方改革です。これは、課題があって、そして目標があって、将来の姿があるかと思いますが、それについてお伺いします。小さいぬいぐるみがすごくいいと思って、これを販売しないのか、使わないのか、非常にもったいないと思っているのですが、この３キャラクターの活躍の場をたくさんつくってほしいと思いますが、いかがでしょうか。","respondent":"柏原企画調整課長、黒田人事課長、小川オリンピック・パラリンピック準備課長、仁平情報推進課長","answer":"それで、最終的には、そういったところでの、例えば超過勤務の削減だったり、そういう浮いた事業の部分を、別の事業に人のパワーを回すだとか。幹部職員につきましては、部長級、統括課長級、課長級を合わせまして２４.１％が、幹部職員の中での女性の割合となっております。今後、区民の方々にも多く手にとっていただけるように工夫してまいりたいと思いますが、現在のところ、販売ということは考えてございません。本当にそれがその影響だけなのかも含めまして、引き続き検討してまいります。","voiceIndex":224,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"その辺をどういうふうに想定しながら考えているのか、それは全く考えていないのかということです。それと、女性幹部職員２４％が、多いのか、少ないのかというところがありますが、今後、増やしていこうとしているのかをお聞きしたいと思います。欲しいと思います。露出を高くすれば、やはり欲しいという方々はいらっしゃると思うので、そこの露出度を高めていただきたいということで要望しておきます。","respondent":"黒田人事課長、仁平情報推進課長","answer":"職員定数のあり方ですが、公務員がやるべき、そして対人で行うべきという業務を見定めて、これからも人員の定数については考えてまいりたいと考えています。商店街等関係の所管と検討しながら、支援を考えていきたいと思います。","voiceIndex":229,"id":"exchange-098"},{"speaker":"塚本委員","kind":"質問","question":"やはり、場所によって、つながりにくい、あるいは、つながっても非常にストレスがあって利用しにくいという声は聞いておりまして、今、まず最初にもう少し詳しくお伺いしたいのですけれども、これは平成２９年度末で３３カ所、既に設置されておりますが、ここについて、例えば各設置場所の設置ポイントというか設置場所ごとに、有効な接続範囲や。","respondent":"仁平情報推進課長","answer":"それと、範囲なのですが、電波ですので、どこまでというところは難しいのですけれども、一応、スペック上は、直線距離なのですけれども、７０メートルから８０メートルの範囲。","voiceIndex":233,"id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"これは、どのような形でそれぞれのアクセスポイントで利用されているのか。利用状況ですね。こういうものが多分、月々なのか毎日なのかわかりませんが、見られるようになっているのではないかと思うのですけれども、そういうものから、現状のキャパシティーというか、能力が足らないというようなところが出てきているというのを見ていらっしゃるのかどうか、お伺いしたいと思います。","respondent":"仁平情報推進課長","answer":"ただ、例えば日中のお昼の時間帯の２時間ですと、月当たり全体で４,５００件から５,０００件ぐらいのアクセスになっているという、日中が少し高いという記録は把握しております。","voiceIndex":235,"id":"exchange-100"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。その上で、各サイネージごとに、個別の端末というのか、パネルごとにというのでしょうか、個別の情報の発信というのもそれぞれ可能な部分もあるのかと思いますが、どういうものを個別にやろうとしているのかというのを簡単にお願いしたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"サイネージの個別の情報発信についてのお尋ねです。例えばですけれども、地域センターで町会・自治会の行事を表示させるとか、体育館ではスポーツイベントに関しての、そこでやるイベントのご紹介であるとか、そういう使い方を想定しております。","voiceIndex":237,"id":"exchange-101"},{"speaker":"塚本委員","kind":"質問","question":"そういった意味では、これは観光のほうに聞きたいのですけれども、インフラ等のネットワーク環境がないところで、こういう新しい２次元コードによって直接情報を収集できるというようなものを使って、うまく情報発信のツールとして活用する考えもありなのかと思いますけれども、それぞれご見解をお伺いしたいと思います。","respondent":"木村報道・プロモーション担当課長、鈴木文化観光課長","answer":"新しい技術ですので、私どもも具体的な活用につきまして、関係課を含めまして、情報収集・研究にこれから努めてまいりたいと思います。観光に関しましても、ご指摘のような効果があると思いますので、研究しつつ導入したいと思います。","voiceIndex":239,"id":"exchange-102"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、１７７ページ、児童参加地域事業補助について、まず、これはどういった内容なのでしょうか。以前も教育委員会で、地域の子どもたち、児童が地域に参加するというような取組みをしていたと思いますが、その辺との違いというか、こちらに変わったのか、どういったところなのか、また事業内容をお知らせください。１８３ページ、自動通話録音機購入。","respondent":"伊崎地域活動課長、菅生活安全担当課長","answer":"具体的には、町会・自治会が実施する事業の経費の補助をするということで、率としては４分の３の補助で、上限は１０万円ということで、今、考えております。自動通話録音機の関係です。これは、平成２８年度の分につきましては、もう全て設置しています。","voiceIndex":243,"id":"exchange-103"},{"speaker":"大倉委員","kind":"質問・要望","question":"自動通話録音機なのですが、かなり需要があって、私もぜひさらに推進していっていただきたいと思うのですが、今少しお話にもあった、故障というか、不具合というか、私も以前、警視庁の自動録音機を設置するところに立ち合わせていただいたときに、やはりご家庭の録音機を設置したところ、不具合でうまく設置が、その日できなくて、その後、その方が、「もう、わからないからいい」ということで。","respondent":"菅生活安全担当課長","answer":"そういったところにつきましては、これは個人負担になってしまう場合もありますけれども、工事をしていただくとか、あるいは電話回線を変えていただく、あるいは自動通話録音機をつけられないのであれば。","voiceIndex":246,"id":"exchange-104"},{"speaker":"大倉委員","kind":"質問","question":"１７３ページの庁舎整備費について伺いたいのですが、今、庁舎の２階の駐車場に警備員の方が配置されていると思いますが、例えば何か接触事故が起きてしまった、トラブルが起きてしまった、災害が起きてしまったというようなときの対応マニュアルみたいなものがあるのでしょうか。","respondent":"立川経理課長","answer":"庁舎の駐車場の警備につきましては、現在、委託で実施しています。いわゆる事故等トラブルが起こった場合の手順については定めておりまして、まずは、平日ですと庁舎管理係に連絡をいただく。","voiceIndex":248,"id":"exchange-105"},{"speaker":"大倉委員","kind":"質問","question":"マニュアルを整備して、いろいろ連絡をとりながら、しっかりやっているということだと思うのですが、２階だけに限らず、防災センター側の駐車場も含め、そうした事故への対応というところで、以前、接触事故が起きた際に、接触したところに警備員はもちろんいたのですが、その後、接触した当事者のほうが少し区のほうの予定があって、一回ちょっと離れてしまって。","respondent":"立川経理課長","answer":"警備も委託しているのですけれども、運営のほうも現在、タイムズ２４に委託しておりまして、それで必要なところには防犯カメラを設置するということになっております。","voiceIndex":250,"id":"exchange-106"},{"speaker":"大倉委員","kind":"質問","question":"設置をしているということでいいのでしょうか。設置しているかどうか、まず教えてください。","respondent":"立川経理課長","answer":"駐車場の隅々まで設置しているわけではございません。主に出入口の付近については設置して、やはり、いわゆるバーを折って逃げられるというようなことがありますので、その辺については事業者の判断で実施しています。","voiceIndex":252,"id":"exchange-107"},{"speaker":"渡辺委員","kind":"質問","question":"初めに、まず少年少女スポーツのところ。よく学校等に顕彰幕。というのは、体力低下という課題１つをとってみても、今、運動する子が減っている。そういうこともある。そういう意味で、少年少女スポーツをますます活発にするための手段として、顕彰幕で品川区ナンバーワンだとか、この中身の規定などは各現場の方々と相談だと思うのですが、１つのアイデアとして取り入れられたらどうかと思うので伺います。","respondent":"大関教育総合支援センター長","answer":"各学校は子どもたちの活躍を学校のホームページや便り等で地域の方にもご案内していますが、今ご提案いただいたような顕彰幕等についても、大きな大会以外にさまざまな工夫ができないかは、今後、検討してまいりたいと思います。","voiceIndex":257,"id":"exchange-108"},{"speaker":"渡辺委員","kind":"確認","question":"少し伝わりにくい部分もあるので、一応、確認のため。部活動はいろいろな大会がわかりやすくある。地域の少年少女スポーツという観点で、あれもこれもと言うつもりは全くなくて、どこか区に、例えば連盟、種目だったらその種目の中で一番、格式というか歴史を含めて高いもの、そういう観点でどうかと思いましたので、その辺でまたご検討いただければと思います。","respondent":"池田スポーツ推進課長","answer":"ですので、今、委員からのご提案につきましては、区長杯という一番権威のあるものに対して顕彰幕ということで、関係各課とこれから検討していきたいと思います。","voiceIndex":259,"id":"exchange-109"},{"speaker":"渡辺委員","kind":"質問","question":"力強いご答弁、ありがとうございました。次に、生活安全関係の事業のところを伺います。そのときに、反応が、やはりすごく身近なことなので、うなずいていらしたり質問も出たりという光景をよく見ます。そういう中で、現在、品川区全体といったらいいのですか、そういう犯罪防止も含めたり、被害の状況、取組みのような傾向を、簡単にご説明いただければと思います。","respondent":"菅生活安全担当課長","answer":"町会、それから商店街の皆様を中心に、防犯カメラを積極的につけていただいて、設置していただいているです。町会を中心としました街頭防犯パトロール活動といったものも非常に盛んですので、そういったところが特徴的だと考えております。","voiceIndex":261,"id":"exchange-110"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これもやはり口づてには伝わりますし、「うちのほうにもあったらいい」というお声を聞いたので、まず効果のところを伺いたいと思います。それは、防犯のまちづくりという趣旨から考えたときに、他地域での展開の可能性をどう考えるか。それは多分、ここは交番だった経緯があるにせよ、同じ趣旨のことが求められるエリアというのはかなりあるかと思います。この２点を教えてください。","respondent":"菅生活安全担当課長","answer":"ほかのところの展開ですけれども、今のところ、品川区内の各警察署で、例えば交番が廃止になるとか、そういった話があれば、またそういったところは今後、荏原町安全安心ステーションを、見本としまして、またそれは検討していきたいと考えております。","voiceIndex":263,"id":"exchange-111"},{"speaker":"渡辺委員","kind":"質問","question":"こういうのが１つあったら安心だというのを何人かに伺ったので、ぜひ検討課題に常に挙げていただければと思います。この２点をあわせて伺いたいと思います。これが答えづらかったらあれなのですが、おそらく、これがあることで大分防げたのではないかと思われる、そんな話題といったらいいのですか、シミュレーションみたいなものがあるのかどうか、教えてください。","respondent":"菅生活安全担当課長","answer":"パトロール隊も、朝から夜までそれぞれ区内をパトロールしておりますので、そういう、見せる警戒といいますか、そういった活動をしていることも１つの抑止効果になっているのではないかと考えているところです。","voiceIndex":265,"id":"exchange-112"},{"speaker":"渡辺委員","kind":"質問","question":"コストもかかるだろうと。さすが、品川区と言われる。人数を前に伺ったときだと１万人余、１万幾つかと思いますが、主に保護者の方、それと地域の協力者だと伺っています。そういう意味で、望ましい事業者の方には、きちんと依頼がいっているのかどうか。おそらく地域で配達業だとか、郵便も含めて宅配業だとか、こういうところはどんな展開がなされているのか教えてください。","respondent":"菅生活安全担当課長","answer":"これは、先ほどお話がありました、例えば配達をしている業者ですとか、あるいは金融機関といった業者に、区内を配達等で巡回する際に見守り活動をしていただくということで、この事業をしておりますので、こちらの企業につきましては。","voiceIndex":267,"id":"exchange-113"},{"speaker":"渡辺委員","kind":"質問","question":"システムはどうであれ、ゴールはやはり見守りに多くの方がかかわっていただけることという中で、おそらくマッチングの話になるかと思います。続いて、コミュニティＦＭのことを伺います。それぞれの方法に長所・短所がある中で、やはり情報を届けるのは、できることは何でもするべき。その辺をどう考えているのかを、まず教えてください。どのように展開されていくのか、教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"段階的なものに関しましては、実際にまずは４月以降、秋ごろ開局を想定しておりますけれども、そこでまずやってみて、実際にいろいろ反応、ご意見をお伺いしながら、いい番組づくりに努めてまいりたいと考えております。","voiceIndex":269,"id":"exchange-114"},{"speaker":"渡辺委員","kind":"質問","question":"区民サービスにも大きく膨らんでいく要素があるかと思いますので、今のところ、あれもやれ、これもやれという意味ではなくて、段階的にしっかりと施策が膨らんでいけばいいという思いで伺いました。オリンピック・パラリンピックのことを最後に伺います。もう一点、あと工事現場等で３競技の紹介。今後ぜひ、このバージョンアップ等を含めて展開すべきと思いますが、ご見解をお知らせください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"イベント等にご協力いただく予定です。横断幕での告知等は、風を通す形の横断幕を工夫して作成いたしまして、公園等に設置してきたものです。今後もそういったイベントの告知等には活用していくとともに、また工事現場での壁の活用等も積極的に考えてまいりたいと思います。","voiceIndex":271,"id":"exchange-115"},{"speaker":"浅野委員","kind":"質問","question":"時間があればコンビニ交付経費、１９９ページ、質問します。このような、既に開局しているＦＭ局の取組みなどを参考にしていただきながら、品川区としての特色のあるコミュニティＦＭにしていただければと思いますが、いかがでしょうか。このコミュニティＦＭは事業継続計画ですか。こちらは検討されているのか、既にできているのか、教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"事業継続計画につきましては、まだ正直、そこまで考えているところではございません。","voiceIndex":274,"id":"exchange-116"},{"speaker":"浅野委員","kind":"質問","question":"しながわＷｉ－Ｆｉスポット事業ですけれども、先ほども質問が出ておりましたが、どう見ても私の住んでいるエリアは、このＷｉ－Ｆｉスポットというのはあまりないというか、ほとんどないと考えています。この件に関しまして、今後の荏原地域のフリーＷｉ－Ｆｉの取組みについて教えてください。","respondent":"仁平情報推進課長","answer":"来年度の計画といたしましては、荏原地区ですと、荏原文化センター、旗の台文化センターほか、例えば平塚橋のゆうゆうプラザなどへも順次整備を進めていく考えでおります。","voiceIndex":276,"id":"exchange-117"},{"speaker":"浅野委員","kind":"質問","question":"しながわテレビ・プッシュ普及促進経費について伺います。地震の情報も音声で入ってくるということで、これもなかなか有効かと思いますが、１月末で加入者が２,２００件程度と聞いております。こんなものなのかと思ってしまったのですけれども、少し機器が高い部分もあるかと思いますけれども、こちらのほう、どのような形で今後進めていくのか、区の見解をお伺いします。","respondent":"柏原企画調整課長","answer":"全品川区の世帯は２０万世帯ありますので、そこから比較するとというところはありますが、今後もこういった形で普及促進に努めたいと考えています。","voiceIndex":278,"id":"exchange-118"},{"speaker":"浅野委員","kind":"質問","question":"コンビニ交付経費について質問します。窓口での交付もあると思いますし、またコンビニで交付を得るという方もおられると思いますけれども、区として、それぞれのかかる経費というのでしょうか、窓口での交付経費とコンビニでの交付の経費にどのぐらいの差異があるのか。１件当たりの経費、それぞれについて教えてください。","respondent":"提坂戸籍住民課長","answer":"今のところ、窓口交付のほうがコストが低いということになっていますけれども、コンビニ交付が進むことによって、さらにコンビニ交付の１通当たりのコストが下がると考えていますので、マイナンバーカードの普及に力を入れてまいります。","voiceIndex":280,"id":"exchange-119"},{"speaker":"浅野委員","kind":"意見","question":"ちなみに、さいたま市ですけれども、今度、証明書発行費用、窓口ですけれども１,２００円、コンビニ交付は７１０円という数字が出ていましたので、品川区とは当然、いろいろ違いはあるかと思いますけれども、やはりこれだけの経費がかかっているのだということを改めて感じました。庁舎内にも、コンビニ交付の機械が入ればうれしいと考えていますので、ぜひとも推進をお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":282,"id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それと、あと２つ目は、意見の提出期間についてなのですが、行政手続法の第３９条では、公示の日から起算して３０日以上でなければならないと書かれているのですけれども、品川区の要綱では、広報紙に出てから３０日以内と、少なくとも１４日を確保するということになっていますけれども、なぜ３０日以上ではなくて３０日以内としたのかについても伺いたいと思います。","respondent":"中元広報広聴課長","answer":"２点目の意見提出期間のことですが、こちらは、やはり意見を提出された後に計画案をつくるというところが本筋のところというところもございまして、全体のスケジュールの中で、行政計画につきまして最大３０日間を確保させていただければ、計画案を理解し。","voiceIndex":284,"id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"私は、行政手続法の改正から、この要綱がつくられたのかという、このことを確認したかったので、その点、改めてお願いしたいのと、３０日あればということなのですけれども、最低１４日ということなので、３０日ないこともたくさんありますし、私は、広報に出て初めて本案を手に入れて、それから読み込んで１４日から３０日というのでは、あまりにも短過ぎて。","respondent":"中元広報広聴課長","answer":"広報広聴課としましても、なるべく皆さんに意見を出していただきたいという姿勢はそのとおりですが、やはり案件によりまして対象となる方々がそれぞれ異なりますし、やはり興味がある、またこのパブリックコメントに意見をおっしゃらなくても、所管の窓口でご要望を伺ったり。","voiceIndex":286,"id":"exchange-122"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、こういう中身が品川区でも入っていたならば、今定例会で出ている民泊の条例についても、パブリックコメントなどで区民の意見を聴取して、そして、それを反映したものにできるのではなかったのかという思いがしているのですけれども、ぜひそういう点では、パブリックコメント手続、行政手続法の趣旨にのっとった形での、そういう対象も拡大していただきたいと思うのですけれども、いかがでしょうか。","respondent":"中元広報広聴課長","answer":"先ほど申し上げましたが、各課におきましての判断のもと、適切なものをパブリックコメントの対象としていると私は認識しております。","voiceIndex":288,"id":"exchange-123"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"パブリックコメントの前に、私は説明会をやってほしいということで、さまざま、ずっとこれを求め続けてきているのですけれども、区民の大きな関心のある介護保険の事業計画策定のたびに、これをやってほしいと要望していますし、今回の障害福祉計画についても説明会をやってほしいという、団体の皆さんからもありましたし、そういうことを議会で求めてきたのですけれども、もう絶対にやらないという。","respondent":"中元広報広聴課長","answer":"それは、区として決めていることではございません。その案件によりまして、そこのさまざまな事業におきまして、必要があれば、その対象の方々にお声がけをして、さまざまな説明会がいろいろな事業で行われていると認識しています。","voiceIndex":290,"id":"exchange-124"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この考え方というのは、公平性の観点から説明会はやるべきではないという考え方になるということです。これは大変重大な問題だと思うのですけれども、それでいいのでしょうか。例えば、今回の障害福祉計画に対しては、港区は１０回やっています。こういう立場こそ必要ではないかと思うのですが、いかがでしょうか。","respondent":"中元広報広聴課長","answer":"それは、やはり各区の事業の進め方でありますとか地域の特性によっても違ってくるかと思います。今回の計画に関しましては、パブリックコメントでも大変たくさんの意見をいただけているところですし、十分にその辺の説明は尽くされているものと考えております。","voiceIndex":292,"id":"exchange-125"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１月２３日の行財政改革特別委員会で、施設のにぎわい創出、防災機能強化を軸に進めていくというお話があったのですけれども、これは具体的になかなかイメージがつかなくて、地域交流スペースが、イベントなど、さまざまな人々が利用できる施設、広場などの多目的の交流空間とあるのですけれども、これは、イベントというのはどんなイベントなのか、またにぎわいの創出というふうな施設。","respondent":"柏原企画調整課長","answer":"ということで、集会施設的な機能もそうですし、そういったたくさん人が集まれるようなものを検討したいというものです。検討委員会とはどういったものを指しているかわかりませんけれども、今、庁内の検討を進めているというものです。","voiceIndex":294,"id":"exchange-126"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、まず最初に、外国人観光客誘致事業、海外日本博出店というところで、応援をする気で質問します。ぜひ、もっとやってほしいという思いです。それから、今までいろいろ行かれて、現在、成果というか、いろいろ例えばガイドブックへ取り上げられたとか、あとはネット検索なども、そういうところでの効果もあると思うのですけれども、そういうところを少し教えていただきたい。","respondent":"鈴木文化観光課長","answer":"海外日本博等でのＰＲ事業ですが、まず出展している国です。平成２９年度は、ベトナム、フランス、タイ、台湾の４カ国に出展しております。平成３０年度につきましては、現在の時点では、ベトナム、台湾、タイを想定しています。","voiceIndex":297,"id":"exchange-127"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"はネットで検索する。それでも自分たちの、自国のネットを検索して、どこかの国を、どういうところがあるのかとなるわけです。旅行代理店も、では品川区に行きましょうとなるのかと思うと、なかなか大変な面もありますけれども、そうだからといって負けているわけにはいかないので、絶対強化をしていただきたいと思うのだけど、その辺の考え方も再度お聞きします。","respondent":"鈴木文化観光課長","answer":"今後もしっかりと取り組みたいと考えております。","voiceIndex":299,"id":"exchange-128"},{"speaker":"石田（秀）委員","kind":"質問","question":"次に１８１ページ、オリンピック・パラリンピックで少しだけお伺いしたいと思います。先ほど、鈴木真澄委員からも少しあったのですけれども、オリンピックをやっているとき、ではその周りでどういうイベントを打つかというのも非常に大切なことだと思っています。今度、私も４月７日・８日で、広島市民球場跡地のアーバンスポーツ大会に行ってきます。そういうことは可能なのでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、品川区といたしましては、会場も持っておりますし、大会会場周辺でにぎわいを創出し、また荏原周辺のほうにも誘導していきたいと考えておりますので、そのやり方については、まだまだ検討する余地があるかです。","voiceIndex":301,"id":"exchange-129"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えば、品川区で区民の人が参加してくれて、文化祭をやるとか、そういうのはもう今やっているのだけど、もっと外国人観光客が品川区に来てくれるようなイベントとか、いろんな、日本中の人が来てくれる形のものを組んでいくのであれば、もう場所も含めて、もっとやっていかないと間に合わないような気がするのですけれど、この辺の感覚というのはどうなのでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういった意味では、国際都市品川ということで、さまざまな観戦客ですとかスポーツのチームが来るというところで、先手を打ってやっているところです。まさに大会期間中の部分につきましては、２年前ですので、もう少し検討させていただきたいと思います。","voiceIndex":303,"id":"exchange-130"},{"speaker":"石田（秀）委員","kind":"質問","question":"それと、１７７ページのトップランナー町会・自治会支援と児童参加地域事業補助と、先ほど少しお話が出たのですけれども、これは、イメージとしてはどういうことを思えばいいのですか。大体、近所の１０町会ぐらいはわかりますけれども、では、それがどういうのがトップなのかなど、わからないですよね。イメージとしたら、どういうのがありなのですか。","respondent":"伊崎地域活動課長","answer":"今ご指摘がありましたように、なかなか、ほかの町会の事業というのを知る機会がないというお声もありますので、今までも事例などのご紹介をしてまいりましたが、例えばトップランナー町会で認定された町会の事例を、事例集などでご紹介するなどして。","voiceIndex":305,"id":"exchange-131"},{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっと伺います。イベント的なのと一生懸命やっているのと、２つ例を言います。これはまさに私の町会なのですけれども、町会長の意地みたいなのがあって、８つの水利を使って、年に９回、１回は子どもたちを呼んでやるので、年に９回、スタンドパイプ訓練をやっています。そんなにはやっていない。こういうのは結構、これは２つともトップクラスに珍しい事業なのでしょうか。基準がよくわからない。","respondent":"伊崎地域活動課長","answer":"平成３０年度予算ですので、来年度の予算ですが、来年度の単年度ということでは考えておりませんので、何年かやっていく中で、そういった事例が区の中で共有されていけばいいと考えています。","voiceIndex":307,"id":"exchange-132"},{"speaker":"石田（秀）委員","kind":"質問","question":"これは、ここでやめておきます。最後に１つだけ、先ほど１８５ページ、明治維新の話がありました。山内容堂公の墓が品川区にはあります。区も、山内家に言っていただいているのも、もちろんそのとおりで、個人のものですから、それはそれで。だけど、今、明治維新、こうなったときに、一言ぐらい、知事や県に、品川区からやってと言ってもいいような気がするのですけど、どうかという感じです。","respondent":"品川庶務課長","answer":"山内容堂公の墓ですけれども、基本的には所有者が管理することとなっております。これまで立会小学校、それから区の職員等も、清掃等を進めてまいりましたけれども、今回、明治維新１５０周年ということで、いい機会ですので、高知県等と相談していきたいと考えております。","voiceIndex":309,"id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問","question":"１５９ページの予算関係管理費、１８９ページの総合区民会館運営費についてお伺いします。時間があればオリンピック・パラリンピックについて。先に、まずは予算関係管理費ですけれども、ホームページに、平成３０年度予算編成に関する基本方針について、いわゆる依命通達が出されました。そして、予算編成日程も掲載されて、拝見させていただきました。","respondent":"秋山財政課長","answer":"年度当初に執行の通知を出し、それから夏に予算編成の通知を出して、各課からの予算要求を受けているわけですけれども、その中の要求で、課題ということでおっしゃられたのですけれども、課題というよりも、私どもとしては、それが実情に合っているのか。","voiceIndex":312,"id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"提案","question":"今お話があったような観点で、査定というか、そういうものを見られていると。予算編成基本方針の中にも、新規事業に関しては積極的になど、さまざまな、何というのですか、指示が出ているのですが、今お話があったように、そのような形で、見積もりについてはそちらの課のほうで、何といいますか、査定という言葉が正しいかどうかはあれですけれども、中身を見ていっているという事実があると。","respondent":"秋山財政課長","answer":"左側に前々年度決算額があります。それと、昨年度の予算額の差であるとか、その辺のものを入れていけば、決算額にどう対応したのかというのがわかるのではないかということで、今、想定はしています。","voiceIndex":314,"id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問","question":"いろいろな使い方ができるということであります。そうすると、議会のほうにこうしていただいたものが、今、空欄になっているのですが、これと同じものが職員の方の手元にあるということでよろしいでしょうか。","respondent":"秋山財政課長","answer":"そのとおりです。","voiceIndex":316,"id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、先ほど、今、私どもがいただいている、ここが空欄になっている見積書が職員の方の手元にもあるというふうなお話をいただきました。そして、査定もしっかりとされている。そして、その要求額が、最終的に予算として、こういう形で出てきたということで、しっかりとした見積もりとしっかりとした査定が、このように公開に耐え得るものだと思うのですが、その点についてはいかがでしょうか。","respondent":"秋山財政課長","answer":"この要求額については、いろいろとご答弁をしていますけれども、わかりやすく説明するために必要だということも理解はしておりますけれども、いわゆる予算の編成過程というのを、非常に多くの要因や情報などがありまして。","voiceIndex":318,"id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この件について、また機会を改めてお尋ねしたいと思いますが、先ほどいただいた見積書の空欄に入ることが可能なわけですから、本来のいわゆる編成過程の可視化を、改めて求めてまいります。これは質問ではなくて、最後は、いただきたいということで要望しておきます。では次です。","respondent":"鈴木文化観光課長","answer":"ご質問のＵＤサポートシステムですが、これは昨年３月に文化振興事業団で利用者の方の便宜を向上させたり、またユニバーサルの対応ということで導入したものです。","voiceIndex":320,"id":"exchange-138"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"こちらを、費用がかかるわけですけれども、文化コミュニティ施設に整備していくということについて要望したいと思います。これは、企業が会議録をとらなくて済む、筆記しなくてもいいということで、民間企業では随分使われているようですが、文化コミュニティ施設に今後導入していくということでいかがでしょうか。","respondent":"鈴木文化観光課長","answer":"区内５つの文化センターでも同様の貸室がありますが、一般的な民間企業中心の利用と違いまして、区民のサークル等の活用が多い、文化活動が多いということもありますので、今後、利用者の方の声を聞いたりしながら、適宜。","voiceIndex":322,"id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"荏原平塚総合区民会館などはきゅりあんと同じような形で有効ではないかと思います。これは要望いたしますが、いかがでしょうか。","respondent":"鈴木文化観光課長","answer":"スクエア荏原の指定管理者と相談しながら進めたいと思います。","voiceIndex":324,"id":"exchange-140"},{"speaker":"若林委員","kind":"提案","question":"別の角度で、今のＩＴのワークショップの採択事業のもう一つが、地域資源マップをつくろうというのがあったと思いますけれども、これはもともと担当所管が、庁内の各課、各所管に、どういうものを協働事業として提案制度で受けつけたらいいかというのを聞きながら出されているわけですけれども、この地域資源マップのようなものの、出してくださいと、テーマとして提案されたのは。","respondent":"遠藤協働・国際担当課長","answer":"今、継続しているものといいますか、以前、事業として採択されたものにつきましては、現在、４件ほどございまして、古いものでありますと、発達障害児の思春期以降の支援や、その部分の自立支援のようなものから、あるいは外国の方と接する機会。","voiceIndex":327,"id":"exchange-141"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、過去、これまでの年月の中で４つぐらいの事業が、継続、根づいていると。要望します。それから、１８５ページのしながわ観光大使館について、先ほど、つる委員からも質問がありましたけれども、音響設備の件。そのような屋外音響のやり方もあると思うのですけれども、こういう観点でお答えいただけたらと思います。","respondent":"鈴木文化観光課長","answer":"ご指摘のありました音響の、どちらかというと設置より使い道のお話だと感じております。ご指摘のありましたように、近隣の方の苦情等もある施設ですので、近隣の方の意見も聞きながら、また効果的な放送設備のあり方も検討する必要があると認識しております。","voiceIndex":329,"id":"exchange-142"},{"speaker":"伊藤委員","kind":"質問","question":"１６３ページのホームページ運営経費等に関連して、それから１６５ページの犯罪被害者支援に関連して質問します。ホームページのほうですけれども、リマーケティング広告というのをご存知でしょうか。これをどうもリマーケティング広告というそうです。勉強しました。そうすることによって、品川区のページにつながっていくと思うのですが、品川区のお考えをお聞かせください。","respondent":"木村報道・プロモーション担当課長","answer":"今のご指摘です。申し訳ございません。私はその技術について存じ上げませんでした。実際に、今ご紹介いただきました使い道、用途を少し積極的に勉強して、これから研究してまいりたいと考えております。","voiceIndex":332,"id":"exchange-143"},{"speaker":"伊藤委員","kind":"質問","question":"どこかのサイトを見たら、その広告が自動的に追いかけてくるというのは、私たちは常日頃感じることではないですか。おそらくほかのサイトでありますから、ここで答えるのは難しいのかもしれないけれども、同じ意味で、しながわ水族館のホームページについても導入していったらいいのではないでしょうかということを指摘させていただいて、それでシナモロールのわくわくしながわタウンというのを見ました。","respondent":"鈴木文化観光課長","answer":"ご質問のありましたシナモンのホームページですが、実際のコンテンツ作成・運用は、サンリオにお願いしていますので、今いただいた意見を踏まえて、より効果的なターゲティングや差別化を図って、効果のあるＰＲをしたいと考えております。","voiceIndex":334,"id":"exchange-144"},{"speaker":"伊藤委員","kind":"質問・要望","question":"わくわくしながわタウンは非常にかわいいのです。第一義的に、それはいいことなのです。だけれども、それを通して、品川区の観光大使であるシナモロールにお仕事をしてもらう。要は、シナモロールを介してその方々につなげていってほしいという思いで質問していますので、ぜひ研究ではなくて、具体的な検討をしていっていただきたいと思うのですが、いかがでしょうか。","respondent":"鈴木文化観光課長","answer":"ご指摘のとおり、せっかくいいツールといいキャラクターに協力いただいていますので、しっかりと活用できるように取り組んでいきたいと考えております。","voiceIndex":336,"id":"exchange-145"},{"speaker":"伊藤委員","kind":"質問","question":"犯罪被害者支援のほうを質問します。これもいろいろ勉強したら、平成１６年に犯罪被害者支援法が成立して、去年、その方針が閣議決定されたということがわかりました。それで、品川区保護司会においても、この準備を進めていただいたわけであります。保護観察所、保護司の方を含む犯罪被害者支援施設への周知に努めるとの表現もありますので、このことに対しての品川区の対応と方針をお聞かせください。","respondent":"中元広報広聴課長","answer":"連絡会議等の事務局を広報広聴課で務めさせていただき、人権啓発課、生活安全担当課と、３課で合同で事務局をやり、それぞれ、人権啓発課が国や都との連絡調整、区民への啓発を行い、生活安全担当課で警察との連絡調整を行うなど、組織的に取り組んでいるところです。","voiceIndex":340,"id":"exchange-146"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、今の協力体制はもちろん正しいのだけれども、せっかくこういう法律が制定されて、しかも安倍内閣のもとでその方針が閣議決定されて、それが今年以降、全国のさまざまな地方自治体も含めて、各地域の保護司会などもそうなのでしょうけれども、これを展開していく。だから、このときにあたって、何というか、もう一歩踏み込んだ具体的な政策を構築していくべきと思うのですが、いかがでしょうか。","respondent":"中元広報広聴課長","answer":"今後につきましても、他の自治体の取組みですとか、そういうものを参考にさせていただきながら検討してまいりたいと思います。","voiceIndex":342,"id":"exchange-147"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"昨年の衆議院選挙でも２１％ぐらいですか、期日前投票されている中で、ぜひ期日前投票所の確保はしていただきたいと思うのですが、期日前投票が増えていくということは、いわゆる選挙公報なども、できる限り早く区民の皆様にお伝えしなければいけないといった中で、改めて配布方法や期間などについて、なるべく早く皆さんにお渡しできるような工夫をとっていただきたいと思います。労務管理についてです。","respondent":"安井選挙管理委員会事務局長、仁平情報推進課長、黒田人事課長","answer":"昨年の都議会議員選挙のときは、虫よけパッチを保育園等でもお配りしたり、児童センターでもお配りしていますので、そういったものを通じた啓発と。特にＡＩの活用になりますと、すごく大きな話になりますし、そういう面を考えますと、まずは、企画部門を中心に。人材派遣を一部導入しておりますが、こちらは、派遣法が改正された際に、抵触日のところで、３年たちますと。","voiceIndex":346,"id":"exchange-148"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"行政だろうが、今、民間企業もどんどんそういうものに取り組んでやっているわけなので、これはぜひ検討を、本会議で、「専門部署を設立してやってほしい」と言ったのですが、そこに関しての答弁はなかったので、ぜひ専門的に、その取組みについては、調査研究を含め、やっていただきたいと思います。これは要望で終わります。ぜひ、きちんとした対応ができるように、よろしくお願いします。","respondent":"木村報道・プロモーション担当課長","answer":"こちらにつきましては、関係課といろいろ協議いたしまして、あと区からの情報提供みたいな部分、災害情報の提供だったりする部分が、うまく疎通、やりとりができるかみたいなところを含めまして、研究を進めてまいりたいと思います。","voiceIndex":350,"id":"exchange-149"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"できるのです。それと、カメラもついていて、テロリストや犯罪者の検知も可能になったのです。なので、オリンピック・パラリンピックも控えているので、これはぜひ本当に検討していただければと思います。いろいろと進んでいます。できる限り経費を削減しながら、いい技術を活用して、民間の力を活用したら、それは協働になるわけですから、これはぜひ取り組んでいただきたいと思います。強く要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":352,"id":"exchange-150"},{"speaker":"南委員","kind":"質問","question":"１７０ページの人事管理に関して伺いたいと思います。保育課の残業時間について、この間、わかったこと。残業最高が１,５１０時間。１人平均、年間３６１時間も残業している。１日で見ると６時間の残業になっているということを、この間、私ども共産党は取り上げてきました。あるいは、しなくても乗り切れていると言えるのか、その点について、まず伺います。","respondent":"黒田人事課長","answer":"そういった意味では、必要な人材については、所要人員として見て配置していくということでありますので、保育課につきましては平成２９年度につきましても職員を増員しておりますし、平成３０年度につきましても、定数条例の中で増員するという形で条例を提案していますので。","voiceIndex":354,"id":"exchange-151"},{"speaker":"南委員","kind":"確認","question":"私は、必要な仕事量に見合った必要な配置は絶対に譲れないところだと思うのです。それで、保育園についてなのですけれども、保育園職員の有給休暇取得については、平成２８年度は平均８日だというふうな答弁もされておりました。それでいいのか、確認をまずしたいと思います。２０日とれるうちの８日というのは、４割。その評価について妥当だと思っているのかどうか。その点についても伺いたいと思います。","respondent":"黒田人事課長","answer":"ただ、保育園ですと、学校の先生もそうなのですが、クラスを持っているような職種につきましては、なかなか休みづらいということも伺っておりますので、そういったことにつきましては所管にも働きかけて。","voiceIndex":356,"id":"exchange-152"},{"speaker":"南委員","kind":"質問","question":"１３日と比較してもやはり少ない。半分以上を捨てているという状況は一刻も早く改善しなければいけないと思うのですけれども、保育園職場の実態アンケートの報告というのが、労働組合で出されていまして、私も見て、改めて驚いたのですけれども、有給休暇取得５日未満。７００人として、６％ですから４２人。９１％の保育園の職員が１０日以下。こういう実態を区はつかんでいるのでしょうか。","respondent":"黒田人事課長","answer":"年休の取得率につきましては職種ごとに把握してございまして、保育園、保育士の方は大体、年８日ぐらいと、これは平成２８年分、平成２９年分も同じぐらいというような状況でつかんでおりますので、そういった中で、所管のほうで。","voiceIndex":358,"id":"exchange-153"},{"speaker":"南委員","kind":"質問・要望","question":"なぜこんな状況になっているのかという認識も、改めて伺いたいのですけれども、私は、保育園というのは、保育需要が高まる中で、今でこそ年に１２カ所とか１６カ所とか増設しておりますけれども、大分前は、保育園の子どもたちの定数を拡大したり弾力化したり、そういう状況で入園に対応していました。あるいは、３・４・５歳は１０４％まで受け入れる。しかし、その間、正規職員は増やしたのでしょうか。","respondent":"黒田人事課長","answer":"保育園の職員の数の推移ですが、平成２２年度の４月１日現在では、正規職員で６６４人でございまして、平成２９年の４月１日につきましては７２７人ということで、保育士につきましては、業務量に応じて採用しておりまして、増やしているような状況です。","voiceIndex":360,"id":"exchange-154"},{"speaker":"南委員","kind":"意見","question":"過酷な状況をどう思うかという認識も聞いたのですけれども、そこを答弁してください。","respondent":"黒田人事課長","answer":"保育園につきましては、開園時間も、いわゆる一般職の勤務時間よりも長いという中で、どうしてもシフトを組んで勤務していただいているという意味では、勤務の体系が、いわゆる庁舎型の職員よりは煩雑だということは認識していますので、そういった中では。","voiceIndex":362,"id":"exchange-155"},{"speaker":"南委員","kind":"質問・要望","question":"課長は、職員を増やしているから支障がないとおっしゃるけれども、先ほど紹介したとおり、年休をとれないではないですか。改めて、その点についてしっかり答えていただきたいと思います。子どもと接する仕事ですから、疲れ果てた顔で、肩を落として働くということはあってはならない。自分がどんなに疲れていても笑顔で接することが求められる仕事なのです。その点についての認識を、改めて伺います。","respondent":"黒田人事課長","answer":"保育園の職員の確保につきましては、国の配置基準がございまして、東京都の加算の基準、さらに区では上乗せで配置しているというところもありますので、そういった中で、適切な職員数については確保して、保育園の運営に支障がないようにという観点で。","voiceIndex":364,"id":"exchange-156"},{"speaker":"南委員","kind":"質問・要望","question":"年休が少ないので何とかしてとっていただきたいなどとおっしゃっていますけれども、現状がとれていないではないですか。９１％の方たちが１０日以下なのです。４月以降の保育園の職員がどのぐらい採用されているのか、そこでどのぐらいの新たな環境、働く職場環境が改善されると区は見ているのか、そこについても伺いたいと思います。","respondent":"黒田人事課長","answer":"平成３０年４月１日付で、まだ採用数は、内定辞退などがありますと変動しますが、保育士の採用数としましては、保育士、児童福祉司と合わせまして、福祉職としまして、一般職員で約５０名、育休任期付の職員で約２０名ということで。","voiceIndex":366,"id":"exchange-157"},{"speaker":"南委員","kind":"質問・要望","question":"よくわからなかったのですけれども、５０人というのは保育士なのですか。そこを確認したいと思います。申請しづらい環境にあるということも、はっきりと出されておりますけれども、そういう劣悪な職場環境が改善されるのかどうか。そこを伺いたいと思います。区政を支えている職員を大事にして、住民の福祉増進にしっかりと取り組むように求めたいと思いますけれども、改めて最後にお願いします。","respondent":"黒田人事課長","answer":"この間、職員は増えておりますので、職員を削減しているという事実はございません。保育士の採用数につきましては、保育資格を持っている職員を合わせて７０名弱、採用するというものです。","voiceIndex":368,"id":"exchange-158"},{"speaker":"南委員","kind":"質問・要望","question":"増えていても、年休もとれない。そういう事態になっているではないですか。そこのところは、もうしっかりと自覚して改善してください。強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":370,"id":"exchange-159"},{"speaker":"こんの委員","kind":"確認","question":"私からは、１６３ページ、デジタルサイネージ設置拡大、１７７ページ、町会・自治会新規事業応援助成、トップランナー町会・自治会支援、児童参加地域事業補助、それから時間がありましたら１９１ページ、歴史館運営費、お伺いしたいと思います。デジタルサイネージの設置拡大ですけれども、これは、まず確認ですけれども、設置の目的、どういったことに使っていくのか。","respondent":"木村報道・プロモーション担当課長","answer":"平成３０年度につきましては、本庁舎の２階部分でありますとか、第二庁舎、第三庁舎、それから地域センターの８カ所、基本的に１２台という形で、平成３０年度は整備してまいる予定です。","voiceIndex":372,"id":"exchange-160"},{"speaker":"こんの委員","kind":"質問","question":"新たな情報媒体ということで設置されると。流す内容としては、地域行事など、また災害時の情報だということですが、この中に、町会の行事なども周知していくという目的があろうかと思いますけれども、そうなると、町会・自治会のお知らせというのは、どのようなお知らせを想定されていらっしゃるのでしょうか。","respondent":"伊崎地域活動課長","answer":"今現在、地域センター５カ所にデジタルサイネージが入っておりまして、それぞれ地域の特性がありますが、連合町会の行事予定を掲示しましたり、あるいは町会の行事の結果をお知らせして、次の行事にお誘いするというような形で、各地域センターで工夫してやっております。","voiceIndex":374,"id":"exchange-161"},{"speaker":"こんの委員","kind":"提案","question":"そうなると、地域センターに設置されるということですが、今後の設置の場所というか考え方を、少し提案とお考えをお聞きしたいわけなのですけれども、要するに、町会・自治会の加入促進も今、図っている中で、町会・自治会のお知らせというのは、地域センターにいらっしゃる方だけでなく、やはりお子さんとともに町会に参加するといった流れも考えると、今後はどうなのでしょう。","respondent":"木村報道・プロモーション担当課長","answer":"今後の設置の予定ですけれども、先ほどは来年度の話をさせていただきましたが、その次は、現在、総合体育館には整備していますが、戸越体育館ですとか、保健センター、文化センター、ゆうゆうプラザを、今のところは想定しています。","voiceIndex":376,"id":"exchange-162"},{"speaker":"こんの委員","kind":"質問","question":"次にまいります。この３つの事業、新規事業としての応援助成、それから児童参加地域事業補助。先ほど、石田秀男委員が、こういう例はどうですかということで質問もありましたが、いわゆる選定基準というのがあるのか、ないのか。全部を、頑張った成果を見てもらいたいぐらいなので、その辺はどういうふうにお考えで、トップランナーという制度を進めようとされているのでしょうか。","respondent":"伊崎地域活動課長","answer":"こういったことは、４月以降の町会長会議で詳細にご説明する予定です。","voiceIndex":378,"id":"exchange-163"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、お知らせまでしてくださって、ありがとうあります。「どれぐらいの際立ったものが必要なの」というようなことになってもいけないと私は感じているところなので、町会の独自のことは評価していただけるような仕組みで、このトップランナーの制度も進めていただきたいと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":380,"id":"exchange-164"},{"speaker":"渡部委員","kind":"質問・要望","question":"１７７ページ、町会支援のあたりで伺うのですけれども、代表質問でもさまざま聞かせていただいていますので、そこのところはそれで、くれぐれもよろしくお願いしますというところなのですけれども、先ほど来、話が出ております、児童参加地域事業がこれから始まるということで、今のご質問の中でも、これから説明していくのだろうというところはわかるのですが、これは例えば。","respondent":"品川庶務課長、遠藤協働・国際担当課長","answer":"子ども地域活動支援事業のスタンプカードですが、約４年ぐらい、事業を今回、やらせていただきました。その中で、約１割程度の町会の方が、この事業に参加してやっていただきました。アメリカ、メイン州のポートランド市の青少年スポーツ交流の件なのですが、今回、７月から８月にかけまして、今のところの予定なのですが、女子のバスケットボールが相互に行き来して交流を深めるというような予定になっております。","voiceIndex":382,"id":"exchange-165"},{"speaker":"渡部委員","kind":"質問・要望","question":"最初、聞いたとき、何なのだろうと思ったのですけれども、わかりやすくて、大体４秒ぐらいの長さでしょうか。意外と、一、二回聞くと、みんな覚えてくれるようなリズムだと思うのです。「わわわわわ！私は頭についています。しながわ １０時をお知らせします」とか、これは何でも使い道があると思うのです。その辺の活用をぜひ検討していただきたいのですが、いかがでしょうか。","respondent":"木村報道・プロモーション担当課長","answer":"サウンドロゴの活用です。現在、幼稚園、保育園、ランチタイムに流していただいているということがあります。それから、今ご指摘いただいたラジオのキャッチですか。大変いいご意見をいただきましたので、ぜひ活用させていただきたいと思います。","voiceIndex":387,"id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1076#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":125068,"voices":390}}]);
